@bp.route("/account-settings", methods=["GET", "POST"])
@login_required
def account_settings():

    # --------------------------------------------------------
    # GET CURRENT USER
    # --------------------------------------------------------

    user = User.query.get(int(current_user.get_id()))

    if not user:
        flash("User account could not be found.", "danger")
        return redirect(url_for("main.logout"))

    # --------------------------------------------------------
    # CHANGE PASSWORD
    # --------------------------------------------------------

    if request.method == "POST":

        current_password = request.form.get(
            "current_password",
            ""
        ).strip()

        new_password = request.form.get(
            "new_password",
            ""
        ).strip()

        confirm_password = request.form.get(
            "confirm_password",
            ""
        ).strip()

        # ----------------------------------------------------
        # REQUIRED FIELDS
        # ----------------------------------------------------

        if not current_password:
            flash(
                "Please enter your current password.",
                "danger"
            )

            return redirect(
                url_for("main.account_settings")
            )

        if not new_password:
            flash(
                "Please enter your new password.",
                "danger"
            )

            return redirect(
                url_for("main.account_settings")
            )

        if not confirm_password:
            flash(
                "Please confirm your new password.",
                "danger"
            )

            return redirect(
                url_for("main.account_settings")
            )

        # ----------------------------------------------------
        # VERIFY CURRENT PASSWORD
        # ----------------------------------------------------

        if not user.check_password(current_password):

            flash(
                "Your current password is incorrect.",
                "danger"
            )

            return redirect(
                url_for("main.account_settings")
            )

        # ----------------------------------------------------
        # NEW PASSWORD MATCH
        # ----------------------------------------------------

        if new_password != confirm_password:

            flash(
                "The new passwords do not match.",
                "danger"
            )

            return redirect(
                url_for("main.account_settings")
            )

        # ----------------------------------------------------
        # PASSWORD LENGTH
        # ----------------------------------------------------

        if len(new_password) < 8:

            flash(
                "Your new password must contain at least 8 characters.",
                "danger"
            )

            return redirect(
                url_for("main.account_settings")
            )

        # ----------------------------------------------------
        # PREVENT SAME PASSWORD
        # ----------------------------------------------------

        if user.check_password(new_password):

            flash(
                "Your new password must be different from your current password.",
                "warning"
            )

            return redirect(
                url_for("main.account_settings")
            )

        # ----------------------------------------------------
        # SET NEW PASSWORD
        # ----------------------------------------------------

        user.set_password(new_password)

        # ----------------------------------------------------
        # UPDATE TIMESTAMP
        # ----------------------------------------------------

        user.updated_at = datetime.utcnow()

        # ----------------------------------------------------
        # SAVE
        # ----------------------------------------------------

        try:

            db.session.commit()

            flash(
                "Your password has been changed successfully.",
                "success"
            )

        except Exception as e:

            db.session.rollback()

            current_app.logger.exception(
                "Password change failed for user ID %s: %s",
                user.id,
                e
            )

            flash(
                "Unable to change your password. Please try again.",
                "danger"
            )

        return redirect(
            url_for("main.account_settings")
        )

    # --------------------------------------------------------
    # GET REQUEST
    # --------------------------------------------------------

    return render_template(
        "backend/pages/users/account_settings.html",
        user=user
    )



# ============================================================
# ALL USERS
# ============================================================

@bp.route("/all-users")
@login_required
def all_users():

    # ========================================================
    # SUPERADMIN ONLY
    # ========================================================

    if not current_user.is_authenticated:
        flash(
            "Authentication required.",
            "danger"
        )
        return redirect(
            url_for("main.login")
        )

    if not current_user.is_superadmin():
        flash(
            "You do not have permission to access all users.",
            "danger"
        )
        return redirect(
            url_for("main.dashboard")
        )


    # ========================================================
    # ALLOWED ROLES
    # ========================================================

    allowed_roles = [
        UserRole.superadmin.value,
        UserRole.school_admin.value,
        UserRole.branch_admin.value,
        UserRole.teacher.value,
        UserRole.student.value,
        UserRole.parent.value
    ]


    # ========================================================
    # FILTERS
    # ========================================================

    search = request.args.get(
        "search",
        "",
        type=str
    ).strip()

    role = request.args.get(
        "role",
        "",
        type=str
    ).strip().lower()

    status = request.args.get(
        "status",
        "",
        type=str
    ).strip().lower()

    verification = request.args.get(
        "verification",
        "",
        type=str
    ).strip().lower()


    # --------------------------------------------------------
    # INSTITUTION FILTER
    # --------------------------------------------------------

    institution_id = request.args.get(
        "institution_id",
        "",
        type=str
    ).strip()


    # --------------------------------------------------------
    # BRANCH FILTER
    # --------------------------------------------------------

    branch_id = request.args.get(
        "branch_id",
        "",
        type=str
    ).strip()


    # ========================================================
    # SAFE INTEGER CONVERSION
    # ========================================================

    selected_institution_id = None
    selected_branch_id = None


    if institution_id:

        try:
            selected_institution_id = int(
                institution_id
            )

        except (TypeError, ValueError):

            selected_institution_id = None


    if branch_id:

        try:
            selected_branch_id = int(
                branch_id
            )

        except (TypeError, ValueError):

            selected_branch_id = None


    # ========================================================
    # LOAD INSTITUTIONS
    # ========================================================

    institutions = (
        Institution.query
        .order_by(
            Institution.name.asc()
        )
        .all()
    )


    # ========================================================
    # LOAD BRANCHES
    #
    # If institution is selected, only branches belonging
    # to that institution are loaded.
    # ========================================================

    branches_query = Branch.query


    if selected_institution_id:

        branches_query = branches_query.filter(
            Branch.institution_id ==
            selected_institution_id
        )


    branches = (
        branches_query
        .order_by(
            Branch.name.asc()
        )
        .all()
    )


    # ========================================================
    # VALIDATE SELECTED INSTITUTION
    # ========================================================

    selected_institution = None

    if selected_institution_id:

        selected_institution = (
            Institution.query
            .filter(
                Institution.id ==
                selected_institution_id
            )
            .first()
        )

        if not selected_institution:

            selected_institution_id = None
            institution_id = ""

            # Reload all branches because the selected
            # institution was invalid.
            branches = (
                Branch.query
                .order_by(
                    Branch.name.asc()
                )
                .all()
            )


    # ========================================================
    # VALIDATE SELECTED BRANCH
    #
    # Branch must belong to the selected institution.
    # ========================================================

    selected_branch = None

    if selected_branch_id:

        branch_query = Branch.query.filter(
            Branch.id ==
            selected_branch_id
        )

        if selected_institution_id:

            branch_query = branch_query.filter(
                Branch.institution_id ==
                selected_institution_id
            )

        selected_branch = (
            branch_query
            .first()
        )

        if not selected_branch:

            selected_branch_id = None
            branch_id = ""


    # ========================================================
    # PAGINATION
    # ========================================================

    page = request.args.get(
        "page",
        1,
        type=int
    )

    per_page = request.args.get(
        "per_page",
        20,
        type=int
    )


    if page < 1:
        page = 1


    allowed_per_page = [
        10,
        20,
        50,
        100
    ]


    if per_page not in allowed_per_page:
        per_page = 20


    # ========================================================
    # BASE QUERY
    # ========================================================

    query = User.query


    # ========================================================
    # SEARCH
    # ========================================================

    if search:

        search_pattern = f"%{search}%"


        query = query.filter(
            db.or_(

                User.username.ilike(
                    search_pattern
                ),

                User.email.ilike(
                    search_pattern
                ),

                User.fullname.ilike(
                    search_pattern
                ),

                User.phone.ilike(
                    search_pattern
                ),

                User.country.ilike(
                    search_pattern
                ),

                User.city.ilike(
                    search_pattern
                ),

                User.state.ilike(
                    search_pattern
                ),

                User.address.ilike(
                    search_pattern
                )
            )
        )


    # ========================================================
    # ROLE FILTER
    # ========================================================

    if role and role in allowed_roles:

        query = query.filter(
            User.role == role
        )


    # ========================================================
    # STATUS FILTER
    # ========================================================

    if status == "active":

        query = query.filter(
            User.status.is_(True)
        )

    elif status == "inactive":

        query = query.filter(
            User.status.is_(False)
        )


    # ========================================================
    # VERIFICATION FILTER
    # ========================================================

    if verification == "verified":

        query = query.filter(
            User.is_verified.is_(True)
        )

    elif verification == "unverified":

        query = query.filter(
            User.is_verified.is_(False)
        )


    # ========================================================
    # INSTITUTION FILTER
    # ========================================================

    if selected_institution_id:

        query = query.filter(
            User.institution_id ==
            selected_institution_id
        )


    # ========================================================
    # BRANCH FILTER
    # ========================================================

    if selected_branch_id:

        query = query.filter(
            User.branch_id ==
            selected_branch_id
        )


    # ========================================================
    # ORDER
    # ========================================================

    query = query.order_by(
        User.created_at.desc(),
        User.id.desc()
    )


    # ========================================================
    # PAGINATION
    # ========================================================

    pagination = query.paginate(
        page=page,
        per_page=per_page,
        error_out=False
    )


    users = pagination.items


    # ========================================================
    # GLOBAL USER STATISTICS
    #
    # These are global because superadmin is viewing the
    # complete user management system.
    # ========================================================

    total_users = (
        User.query.count()
    )


    active_users = (
        User.query
        .filter(
            User.status.is_(True)
        )
        .count()
    )


    inactive_users = (
        User.query
        .filter(
            User.status.is_(False)
        )
        .count()
    )


    verified_users = (
        User.query
        .filter(
            User.is_verified.is_(True)
        )
        .count()
    )


    unverified_users = (
        User.query
        .filter(
            User.is_verified.is_(False)
        )
        .count()
    )


    # ========================================================
    # ROLE STATISTICS
    # ========================================================

    superadmin_count = (
        User.query
        .filter(
            User.role ==
            UserRole.superadmin.value
        )
        .count()
    )


    school_admin_count = (
        User.query
        .filter(
            User.role ==
            UserRole.school_admin.value
        )
        .count()
    )


    branch_admin_count = (
        User.query
        .filter(
            User.role ==
            UserRole.branch_admin.value
        )
        .count()
    )


    teacher_count = (
        User.query
        .filter(
            User.role ==
            UserRole.teacher.value
        )
        .count()
    )


    student_count = (
        User.query
        .filter(
            User.role ==
            UserRole.student.value
        )
        .count()
    )


    parent_count = (
        User.query
        .filter(
            User.role ==
            UserRole.parent.value
        )
        .count()
    )


    # ========================================================
    # ONLINE USER COUNT
    #
    # User is considered online when last_active is within
    # the previous 30 seconds.
    # ========================================================

    online_threshold = (
        datetime.utcnow()
        - timedelta(seconds=30)
    )


    online_users = (
        User.query
        .filter(
            User.status.is_(True),
            User.last_active.isnot(None),
            User.last_active >= online_threshold
        )
        .count()
    )


    offline_users = max(
        0,
        total_users - online_users
    )


    # ========================================================
    # FILTERED STATISTICS
    #
    # These statistics change according to the selected
    # institution and branch.
    # ========================================================

    filtered_stats_query = User.query


    if selected_institution_id:

        filtered_stats_query = (
            filtered_stats_query
            .filter(
                User.institution_id ==
                selected_institution_id
            )
        )


    if selected_branch_id:

        filtered_stats_query = (
            filtered_stats_query
            .filter(
                User.branch_id ==
                selected_branch_id
            )
        )


    # --------------------------------------------------------
    # FILTERED TOTAL
    # --------------------------------------------------------

    filtered_total_users = (
        filtered_stats_query.count()
    )


    # --------------------------------------------------------
    # FILTERED ACTIVE
    # --------------------------------------------------------

    filtered_active_users = (
        filtered_stats_query
        .filter(
            User.status.is_(True)
        )
        .count()
    )


    # --------------------------------------------------------
    # FILTERED INACTIVE
    # --------------------------------------------------------

    filtered_inactive_users = (
        filtered_stats_query
        .filter(
            User.status.is_(False)
        )
        .count()
    )


    # --------------------------------------------------------
    # FILTERED VERIFIED
    # --------------------------------------------------------

    filtered_verified_users = (
        filtered_stats_query
        .filter(
            User.is_verified.is_(True)
        )
        .count()
    )


    # --------------------------------------------------------
    # FILTERED UNVERIFIED
    # --------------------------------------------------------

    filtered_unverified_users = (
        filtered_stats_query
        .filter(
            User.is_verified.is_(False)
        )
        .count()
    )


    # ========================================================
    # FILTERED ONLINE USERS
    # ========================================================

    filtered_online_users = (
        filtered_stats_query
        .filter(
            User.status.is_(True),
            User.last_active.isnot(None),
            User.last_active >= online_threshold
        )
        .count()
    )


    filtered_offline_users = max(
        0,
        filtered_total_users -
        filtered_online_users
    )


    # ========================================================
    # FILTERED ROLE STATISTICS
    # ========================================================

    filtered_superadmin_count = (
        filtered_stats_query
        .filter(
            User.role ==
            UserRole.superadmin.value
        )
        .count()
    )


    filtered_school_admin_count = (
        filtered_stats_query
        .filter(
            User.role ==
            UserRole.school_admin.value
        )
        .count()
    )


    filtered_branch_admin_count = (
        filtered_stats_query
        .filter(
            User.role ==
            UserRole.branch_admin.value
        )
        .count()
    )


    filtered_teacher_count = (
        filtered_stats_query
        .filter(
            User.role ==
            UserRole.teacher.value
        )
        .count()
    )


    filtered_student_count = (
        filtered_stats_query
        .filter(
            User.role ==
            UserRole.student.value
        )
        .count()
    )


    filtered_parent_count = (
        filtered_stats_query
        .filter(
            User.role ==
            UserRole.parent.value
        )
        .count()
    )


    # ========================================================
    # RENDER
    # ========================================================

    return render_template(
        "backend/pages/users/all_users.html",

        # ----------------------------------------------------
        # CURRENT LOGGED-IN USER
        # ----------------------------------------------------

        user=current_user,


        # ----------------------------------------------------
        # USERS
        # ----------------------------------------------------

        users=users,


        # ----------------------------------------------------
        # PAGINATION
        # ----------------------------------------------------

        pagination=pagination,

        page=page,

        per_page=per_page,


        # ----------------------------------------------------
        # CURRENT FILTERS
        # ----------------------------------------------------

        search=search,

        selected_role=role,

        selected_status=status,

        selected_verification=verification,

        selected_institution_id=(
            selected_institution_id
        ),

        selected_branch_id=(
            selected_branch_id
        ),


        # ----------------------------------------------------
        # INSTITUTIONS / BRANCHES
        # ----------------------------------------------------

        institutions=institutions,

        branches=branches,

        selected_institution=(
            selected_institution
        ),

        selected_branch=(
            selected_branch
        ),


        # ----------------------------------------------------
        # ROLE LIST
        # ----------------------------------------------------

        roles=allowed_roles,


        # ====================================================
        # GLOBAL STATISTICS
        # ====================================================

        total_users=total_users,

        active_users=active_users,

        inactive_users=inactive_users,

        verified_users=verified_users,

        unverified_users=unverified_users,


        # ----------------------------------------------------
        # GLOBAL ONLINE STATISTICS
        # ----------------------------------------------------

        online_users=online_users,

        offline_users=offline_users,


        # ====================================================
        # GLOBAL ROLE STATISTICS
        # ====================================================

        superadmin_count=superadmin_count,

        school_admin_count=school_admin_count,

        branch_admin_count=branch_admin_count,

        teacher_count=teacher_count,

        student_count=student_count,

        parent_count=parent_count,


        # ====================================================
        # FILTERED STATISTICS
        # ====================================================

        filtered_total_users=(
            filtered_total_users
        ),

        filtered_active_users=(
            filtered_active_users
        ),

        filtered_inactive_users=(
            filtered_inactive_users
        ),

        filtered_verified_users=(
            filtered_verified_users
        ),

        filtered_unverified_users=(
            filtered_unverified_users
        ),


        # ----------------------------------------------------
        # FILTERED ONLINE STATISTICS
        # ----------------------------------------------------

        filtered_online_users=(
            filtered_online_users
        ),

        filtered_offline_users=(
            filtered_offline_users
        ),


        # ----------------------------------------------------
        # FILTERED ROLE STATISTICS
        # ----------------------------------------------------

        filtered_superadmin_count=(
            filtered_superadmin_count
        ),

        filtered_school_admin_count=(
            filtered_school_admin_count
        ),

        filtered_branch_admin_count=(
            filtered_branch_admin_count
        ),

        filtered_teacher_count=(
            filtered_teacher_count
        ),

        filtered_student_count=(
            filtered_student_count
        ),

        filtered_parent_count=(
            filtered_parent_count
        )
    )


