@bp.route(
    "/edit-academic-year/<int:academic_year_id>",
    methods=["GET", "POST"]
)
@login_required
def edit_academic_year(academic_year_id):

    # ========================================================
    # SUPERADMIN ONLY
    # ========================================================

    if not current_user.is_authenticated:

        flash(
            "Authentication required.",
            "danger"
        )

        return redirect(
            url_for("main.login")
        )

    # ========================================================
    # ACCESS CONTROL
    # SUPERADMIN + INSTITUTION ADMIN
    # ========================================================

    is_superadmin = current_user.is_superadmin()

    is_institution_admin = (
        hasattr(current_user, "is_institution_admin")
        and current_user.is_institution_admin()
    )

    if not is_superadmin and not is_institution_admin:

        flash(
            "You do not have permission to delete programs.",
            "danger"
        )

        return redirect(
            url_for("main.all_programs")
        )

    # ========================================================
    # GET ACADEMIC YEAR
    # ========================================================

    academic_year = (
        AcademicYear.query
        .filter(
            AcademicYear.id ==
            academic_year_id
        )
        .first()
    )


    if not academic_year:

        flash(
            "Academic year not found.",
            "danger"
        )

        return redirect(
            url_for(
                "main.all_academic_years"
            )
        )


    # ========================================================
    # INSTITUTIONS
    # ========================================================

    institutions = (
        Institution.query
        .order_by(
            Institution.name.asc()
        )
        .all()
    )


    # ========================================================
    # POST
    # ========================================================

    if request.method == "POST":

        # ====================================================
        # FORM DATA
        # ====================================================

        institution_id_raw = request.form.get(
            "institution_id",
            "",
            type=str
        ).strip()


        name = request.form.get(
            "name",
            "",
            type=str
        ).strip()


        code = request.form.get(
            "code",
            "",
            type=str
        ).strip()


        start_date_raw = request.form.get(
            "start_date",
            "",
            type=str
        ).strip()


        end_date_raw = request.form.get(
            "end_date",
            "",
            type=str
        ).strip()


        is_current_raw = request.form.get(
            "is_current",
            "false",
            type=str
        ).strip().lower()


        status = request.form.get(
            "status",
            "active",
            type=str
        ).strip().lower()


        description = request.form.get(
            "description",
            "",
            type=str
        ).strip()


        # ====================================================
        # REQUIRED FIELDS
        # ====================================================

        if not institution_id_raw:

            flash(
                "Please select an institution.",
                "danger"
            )

            return render_template(
                "backend/pages/academic_years/edit_academic_year.html",
                academic_year=academic_year,
                institutions=institutions,
                user=current_user
            )


        if not name:

            flash(
                "Academic year name is required.",
                "danger"
            )

            return render_template(
                "backend/pages/academic_years/edit_academic_year.html",
                academic_year=academic_year,
                institutions=institutions,
                user=current_user
            )


        if not code:

            flash(
                "Academic year code is required.",
                "danger"
            )

            return render_template(
                "backend/pages/academic_years/edit_academic_year.html",
                academic_year=academic_year,
                institutions=institutions,
                user=current_user
            )


        if not start_date_raw:

            flash(
                "Start date is required.",
                "danger"
            )

            return render_template(
                "backend/pages/academic_years/edit_academic_year.html",
                academic_year=academic_year,
                institutions=institutions,
                user=current_user
            )


        if not end_date_raw:

            flash(
                "End date is required.",
                "danger"
            )

            return render_template(
                "backend/pages/academic_years/edit_academic_year.html",
                academic_year=academic_year,
                institutions=institutions,
                user=current_user
            )


        # ====================================================
        # INSTITUTION ID
        # ====================================================

        try:

            institution_id = int(
                institution_id_raw
            )

        except (
            ValueError,
            TypeError
        ):

            flash(
                "Invalid institution selected.",
                "danger"
            )

            return render_template(
                "backend/pages/academic_years/edit_academic_year.html",
                academic_year=academic_year,
                institutions=institutions,
                user=current_user
            )


        # ====================================================
        # CHECK INSTITUTION
        # ====================================================

        institution = (
            Institution.query
            .filter(
                Institution.id == institution_id
            )
            .first()
        )


        if not institution:

            flash(
                "Selected institution was not found.",
                "danger"
            )

            return render_template(
                "backend/pages/academic_years/edit_academic_year.html",
                academic_year=academic_year,
                institutions=institutions,
                user=current_user
            )


        # ====================================================
        # PARSE START DATE
        # ====================================================

        try:

            start_date = datetime.strptime(
                start_date_raw,
                "%Y-%m-%d"
            ).date()

        except (
            ValueError,
            TypeError
        ):

            flash(
                "Invalid start date.",
                "danger"
            )

            return render_template(
                "backend/pages/academic_years/edit_academic_year.html",
                academic_year=academic_year,
                institutions=institutions,
                user=current_user
            )


        # ====================================================
        # PARSE END DATE
        # ====================================================

        try:

            end_date = datetime.strptime(
                end_date_raw,
                "%Y-%m-%d"
            ).date()

        except (
            ValueError,
            TypeError
        ):

            flash(
                "Invalid end date.",
                "danger"
            )

            return render_template(
                "backend/pages/academic_years/edit_academic_year.html",
                academic_year=academic_year,
                institutions=institutions,
                user=current_user
            )


        # ====================================================
        # DATE VALIDATION
        # ====================================================

        if end_date <= start_date:

            flash(
                "End date must be after the start date.",
                "danger"
            )

            return render_template(
                "backend/pages/academic_years/edit_academic_year.html",
                academic_year=academic_year,
                institutions=institutions,
                user=current_user
            )


        # ====================================================
        # NORMALIZE CODE
        # ====================================================

        code = code.upper()


        # ====================================================
        # STATUS
        # ====================================================

        allowed_statuses = {
            "active",
            "inactive",
            "closed"
        }


        if status not in allowed_statuses:

            status = "active"


        # ====================================================
        # IS CURRENT
        # ====================================================

        is_current = (
            is_current_raw
            in {
                "true",
                "1",
                "yes",
                "on"
            }
        )


        # ====================================================
        # DUPLICATE CODE
        #
        # Exclude current academic year
        # ====================================================

        existing_code = (
            AcademicYear.query
            .filter(

                AcademicYear.institution_id ==
                institution_id,

                db.func.lower(
                    AcademicYear.code
                ) == code.lower(),

                AcademicYear.id !=
                academic_year.id

            )
            .first()
        )


        if existing_code:

            flash(
                "An academic year with this code already exists in this institution.",
                "danger"
            )

            return render_template(
                "backend/pages/academic_years/edit_academic_year.html",
                academic_year=academic_year,
                institutions=institutions,
                user=current_user
            )


        # ====================================================
        # DUPLICATE NAME
        #
        # Exclude current academic year
        # ====================================================

        existing_name = (
            AcademicYear.query
            .filter(

                AcademicYear.institution_id ==
                institution_id,

                db.func.lower(
                    AcademicYear.name
                ) == name.lower(),

                AcademicYear.id !=
                academic_year.id

            )
            .first()
        )


        if existing_name:

            flash(
                "An academic year with this name already exists in this institution.",
                "danger"
            )

            return render_template(
                "backend/pages/academic_years/edit_academic_year.html",
                academic_year=academic_year,
                institutions=institutions,
                user=current_user
            )


        # ====================================================
        # UPDATE FIELDS
        # ====================================================

        academic_year.institution_id = (
            institution_id
        )

        academic_year.name = name

        academic_year.code = code

        academic_year.start_date = (
            start_date
        )

        academic_year.end_date = (
            end_date
        )

        academic_year.is_current = (
            is_current
        )

        academic_year.status = status

        academic_year.description = (
            description
            or None
        )


        # ====================================================
        # CURRENT YEAR LOGIC
        #
        # If current:
        # unset other current years in selected institution.
        #
        # Important:
        # This also handles moving the academic year
        # from one institution to another.
        # ====================================================

        try:

            if is_current:

                (
                    AcademicYear.query
                    .filter(

                        AcademicYear.institution_id ==
                        institution_id,

                        AcademicYear.is_current.is_(True),

                        AcademicYear.id !=
                        academic_year.id

                    )
                    .update(

                        {
                            AcademicYear.is_current:
                                False
                        },

                        synchronize_session=False

                    )
                )


            # ------------------------------------------------
            # SAVE
            # ------------------------------------------------

            db.session.commit()


            flash(
                f"Academic year '{academic_year.name}' has been updated successfully.",
                "success"
            )


            return redirect(
                url_for(
                    "main.view_academic_year",
                    academic_year_id=
                        academic_year.id
                )
            )


        except IntegrityError:

            db.session.rollback()


            flash(
                "Unable to update academic year because one of the unique values already exists.",
                "danger"
            )


        except Exception as e:

            db.session.rollback()


            flash(
                f"Unable to update academic year: {str(e)}",
                "danger"
            )


    # ========================================================
    # GET
    # ========================================================

    return render_template(
        "backend/pages/academic_years/edit_academic_year.html",
        academic_year=academic_year,
        institutions=institutions,
        user=current_user
    )


# ============================================================
# DELETE ACADEMIC YEAR
# ============================================================

@bp.route(
    "/delete-academic-year/<int:academic_year_id>",
    methods=["POST"]
)
@login_required
def delete_academic_year(academic_year_id):

    # ========================================================
    # SUPERADMIN ONLY
    # ========================================================

    if not current_user.is_authenticated:

        return jsonify({

            "success": False,

            "message":
                "Authentication required."

        }), 401


   # ========================================================
    # ACCESS CONTROL
    # SUPERADMIN + INSTITUTION ADMIN
    # ========================================================

    is_superadmin = current_user.is_superadmin()

    is_institution_admin = (
        hasattr(current_user, "is_institution_admin")
        and current_user.is_institution_admin()
    )

    if not is_superadmin and not is_institution_admin:

        flash(
            "You do not have permission to delete programs.",
            "danger"
        )

        return redirect(
            url_for("main.all_programs")
        )


    # ========================================================
    # GET ACADEMIC YEAR
    # ========================================================

    academic_year = (
        AcademicYear.query
        .filter(
            AcademicYear.id ==
            academic_year_id
        )
        .first()
    )


    if not academic_year:

        return jsonify({

            "success": False,

            "message":
                "Academic year not found."

        }), 404


    # ========================================================
    # PREVENT DELETING CURRENT YEAR
    #
    # This is safer because other records may depend on
    # the current academic year.
    # ========================================================

    if academic_year.is_current:

        return jsonify({

            "success": False,

            "message":
                "The current academic year cannot be deleted. "
                "Set another academic year as current first."

        }), 400


    # ========================================================
    # SAVE NAME FOR RESPONSE
    # ========================================================

    academic_year_name = (
        academic_year.name
    )


    # ========================================================
    # DELETE
    # ========================================================

    try:

        db.session.delete(
            academic_year
        )

        db.session.commit()


        return jsonify({

            "success": True,

            "message":
                f"Academic year '{academic_year_name}' "
                "has been deleted successfully."

        }), 200


    except IntegrityError:

        db.session.rollback()


        return jsonify({

            "success": False,

            "message":
                "This academic year cannot be deleted because "
                "other records are still linked to it."

        }), 409


    except Exception as e:

        db.session.rollback()


        return jsonify({

            "success": False,

            "message":
                f"Unable to delete academic year: {str(e)}"

        }), 500




# ============================================================
# ALL TERMS
# ============================================================

@bp.route("/all-terms")
@login_required
def all_terms():

    # --------------------------------------------------------
    # SUPERADMIN ONLY
    # --------------------------------------------------------
 # ========================================================
    # ACCESS CONTROL
    # SUPERADMIN + INSTITUTION ADMIN
    # ========================================================

    is_superadmin = current_user.is_superadmin()

    is_institution_admin = (
        hasattr(current_user, "is_institution_admin")
        and current_user.is_institution_admin()
    )

    if not is_superadmin and not is_institution_admin:

        flash(
            "You do not have permission to delete programs.",
            "danger"
        )

        return redirect(
            url_for("main.all_programs")
        )

    # --------------------------------------------------------
    # QUERY PARAMETERS
    # --------------------------------------------------------

    search = request.args.get(
        "search",
        "",
        type=str
    ).strip()

    selected_status = request.args.get(
        "status",
        "",
        type=str
    ).strip().lower()

    selected_institution_id = request.args.get(
        "institution_id",
        "",
        type=str
    ).strip()

    selected_academic_year_id = request.args.get(
        "academic_year_id",
        "",
        type=str
    ).strip()

    selected_current = request.args.get(
        "is_current",
        "",
        type=str
    ).strip().lower()


    # --------------------------------------------------------
    # PAGINATION
    # --------------------------------------------------------

    allowed_per_page = [
        10,
        25,
        50,
        100
    ]

    per_page = request.args.get(
        "per_page",
        25,
        type=int
    )

    if per_page not in allowed_per_page:

        per_page = 25


    page = request.args.get(
        "page",
        1,
        type=int
    )


    # --------------------------------------------------------
    # BASE QUERY
    # --------------------------------------------------------

    query = Term.query


    # --------------------------------------------------------
    # SEARCH
    # --------------------------------------------------------

    if search:

        search_pattern = f"%{search}%"

        query = query.filter(
            or_(
                Term.name.ilike(search_pattern),
                Term.code.ilike(search_pattern),
                Term.description.ilike(search_pattern)
            )
        )


    # --------------------------------------------------------
    # STATUS FILTER
    # --------------------------------------------------------

    allowed_statuses = {
        "active",
        "inactive",
        "closed"
    }

    if selected_status in allowed_statuses:

        query = query.filter(
            Term.status == selected_status
        )

    else:

        selected_status = ""


    # --------------------------------------------------------
    # INSTITUTION FILTER
    # --------------------------------------------------------

    if selected_institution_id:

        try:

            institution_id = int(
                selected_institution_id
            )

            query = query.filter(
                Term.institution_id == institution_id
            )

        except (
            ValueError,
            TypeError
        ):

            selected_institution_id = ""


    # --------------------------------------------------------
    # ACADEMIC YEAR FILTER
    # --------------------------------------------------------

    if selected_academic_year_id:

        try:

            academic_year_id = int(
                selected_academic_year_id
            )

            query = query.filter(
                Term.academic_year_id ==
                academic_year_id
            )

        except (
            ValueError,
            TypeError
        ):

            selected_academic_year_id = ""


    # --------------------------------------------------------
    # CURRENT TERM FILTER
    # --------------------------------------------------------

    if selected_current == "current":

        query = query.filter(
            Term.is_current.is_(True)
        )

    elif selected_current == "not_current":

        query = query.filter(
            Term.is_current.is_(False)
        )

    else:

        selected_current = ""


    # --------------------------------------------------------
    # ORDERING
    # --------------------------------------------------------

    query = query.order_by(
        Term.is_current.desc(),
        Term.academic_year_id.desc(),
        Term.sequence.asc(),
        Term.start_date.asc(),
        Term.created_at.desc(),
        Term.id.desc()
    )


    # --------------------------------------------------------
    # PAGINATION
    # --------------------------------------------------------

    pagination = query.paginate(
        page=page,
        per_page=per_page,
        error_out=False
    )

    terms = pagination.items


    # --------------------------------------------------------
    # INSTITUTIONS
    # --------------------------------------------------------

    institutions = (
        Institution.query
        .order_by(
            Institution.name.asc()
        )
        .all()
    )


    # --------------------------------------------------------
    # ACADEMIC YEARS
    # --------------------------------------------------------

    academic_years = (
        AcademicYear.query
        .order_by(
            AcademicYear.is_current.desc(),
            AcademicYear.start_date.desc(),
            AcademicYear.name.asc()
        )
        .all()
    )


    # --------------------------------------------------------
    # STATISTICS
    # --------------------------------------------------------

    total_terms = Term.query.count()


    active_terms = (
        Term.query
        .filter(
            Term.status == "active"
        )
        .count()
    )


    inactive_terms = (
        Term.query
        .filter(
            Term.status == "inactive"
        )
        .count()
    )


    closed_terms = (
        Term.query
        .filter(
            Term.status == "closed"
        )
        .count()
    )


    current_terms = (
        Term.query
        .filter(
            Term.is_current.is_(True)
        )
        .count()
    )


    # --------------------------------------------------------
    # RENDER
    # --------------------------------------------------------

    return render_template(
        "backend/pages/terms/all_terms.html",

        terms=terms,

        pagination=pagination,

        institutions=institutions,

        academic_years=academic_years,

        search=search,

        selected_status=selected_status,

        selected_institution_id=
            selected_institution_id,

        selected_academic_year_id=
            selected_academic_year_id,

        selected_current=
            selected_current,

        per_page=per_page,

        total_terms=total_terms,

        active_terms=active_terms,

        inactive_terms=inactive_terms,

        closed_terms=closed_terms,

        current_terms=current_terms,

        user=current_user
    )

# ============================================================
# ADD TERM
# ============================================================

@bp.route(
    "/add-term",
    methods=["GET", "POST"]
)
@login_required
def add_term():

    # --------------------------------------------------------
    # SUPERADMIN ONLY
    # --------------------------------------------------------
 # ========================================================
    # ACCESS CONTROL
    # SUPERADMIN + INSTITUTION ADMIN
    # ========================================================

    is_superadmin = current_user.is_superadmin()

    is_institution_admin = (
        hasattr(current_user, "is_institution_admin")
        and current_user.is_institution_admin()
    )

    if not is_superadmin and not is_institution_admin:

        flash(
            "You do not have permission to delete programs.",
            "danger"
        )

        return redirect(
            url_for("main.all_programs")
        )



    # --------------------------------------------------------
    # LOAD INSTITUTIONS
    # --------------------------------------------------------

    institutions = (
        Institution.query
        .order_by(
            Institution.name.asc()
        )
        .all()
    )


    # --------------------------------------------------------
    # LOAD ACADEMIC YEARS
    # --------------------------------------------------------

    academic_years = (
        AcademicYear.query
        .order_by(
            AcademicYear.is_current.desc(),
            AcademicYear.start_date.desc(),
            AcademicYear.name.asc()
        )
        .all()
    )


    # --------------------------------------------------------
    # POST
    # --------------------------------------------------------

    if request.method == "POST":

        institution_id_raw = request.form.get(
            "institution_id",
            ""
        ).strip()

        academic_year_id_raw = request.form.get(
            "academic_year_id",
            ""
        ).strip()

        name = request.form.get(
            "name",
            ""
        ).strip()

        code = request.form.get(
            "code",
            ""
        ).strip().upper()

        sequence_raw = request.form.get(
            "sequence",
            "1"
        ).strip()

        start_date_raw = request.form.get(
            "start_date",
            ""
        ).strip()

        end_date_raw = request.form.get(
            "end_date",
            ""
        ).strip()

        is_current_raw = request.form.get(
            "is_current",
            ""
        ).strip().lower()

        status = request.form.get(
            "status",
            "active"
        ).strip().lower()

        description = request.form.get(
            "description",
            ""
        ).strip()


        # ----------------------------------------------------
        # VALIDATE INSTITUTION ID
        # ----------------------------------------------------

        try:

            institution_id = int(
                institution_id_raw
            )

        except (
            ValueError,
            TypeError
        ):

            flash(
                "Please select a valid institution.",
                "danger"
            )

            return render_template(
                "backend/pages/terms/add_term.html",
                institutions=institutions,
                academic_years=academic_years,
                user=current_user
            )


        # ----------------------------------------------------
        # VALIDATE ACADEMIC YEAR ID
        # ----------------------------------------------------

        try:

            academic_year_id = int(
                academic_year_id_raw
            )

        except (
            ValueError,
            TypeError
        ):

            flash(
                "Please select a valid academic year.",
                "danger"
            )

            return render_template(
                "backend/pages/terms/add_term.html",
                institutions=institutions,
                academic_years=academic_years,
                user=current_user
            )


        # ----------------------------------------------------
        # VALIDATE REQUIRED FIELDS
        # ----------------------------------------------------

        if not name:

            flash(
                "Term name is required.",
                "danger"
            )

            return render_template(
                "backend/pages/terms/add_term.html",
                institutions=institutions,
                academic_years=academic_years,
                user=current_user
            )


        if not code:

            flash(
                "Term code is required.",
                "danger"
            )

            return render_template(
                "backend/pages/terms/add_term.html",
                institutions=institutions,
                academic_years=academic_years,
                user=current_user
            )


        if not start_date_raw:

            flash(
                "Start date is required.",
                "danger"
            )

            return render_template(
                "backend/pages/terms/add_term.html",
                institutions=institutions,
                academic_years=academic_years,
                user=current_user
            )


        if not end_date_raw:

            flash(
                "End date is required.",
                "danger"
            )

            return render_template(
                "backend/pages/terms/add_term.html",
                institutions=institutions,
                academic_years=academic_years,
                user=current_user
            )


        # ----------------------------------------------------
        # INSTITUTION
        # ----------------------------------------------------

        institution = (
            Institution.query
            .filter(
                Institution.id == institution_id
            )
            .first()
        )

        if not institution:

            flash(
                "Selected institution was not found.",
                "danger"
            )

            return render_template(
                "backend/pages/terms/add_term.html",
                institutions=institutions,
                academic_years=academic_years,
                user=current_user
            )


        # ----------------------------------------------------
        # ACADEMIC YEAR
        # ----------------------------------------------------

        academic_year = (
            AcademicYear.query
            .filter(
                AcademicYear.id ==
                academic_year_id
            )
            .first()
        )

        if not academic_year:

            flash(
                "Selected academic year was not found.",
                "danger"
            )

            return render_template(
                "backend/pages/terms/add_term.html",
                institutions=institutions,
                academic_years=academic_years,
                user=current_user
            )


        # ----------------------------------------------------
        # VERIFY ACADEMIC YEAR BELONGS TO INSTITUTION
        # ----------------------------------------------------

        if (
            academic_year.institution_id
            != institution_id
        ):

            flash(
                "The selected academic year does not belong to the selected institution.",
                "danger"
            )

            return render_template(
                "backend/pages/terms/add_term.html",
                institutions=institutions,
                academic_years=academic_years,
                user=current_user
            )


        # ----------------------------------------------------
        # SEQUENCE
        # ----------------------------------------------------

        try:

            sequence = int(
                sequence_raw
            )

        except (
            ValueError,
            TypeError
        ):

            flash(
                "Sequence must be a valid number.",
                "danger"
            )

            return render_template(
                "backend/pages/terms/add_term.html",
                institutions=institutions,
                academic_years=academic_years,
                user=current_user
            )


        if sequence < 1:

            flash(
                "Sequence must be greater than or equal to 1.",
                "danger"
            )

            return render_template(
                "backend/pages/terms/add_term.html",
                institutions=institutions,
                academic_years=academic_years,
                user=current_user
            )


        # ----------------------------------------------------
        # DATE PARSING
        # ----------------------------------------------------

        try:

            start_date = datetime.strptime(
                start_date_raw,
                "%Y-%m-%d"
            ).date()

            end_date = datetime.strptime(
                end_date_raw,
                "%Y-%m-%d"
            ).date()

        except ValueError:

            flash(
                "Invalid date format.",
                "danger"
            )

            return render_template(
                "backend/pages/terms/add_term.html",
                institutions=institutions,
                academic_years=academic_years,
                user=current_user
            )


        # ----------------------------------------------------
        # DATE ORDER
        # ----------------------------------------------------

        if end_date <= start_date:

            flash(
                "End date must be later than start date.",
                "danger"
            )

            return render_template(
                "backend/pages/terms/add_term.html",
                institutions=institutions,
                academic_years=academic_years,
                user=current_user
            )


        # ----------------------------------------------------
        # STATUS
        # ----------------------------------------------------

        allowed_statuses = {
            "active",
            "inactive",
            "closed"
        }

        if status not in allowed_statuses:

            status = "active"


        # ----------------------------------------------------
        # CURRENT TERM
        # ----------------------------------------------------

        is_current = (
            is_current_raw
            in {
                "true",
                "1",
                "yes",
                "on"
            }
        )


        # ----------------------------------------------------
        # DUPLICATE CODE
        # ----------------------------------------------------

        existing_code = (
            Term.query
            .filter(
                Term.academic_year_id ==
                academic_year_id
            )
            .filter(
                Term.code.ilike(code)
            )
            .first()
        )

        if existing_code:

            flash(
                "This term code already exists in the selected academic year.",
                "danger"
            )

            return render_template(
                "backend/pages/terms/add_term.html",
                institutions=institutions,
                academic_years=academic_years,
                user=current_user
            )


        # ----------------------------------------------------
        # DUPLICATE NAME
        # ----------------------------------------------------

        existing_name = (
            Term.query
            .filter(
                Term.academic_year_id ==
                academic_year_id
            )
            .filter(
                Term.name.ilike(name)
            )
            .first()
        )

        if existing_name:

            flash(
                "This term name already exists in the selected academic year.",
                "danger"
            )

            return render_template(
                "backend/pages/terms/add_term.html",
                institutions=institutions,
                academic_years=academic_years,
                user=current_user
            )


        # ----------------------------------------------------
        # DUPLICATE SEQUENCE
        # ----------------------------------------------------

        existing_sequence = (
            Term.query
            .filter(
                Term.academic_year_id ==
                academic_year_id
            )
            .filter(
                Term.sequence == sequence
            )
            .first()
        )

        if existing_sequence:

            flash(
                f"Sequence {sequence} is already used in this academic year.",
                "danger"
            )

            return render_template(
                "backend/pages/terms/add_term.html",
                institutions=institutions,
                academic_years=academic_years,
                user=current_user
            )


        # ----------------------------------------------------
        # CURRENT TERM
        #
        # Only one current term per academic year.
        # ----------------------------------------------------

        if is_current:

            (
                Term.query
                .filter(
                    Term.academic_year_id ==
                    academic_year_id
                )
                .filter(
                    Term.is_current.is_(True)
                )
                .update(
                    {
                        Term.is_current: False
                    },
                    synchronize_session=False
                )
            )


        # ----------------------------------------------------
        # CREATE TERM
        # ----------------------------------------------------

        term = Term(

            institution_id=institution_id,

            academic_year_id=academic_year_id,

            name=name,

            code=code,

            sequence=sequence,

            start_date=start_date,

            end_date=end_date,

            is_current=is_current,

            status=status,

            description=description or None
        )


        db.session.add(term)


        # ----------------------------------------------------
        # COMMIT
        # ----------------------------------------------------

        try:

            db.session.commit()

            flash(
                "Term created successfully.",
                "success"
            )

            return redirect(
                url_for(
                    "main.all_terms"
                )
            )

        except IntegrityError:

            db.session.rollback()

            flash(
                "Unable to create term. "
                "The code, name, or sequence may already exist.",
                "danger"
            )

        except Exception:

            db.session.rollback()

            flash(
                "An unexpected error occurred while creating the term.",
                "danger"
            )


    # --------------------------------------------------------
    # GET
    # --------------------------------------------------------

    return render_template(
        "backend/pages/terms/add_term.html",

        institutions=institutions,

        academic_years=academic_years,

        user=current_user
    )

# ============================================================
# VIEW TERM
# ============================================================

@bp.route(
    "/view-term/<int:term_id>"
)
@login_required
def view_term(term_id):

   
    # ========================================================
    # ACCESS CONTROL
    # SUPERADMIN + INSTITUTION ADMIN
    # ========================================================

    is_superadmin = current_user.is_superadmin()

    is_institution_admin = (
        hasattr(current_user, "is_institution_admin")
        and current_user.is_institution_admin()
    )

    if not is_superadmin and not is_institution_admin:

        flash(
            "You do not have permission to delete programs.",
            "danger"
        )

        return redirect(
            url_for("main.all_programs")
        )

    # --------------------------------------------------------
    # GET TERM
    # --------------------------------------------------------

    term = (
        Term.query
        .filter(
            Term.id == term_id
        )
        .first()
    )


    if not term:

        flash(
            "Term not found.",
            "danger"
        )

        return redirect(
            url_for("main.all_terms")
        )


    # --------------------------------------------------------
    # INSTITUTION
    # --------------------------------------------------------

    institution = (
        Institution.query
        .filter(
            Institution.id ==
            term.institution_id
        )
        .first()
    )


    # --------------------------------------------------------
    # ACADEMIC YEAR
    # --------------------------------------------------------

    academic_year = (
        AcademicYear.query
        .filter(
            AcademicYear.id ==
            term.academic_year_id
        )
        .first()
    )


    # --------------------------------------------------------
    # TERMS IN SAME ACADEMIC YEAR
    # --------------------------------------------------------

    academic_year_terms_count = (
        Term.query
        .filter(
            Term.academic_year_id ==
            term.academic_year_id
        )
        .count()
    )


    # --------------------------------------------------------
    # CURRENT TERM
    # --------------------------------------------------------

    current_term = (
        Term.query
        .filter(
            Term.academic_year_id ==
            term.academic_year_id
        )
        .filter(
            Term.is_current.is_(True)
        )
        .first()
    )


    # --------------------------------------------------------
    # PREVIOUS TERM
    # --------------------------------------------------------

    previous_term = (
        Term.query
        .filter(
            Term.academic_year_id ==
            term.academic_year_id
        )
        .filter(
            Term.sequence < term.sequence
        )
        .order_by(
            Term.sequence.desc()
        )
        .first()
    )


    # --------------------------------------------------------
    # NEXT TERM
    # --------------------------------------------------------

    next_term = (
        Term.query
        .filter(
            Term.academic_year_id ==
            term.academic_year_id
        )
        .filter(
            Term.sequence > term.sequence
        )
        .order_by(
            Term.sequence.asc()
        )
        .first()
    )


    # --------------------------------------------------------
    # RENDER
    # --------------------------------------------------------

    return render_template(
        "backend/pages/terms/view_term.html",

        term=term,

        institution=institution,

        academic_year=academic_year,

        academic_year_terms_count=
            academic_year_terms_count,

        current_term=current_term,

        previous_term=previous_term,

        next_term=next_term,

        user=current_user
    )


