@bp.route(
    "/exams/<int:exam_id>",
    methods=["GET"]
)
@login_required
def view_exam(exam_id):

    if not _exam_can_view():
        abort(403)

    query = _exam_scope_query(
        Exam.query
    )

    exam = (
        query
        .filter(
            Exam.id == exam_id
        )
        .first_or_404()
    )

    return render_template(
        "backend/pages/exams/view_exam.html",
        exam=exam,
    )


