# ============================================================
# EDIT EXAM
# ============================================================

@bp.route(
    "/exams/<int:exam_id>/edit",
    methods=["GET", "POST"]
)
@login_required
def edit_exam(exam_id):

    # ========================================================
    # ROLE SECURITY
    # ========================================================

    allowed_roles = {
        "superadmin",
        "school_admin",
        "branch_admin",
    }

    current_role = getattr(
        current_user,
        "role",
        None
    )

    if current_role not in allowed_roles:
        abort(403)

    # ========================================================
    # USER SCOPE
    # ========================================================

    user_institution_id = getattr(
        current_user,
        "institution_id",
        None
    )

    user_branch_id = getattr(
        current_user,
        "branch_id",
        None
    )

    # ========================================================
    # GET EXAM
    # ========================================================

    exam = (
        Exam.query
        .filter(
            Exam.id == exam_id
        )
        .first()
    )

    if not exam:
        flash(
            "Exam not found.",
            "danger"
        )

        return redirect(
            url_for("main.all_exams")
        )

    # ========================================================
    # EXAM INSTITUTION SECURITY
    # ========================================================

    if (
        current_role != "superadmin"
        and user_institution_id
        and exam.institution_id
        != user_institution_id
    ):
        abort(403)

    # ========================================================
    # BRANCH ADMIN SECURITY
    # ========================================================

    if (
        current_role == "branch_admin"
        and user_branch_id
        and exam.branch_id != user_branch_id
    ):
        abort(403)

    # ========================================================
    # ALLOWED EXAM TYPES
    # ========================================================

    allowed_exam_types = {
        "term",
        "monthly",
        "bi_monthly",
        "quarterly",
        "semester",
        "midterm",
        "final",
        "annual",
        "mock",
        "entrance",
        "supplementary",
        "resit",
        "special",
    }

    # ========================================================
    # ALLOWED STATUS
    # ========================================================

    allowed_statuses = {
        "draft",
        "scheduled",
        "ongoing",
        "completed",
        "cancelled",
        "published",
    }

    # ========================================================
    # FORM DATA
    # ========================================================

    institutions_query = Institution.query
    branches_query = Branch.query
    programs_query = Program.query
    assessment_plans_query = AssessmentPlan.query
    academic_years_query = AcademicYear.query
    terms_query = Term.query

    # ========================================================
    # USER SCOPE
    # ========================================================

    if current_role != "superadmin":

        if not user_institution_id:

            flash(
                "Your account is not assigned to an institution.",
                "danger"
            )

            return redirect(
                url_for("main.dashboard")
            )

        # ----------------------------------------------------
        # INSTITUTIONS
        # ----------------------------------------------------

        institutions_query = (
            institutions_query.filter(
                Institution.id
                == user_institution_id
            )
        )

        # ----------------------------------------------------
        # BRANCHES
        # ----------------------------------------------------

        branches_query = (
            branches_query.filter(
                Branch.institution_id
                == user_institution_id
            )
        )

        # ----------------------------------------------------
        # PROGRAMS
        # ----------------------------------------------------

        programs_query = (
            programs_query.filter(
                Program.institution_id
                == user_institution_id
            )
        )

        # ----------------------------------------------------
        # ASSESSMENT PLANS
        # ----------------------------------------------------

        if hasattr(
            AssessmentPlan,
            "institution_id"
        ):

            assessment_plans_query = (
                assessment_plans_query.filter(
                    AssessmentPlan.institution_id
                    == user_institution_id
                )
            )

        # ----------------------------------------------------
        # ACADEMIC YEARS
        # ----------------------------------------------------

        if hasattr(
            AcademicYear,
            "institution_id"
        ):

            academic_years_query = (
                academic_years_query.filter(
                    AcademicYear.institution_id
                    == user_institution_id
                )
            )

        # ----------------------------------------------------
        # BRANCH ADMIN
        # ----------------------------------------------------

        if (
            current_role == "branch_admin"
            and user_branch_id
        ):

            branches_query = (
                branches_query.filter(
                    Branch.id
                    == user_branch_id
                )
            )

            programs_query = (
                programs_query.filter(
                    or_(
                        Program.branch_id
                        == user_branch_id,

                        Program.branch_id.is_(None)
                    )
                )
            )

    # ========================================================
    # EXECUTE QUERIES
    # ========================================================

    institutions = (
        institutions_query
        .order_by(
            Institution.name.asc()
        )
        .all()
    )

    branches = (
        branches_query
        .order_by(
            Branch.name.asc()
        )
        .all()
    )

    programs = (
        programs_query
        .order_by(
            Program.name.asc()
        )
        .all()
    )

    assessment_plans = (
        assessment_plans_query
        .order_by(
            AssessmentPlan.name.asc()
        )
        .all()
    )

    academic_years = (
        academic_years_query
        .order_by(
            AcademicYear.id.desc()
        )
        .all()
    )

    terms = (
        terms_query
        .order_by(
            Term.id.desc()
        )
        .all()
    )

    # ========================================================
    # POST
    # ========================================================

    if request.method == "POST":

        # ====================================================
        # FORM VALUES
        # ====================================================

        institution_id = request.form.get(
            "institution_id",
            type=int
        )

        branch_id = request.form.get(
            "branch_id",
            type=int
        )

        program_id = request.form.get(
            "program_id",
            type=int
        )

        assessment_plan_id = request.form.get(
            "assessment_plan_id",
            type=int
        )

        if not assessment_plan_id:
            assessment_plan_id = None

        academic_year_id = request.form.get(
            "academic_year_id",
            type=int
        )

        term_id = request.form.get(
            "term_id",
            type=int
        )

        if not term_id:
            term_id = None

        name = (
            request.form.get(
                "name",
                ""
            )
            .strip()
        )

        code = (
            request.form.get(
                "code",
                ""
            )
            .strip()
            .upper()
        )

        exam_type = (
            request.form.get(
                "exam_type",
                "term"
            )
            .strip()
            .lower()
        )

        description = (
            request.form.get(
                "description",
                ""
            )
            .strip()
        )

        start_date = (
            request.form.get(
                "start_date",
                ""
            )
            .strip()
        )

        end_date = (
            request.form.get(
                "end_date",
                ""
            )
            .strip()
        )

        status = (
            request.form.get(
                "status",
                "draft"
            )
            .strip()
            .lower()
        )

        # ====================================================
        # BASIC VALIDATION
        # ====================================================

        if not institution_id:

            flash(
                "Please select an institution.",
                "danger"
            )

            return render_template(
                "backend/pages/exams/edit_exam.html",
                exam=exam,
                institutions=institutions,
                branches=branches,
                programs=programs,
                assessment_plans=assessment_plans,
                academic_years=academic_years,
                terms=terms,
                allowed_exam_types=allowed_exam_types,
                allowed_statuses=allowed_statuses,
            )

        if not branch_id:

            flash(
                "Please select a branch.",
                "danger"
            )

            return render_template(
                "backend/pages/exams/edit_exam.html",
                exam=exam,
                institutions=institutions,
                branches=branches,
                programs=programs,
                assessment_plans=assessment_plans,
                academic_years=academic_years,
                terms=terms,
                allowed_exam_types=allowed_exam_types,
                allowed_statuses=allowed_statuses,
            )

        if not program_id:

            flash(
                "Please select a program.",
                "danger"
            )

            return render_template(
                "backend/pages/exams/edit_exam.html",
                exam=exam,
                institutions=institutions,
                branches=branches,
                programs=programs,
                assessment_plans=assessment_plans,
                academic_years=academic_years,
                terms=terms,
                allowed_exam_types=allowed_exam_types,
                allowed_statuses=allowed_statuses,
            )

        if not academic_year_id:

            flash(
                "Please select an academic year.",
                "danger"
            )

            return render_template(
                "backend/pages/exams/edit_exam.html",
                exam=exam,
                institutions=institutions,
                branches=branches,
                programs=programs,
                assessment_plans=assessment_plans,
                academic_years=academic_years,
                terms=terms,
                allowed_exam_types=allowed_exam_types,
                allowed_statuses=allowed_statuses,
            )

        if not name:

            flash(
                "Exam name is required.",
                "danger"
            )

            return render_template(
                "backend/pages/exams/edit_exam.html",
                exam=exam,
                institutions=institutions,
                branches=branches,
                programs=programs,
                assessment_plans=assessment_plans,
                academic_years=academic_years,
                terms=terms,
                allowed_exam_types=allowed_exam_types,
                allowed_statuses=allowed_statuses,
            )

        # ====================================================
        # EXAM TYPE
        # ====================================================

        if exam_type not in allowed_exam_types:

            flash(
                "Invalid exam type selected.",
                "danger"
            )

            return render_template(
                "backend/pages/exams/edit_exam.html",
                exam=exam,
                institutions=institutions,
                branches=branches,
                programs=programs,
                assessment_plans=assessment_plans,
                academic_years=academic_years,
                terms=terms,
                allowed_exam_types=allowed_exam_types,
                allowed_statuses=allowed_statuses,
            )

        # ====================================================
        # STATUS
        # ====================================================

        if status not in allowed_statuses:

            flash(
                "Invalid exam status selected.",
                "danger"
            )

            return render_template(
                "backend/pages/exams/edit_exam.html",
                exam=exam,
                institutions=institutions,
                branches=branches,
                programs=programs,
                assessment_plans=assessment_plans,
                academic_years=academic_years,
                terms=terms,
                allowed_exam_types=allowed_exam_types,
                allowed_statuses=allowed_statuses,
            )

        # ====================================================
        # INSTITUTION
        # ====================================================

        institution = (
            Institution.query
            .filter(
                Institution.id
                == institution_id
            )
            .first()
        )

        if not institution:

            flash(
                "Selected institution was not found.",
                "danger"
            )

            return render_template(
                "backend/pages/exams/edit_exam.html",
                exam=exam,
                institutions=institutions,
                branches=branches,
                programs=programs,
                assessment_plans=assessment_plans,
                academic_years=academic_years,
                terms=terms,
                allowed_exam_types=allowed_exam_types,
                allowed_statuses=allowed_statuses,
            )

        # ====================================================
        # INSTITUTION SCOPE
        # ====================================================

        if (
            current_role != "superadmin"
            and institution.id
            != user_institution_id
        ):
            abort(403)

        # ====================================================
        # BRANCH
        # ====================================================

        branch = (
            Branch.query
            .filter(
                Branch.id == branch_id
            )
            .first()
        )

        if not branch:

            flash(
                "Selected branch was not found.",
                "danger"
            )

            return render_template(
                "backend/pages/exams/edit_exam.html",
                exam=exam,
                institutions=institutions,
                branches=branches,
                programs=programs,
                assessment_plans=assessment_plans,
                academic_years=academic_years,
                terms=terms,
                allowed_exam_types=allowed_exam_types,
                allowed_statuses=allowed_statuses,
            )

        # ====================================================
        # BRANCH → INSTITUTION
        # ====================================================

        if branch.institution_id != institution.id:

            flash(
                "Selected branch does not belong to the selected institution.",
                "danger"
            )

            return render_template(
                "backend/pages/exams/edit_exam.html",
                exam=exam,
                institutions=institutions,
                branches=branches,
                programs=programs,
                assessment_plans=assessment_plans,
                academic_years=academic_years,
                terms=terms,
                allowed_exam_types=allowed_exam_types,
                allowed_statuses=allowed_statuses,
            )

        # ====================================================
        # BRANCH ADMIN SCOPE
        # ====================================================

        if (
            current_role == "branch_admin"
            and user_branch_id
            and branch.id != user_branch_id
        ):
            abort(403)

        # ====================================================
        # PROGRAM
        # ====================================================

        program = (
            Program.query
            .filter(
                Program.id == program_id
            )
            .first()
        )

        if not program:

            flash(
                "Selected program was not found.",
                "danger"
            )

            return render_template(
                "backend/pages/exams/edit_exam.html",
                exam=exam,
                institutions=institutions,
                branches=branches,
                programs=programs,
                assessment_plans=assessment_plans,
                academic_years=academic_years,
                terms=terms,
                allowed_exam_types=allowed_exam_types,
                allowed_statuses=allowed_statuses,
            )

        # ====================================================
        # PROGRAM → INSTITUTION
        # ====================================================

        if program.institution_id != institution.id:

            flash(
                "Selected program does not belong to the selected institution.",
                "danger"
            )

            return render_template(
                "backend/pages/exams/edit_exam.html",
                exam=exam,
                institutions=institutions,
                branches=branches,
                programs=programs,
                assessment_plans=assessment_plans,
                academic_years=academic_years,
                terms=terms,
                allowed_exam_types=allowed_exam_types,
                allowed_statuses=allowed_statuses,
            )

        # ====================================================
        # PROGRAM → BRANCH
        #
        # NULL = available to multiple branches
        # ====================================================

        if (
            getattr(
                program,
                "branch_id",
                None
            )
            and program.branch_id
            != branch.id
        ):

            flash(
                "Selected program is not available in this branch.",
                "danger"
            )

            return render_template(
                "backend/pages/exams/edit_exam.html",
                exam=exam,
                institutions=institutions,
                branches=branches,
                programs=programs,
                assessment_plans=assessment_plans,
                academic_years=academic_years,
                terms=terms,
                allowed_exam_types=allowed_exam_types,
                allowed_statuses=allowed_statuses,
            )

        # ====================================================
        # ACADEMIC YEAR
        # ====================================================

        academic_year = (
            AcademicYear.query
            .filter(
                AcademicYear.id
                == academic_year_id
            )
            .first()
        )

        if not academic_year:

            flash(
                "Selected academic year was not found.",
                "danger"
            )

            return render_template(
                "backend/pages/exams/edit_exam.html",
                exam=exam,
                institutions=institutions,
                branches=branches,
                programs=programs,
                assessment_plans=assessment_plans,
                academic_years=academic_years,
                terms=terms,
                allowed_exam_types=allowed_exam_types,
                allowed_statuses=allowed_statuses,
            )

        # ====================================================
        # ACADEMIC YEAR → INSTITUTION
        # ====================================================

        if hasattr(
            AcademicYear,
            "institution_id"
        ):

            if (
                academic_year.institution_id
                != institution.id
            ):

                flash(
                    "Selected academic year does not belong to the selected institution.",
                    "danger"
                )

                return render_template(
                    "backend/pages/exams/edit_exam.html",
                    exam=exam,
                    institutions=institutions,
                    branches=branches,
                    programs=programs,
                    assessment_plans=assessment_plans,
                    academic_years=academic_years,
                    terms=terms,
                    allowed_exam_types=allowed_exam_types,
                    allowed_statuses=allowed_statuses,
                )

        # ====================================================
        # TERM - OPTIONAL
        # ====================================================

        term = None

        if term_id:

            term = (
                Term.query
                .filter(
                    Term.id == term_id
                )
                .first()
            )

            if not term:

                flash(
                    "Selected term was not found.",
                    "danger"
                )

                return render_template(
                    "backend/pages/exams/edit_exam.html",
                    exam=exam,
                    institutions=institutions,
                    branches=branches,
                    programs=programs,
                    assessment_plans=assessment_plans,
                    academic_years=academic_years,
                    terms=terms,
                    allowed_exam_types=allowed_exam_types,
                    allowed_statuses=allowed_statuses,
                )

            # ------------------------------------------------
            # TERM → ACADEMIC YEAR
            # ------------------------------------------------

            if hasattr(
                Term,
                "academic_year_id"
            ):

                if (
                    term.academic_year_id
                    != academic_year.id
                ):

                    flash(
                        "Selected term does not belong to the selected academic year.",
                        "danger"
                    )

                    return render_template(
                        "backend/pages/exams/edit_exam.html",
                        exam=exam,
                        institutions=institutions,
                        branches=branches,
                        programs=programs,
                        assessment_plans=assessment_plans,
                        academic_years=academic_years,
                        terms=terms,
                        allowed_exam_types=allowed_exam_types,
                        allowed_statuses=allowed_statuses,
                    )

        # ====================================================
        # ASSESSMENT PLAN - OPTIONAL
        # ====================================================

        assessment_plan = None

        if assessment_plan_id:

            assessment_plan = (
                AssessmentPlan.query
                .filter(
                    AssessmentPlan.id
                    == assessment_plan_id
                )
                .first()
            )

            if not assessment_plan:

                flash(
                    "Selected assessment plan was not found.",
                    "danger"
                )

                return render_template(
                    "backend/pages/exams/edit_exam.html",
                    exam=exam,
                    institutions=institutions,
                    branches=branches,
                    programs=programs,
                    assessment_plans=assessment_plans,
                    academic_years=academic_years,
                    terms=terms,
                    allowed_exam_types=allowed_exam_types,
                    allowed_statuses=allowed_statuses,
                )

            # ------------------------------------------------
            # PLAN → INSTITUTION
            # ------------------------------------------------

            if hasattr(
                AssessmentPlan,
                "institution_id"
            ):

                if (
                    assessment_plan.institution_id
                    != institution.id
                ):

                    flash(
                        "Selected assessment plan does not belong to the selected institution.",
                        "danger"
                    )

                    return render_template(
                        "backend/pages/exams/edit_exam.html",
                        exam=exam,
                        institutions=institutions,
                        branches=branches,
                        programs=programs,
                        assessment_plans=assessment_plans,
                        academic_years=academic_years,
                        terms=terms,
                        allowed_exam_types=allowed_exam_types,
                        allowed_statuses=allowed_statuses,
                    )

            # ------------------------------------------------
            # PLAN → PROGRAM
            # ------------------------------------------------

            if hasattr(
                AssessmentPlan,
                "program_id"
            ):

                if (
                    assessment_plan.program_id
                    != program.id
                ):

                    flash(
                        "Selected assessment plan does not belong to the selected program.",
                        "danger"
                    )

                    return render_template(
                        "backend/pages/exams/edit_exam.html",
                        exam=exam,
                        institutions=institutions,
                        branches=branches,
                        programs=programs,
                        assessment_plans=assessment_plans,
                        academic_years=academic_years,
                        terms=terms,
                        allowed_exam_types=allowed_exam_types,
                        allowed_statuses=allowed_statuses,
                    )

        # ====================================================
        # DATE VALIDATION
        # ====================================================

        parsed_start_date = None
        parsed_end_date = None

        if start_date:

            try:

                parsed_start_date = (
                    datetime.strptime(
                        start_date,
                        "%Y-%m-%d"
                    ).date()
                )

            except ValueError:

                flash(
                    "Invalid start date.",
                    "danger"
                )

                return render_template(
                    "backend/pages/exams/edit_exam.html",
                    exam=exam,
                    institutions=institutions,
                    branches=branches,
                    programs=programs,
                    assessment_plans=assessment_plans,
                    academic_years=academic_years,
                    terms=terms,
                    allowed_exam_types=allowed_exam_types,
                    allowed_statuses=allowed_statuses,
                )

        if end_date:

            try:

                parsed_end_date = (
                    datetime.strptime(
                        end_date,
                        "%Y-%m-%d"
                    ).date()
                )

            except ValueError:

                flash(
                    "Invalid end date.",
                    "danger"
                )

                return render_template(
                    "backend/pages/exams/edit_exam.html",
                    exam=exam,
                    institutions=institutions,
                    branches=branches,
                    programs=programs,
                    assessment_plans=assessment_plans,
                    academic_years=academic_years,
                    terms=terms,
                    allowed_exam_types=allowed_exam_types,
                    allowed_statuses=allowed_statuses,
                )

        if (
            parsed_start_date
            and parsed_end_date
            and parsed_end_date < parsed_start_date
        ):

            flash(
                "End date cannot be earlier than start date.",
                "danger"
            )

            return render_template(
                "backend/pages/exams/edit_exam.html",
                exam=exam,
                institutions=institutions,
                branches=branches,
                programs=programs,
                assessment_plans=assessment_plans,
                academic_years=academic_years,
                terms=terms,
                allowed_exam_types=allowed_exam_types,
                allowed_statuses=allowed_statuses,
            )

        # ====================================================
        # CODE VALIDATION
        # ====================================================

        if not code:

            flash(
                "Exam code is required.",
                "danger"
            )

            return render_template(
                "backend/pages/exams/edit_exam.html",
                exam=exam,
                institutions=institutions,
                branches=branches,
                programs=programs,
                assessment_plans=assessment_plans,
                academic_years=academic_years,
                terms=terms,
                allowed_exam_types=allowed_exam_types,
                allowed_statuses=allowed_statuses,
            )

        # ====================================================
        # DUPLICATE CODE CHECK
        #
        # Ignore current exam itself
        # ====================================================

        duplicate_exam = (
            Exam.query
            .filter(
                db.func.upper(
                    Exam.code
                ) == code.upper(),

                Exam.id != exam.id
            )
            .first()
        )

        if duplicate_exam:

            flash(
                f"Exam code '{code}' is already used by another exam.",
                "danger"
            )

            return render_template(
                "backend/pages/exams/edit_exam.html",
                exam=exam,
                institutions=institutions,
                branches=branches,
                programs=programs,
                assessment_plans=assessment_plans,
                academic_years=academic_years,
                terms=terms,
                allowed_exam_types=allowed_exam_types,
                allowed_statuses=allowed_statuses,
            )

        # ====================================================
        # UPDATE EXAM
        # ====================================================

        exam.institution_id = institution.id

        exam.branch_id = branch.id

        exam.program_id = program.id

        # Optional
        exam.assessment_plan_id = (
            assessment_plan.id
            if assessment_plan
            else None
        )

        exam.academic_year_id = (
            academic_year.id
        )

        # Optional
        exam.term_id = (
            term.id
            if term
            else None
        )

        exam.name = name

        exam.code = code

        exam.exam_type = exam_type

        exam.description = (
            description
            if description
            else None
        )

        exam.start_date = parsed_start_date

        exam.end_date = parsed_end_date

        exam.status = status

        # ====================================================
        # SAVE
        # ====================================================

        try:

            db.session.commit()

            flash(
                f"Exam '{exam.name}' was updated successfully.",
                "success"
            )

            return redirect(
                url_for(
                    "main.all_exams"
                )
            )

        except Exception:

            db.session.rollback()

            current_app.logger.exception(
                "Error while updating exam"
            )

            flash(
                "An error occurred while updating the exam. Please try again.",
                "danger"
            )

            return render_template(
                "backend/pages/exams/edit_exam.html",
                exam=exam,
                institutions=institutions,
                branches=branches,
                programs=programs,
                assessment_plans=assessment_plans,
                academic_years=academic_years,
                terms=terms,
                allowed_exam_types=allowed_exam_types,
                allowed_statuses=allowed_statuses,
            )

    # ========================================================
    # GET
    # ========================================================

    return render_template(
        "backend/pages/exams/edit_exam.html",

        exam=exam,

        institutions=institutions,

        branches=branches,

        programs=programs,

        assessment_plans=assessment_plans,

        academic_years=academic_years,

        terms=terms,

        allowed_exam_types=allowed_exam_types,

        allowed_statuses=allowed_statuses,
        user=current_user
    )




# ============================================================
# DELETE EXAM
# ============================================================

@bp.route(
    "/exams/<int:exam_id>/delete",
    methods=["POST"]
)
@login_required
def delete_exam(exam_id):

    if not _exam_can_manage():
        abort(403)

    # --------------------------------------------------------
    # GET EXAM WITH USER SCOPE
    # --------------------------------------------------------

    query = _exam_scope_query(
        Exam.query
    )

    exam = (
        query
        .filter(
            Exam.id == exam_id
        )
        .first_or_404()
    )

    try:

        db.session.delete(
            exam
        )

        db.session.commit()

        flash(
            "Exam deleted successfully.",
            "success"
        )

    except Exception as e:

        db.session.rollback()

        flash(
            "This exam cannot be deleted because it may already have related examination records.",
            "danger"
        )

    return redirect(
        url_for(
            "main.all_exams"
        )
    )





# ============================================================
# EXAM SUBJECT ROUTES
# ============================================================

# ============================================================
# ROLE PERMISSION
# ============================================================

def _exam_subject_can_manage():

    role = getattr(
        current_user,
        "role",
        None
    )

    return role in {
        "superadmin",
        "school_admin",
        "branch_admin",
    }


# ============================================================
# ROLE PERMISSION - VIEW
# ============================================================

def _exam_subject_can_view():

    role = getattr(
        current_user,
        "role",
        None
    )

    return role in {
        "superadmin",
        "school_admin",
        "branch_admin",
        "teacher",
    }


# ============================================================
# HELPER
# CURRENT USER INSTITUTION / BRANCH SCOPE
# ============================================================

def _exam_subject_scope_query(query):

    role = getattr(
        current_user,
        "role",
        None
    )

    # --------------------------------------------------------
    # SUPERADMIN
    # --------------------------------------------------------

    if role == "superadmin":
        return query

    # --------------------------------------------------------
    # SCHOOL ADMIN
    # --------------------------------------------------------

    if role == "school_admin":

        institution_id = getattr(
            current_user,
            "institution_id",
            None
        )

        if not institution_id:
            return query.filter(False)

        return query.filter(
            Exam.institution_id == institution_id
        )

    # --------------------------------------------------------
    # BRANCH ADMIN
    # --------------------------------------------------------

    if role == "branch_admin":

        institution_id = getattr(
            current_user,
            "institution_id",
            None
        )

        branch_id = getattr(
            current_user,
            "branch_id",
            None
        )

        if not institution_id or not branch_id:
            return query.filter(False)

        return query.filter(
            Exam.institution_id == institution_id,
            Exam.branch_id == branch_id
        )

    # --------------------------------------------------------
    # OTHER ROLES
    # --------------------------------------------------------

    return query.filter(False)


# ============================================================
# ADD EXAM SUBJECT
# ============================================================

@bp.route(
    "/exam-subjects/add",
    methods=["GET", "POST"]
)
@login_required
def add_exam_subject():

    # ========================================================
    # ROLE SECURITY
    # ========================================================

    allowed_roles = {
        "superadmin",
        "school_admin",
        "branch_admin",
    }

    current_role = getattr(
        current_user,
        "role",
        None
    )

    if current_role not in allowed_roles:
        abort(403)

    # ========================================================
    # CURRENT USER SCOPE
    # ========================================================

    institution_id = getattr(
        current_user,
        "institution_id",
        None
    )

    branch_id = getattr(
        current_user,
        "branch_id",
        None
    )

    # ========================================================
    # EXAM QUERY
    # ========================================================

    exams_query = (
        Exam.query
        .join(
            Program,
            Program.id == Exam.program_id
        )
    )

    # --------------------------------------------------------
    # SUPERADMIN
    # --------------------------------------------------------

    if current_role == "superadmin":

        pass

    # --------------------------------------------------------
    # SCHOOL ADMIN
    # --------------------------------------------------------

    elif current_role == "school_admin":

        if not institution_id:
            abort(403)

        exams_query = exams_query.filter(
            Exam.institution_id == institution_id
        )

    # --------------------------------------------------------
    # BRANCH ADMIN
    # --------------------------------------------------------

    elif current_role == "branch_admin":

        if not institution_id or not branch_id:
            abort(403)

        exams_query = exams_query.filter(
            Exam.institution_id == institution_id,
            Exam.branch_id == branch_id
        )

    exams = (
        exams_query
        .order_by(
            Exam.name.asc()
        )
        .all()
    )

    # ========================================================
    # POST
    # ========================================================

    if request.method == "POST":

        # ====================================================
        # EXAM
        # ====================================================

        exam_id = request.form.get(
            "exam_id",
            type=int
        )

        if not exam_id:

            flash(
                "Please select an exam.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.add_exam_subject"
                )
            )

        # ====================================================
        # LOAD EXAM WITH SECURITY
        # ====================================================

        exam_query = Exam.query.filter(
            Exam.id == exam_id
        )

        if current_role == "school_admin":

            exam_query = exam_query.filter(
                Exam.institution_id == institution_id
            )

        elif current_role == "branch_admin":

            exam_query = exam_query.filter(
                Exam.institution_id == institution_id,
                Exam.branch_id == branch_id
            )

        exam = exam_query.first()

        if not exam:

            flash(
                "The selected exam does not exist or you do not have permission to manage it.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.add_exam_subject"
                )
            )

        # ====================================================
        # PROGRAM
        # ====================================================

        if not exam.program_id:

            flash(
                "The selected exam has no program assigned.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.add_exam_subject"
                )
            )

        program = (
            Program.query
            .filter(
                Program.id == exam.program_id
            )
            .first()
        )

        if not program:

            flash(
                "The program assigned to this exam was not found.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.add_exam_subject"
                )
            )

        # ====================================================
        # SUBJECT IDS
        #
        # Accept BOTH:
        #
        # subject_ids[]
        # subject_id[]
        #
        # This prevents template naming mismatch.
        # ====================================================

        subject_ids = request.form.getlist(
            "subject_ids[]"
        )

        if not subject_ids:

            subject_ids = request.form.getlist(
                "subject_id[]"
            )

        # ====================================================
        # CLASS IDS
        # ====================================================

        class_ids = request.form.getlist(
            "class_ids[]"
        )

        if not class_ids:

            class_ids = request.form.getlist(
                "class_id[]"
            )

        # ====================================================
        # SECTION IDS
        # ====================================================

        section_ids = request.form.getlist(
            "section_ids[]"
        )

        if not section_ids:

            section_ids = request.form.getlist(
                "section_id[]"
            )

        # ====================================================
        # TEACHER IDS
        # ====================================================

        teacher_ids = request.form.getlist(
            "teacher_ids[]"
        )

        if not teacher_ids:

            teacher_ids = request.form.getlist(
                "teacher_id[]"
            )

        # ====================================================
        # MAX MARKS
        # ====================================================

        max_marks_list = request.form.getlist(
            "max_marks[]"
        )

        # ====================================================
        # PASS MARKS
        # ====================================================

        pass_marks_list = request.form.getlist(
            "pass_marks[]"
        )

        # ====================================================
        # WEIGHT
        # ====================================================

        weight_list = request.form.getlist(
            "weight[]"
        )

        # ====================================================
        # DISPLAY ORDER
        # ====================================================

        display_order_list = request.form.getlist(
            "display_order[]"
        )

        # ====================================================
        # STATUS
        # ====================================================

        status = request.form.get(
            "status",
            "active"
        )

        status = (
            status.strip().lower()
            if status
            else "active"
        )

        if status not in {
            "active",
            "inactive"
        }:

            status = "active"

        # ====================================================
        # CHECK SUBJECT ROWS
        # ====================================================

        if not subject_ids:

            flash(
                "Please add at least one subject.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.add_exam_subject",
                    exam_id=exam.id
                )
            )

        # ====================================================
        # ROW COUNT
        # ====================================================

        row_count = len(subject_ids)

        # ====================================================
        # NORMALIZE LIST LENGTHS
        # ========================================================

        def normalize_list(
            values,
            count,
            default_value=""
        ):

            values = list(values)

            if len(values) < count:

                values.extend(
                    [default_value]
                    * (
                        count
                        - len(values)
                    )
                )

            elif len(values) > count:

                values = values[:count]

            return values

        class_ids = normalize_list(
            class_ids,
            row_count,
            ""
        )

        section_ids = normalize_list(
            section_ids,
            row_count,
            ""
        )

        teacher_ids = normalize_list(
            teacher_ids,
            row_count,
            ""
        )

        max_marks_list = normalize_list(
            max_marks_list,
            row_count,
            "100"
        )

        pass_marks_list = normalize_list(
            pass_marks_list,
            row_count,
            "50"
        )

        weight_list = normalize_list(
            weight_list,
            row_count,
            "100"
        )

        display_order_list = normalize_list(
            display_order_list,
            row_count,
            ""
        )

        # ====================================================
        # VALID PROGRAM SUBJECTS
        #
        # Subject must belong to:
        #
        # Exam.program_id
        #
        # AND
        #
        # Exam.institution_id
        # ====================================================

        valid_subject_query = (
            Subject.query
            .filter(
                Subject.program_id == exam.program_id,
                Subject.institution_id == exam.institution_id,
                Subject.status == "active"
            )
        )

        # ----------------------------------------------------
        # Branch
        #
        # branch_id NULL = shared subject
        # ----------------------------------------------------

        if exam.branch_id:

            valid_subject_query = (
                valid_subject_query
                .filter(
                    db.or_(
                        Subject.branch_id == exam.branch_id,
                        Subject.branch_id.is_(None)
                    )
                )
            )

        valid_subjects = (
            valid_subject_query
            .all()
        )

        valid_subject_map = {
            int(subject.id): subject
            for subject in valid_subjects
        }

        # ====================================================
        # VALID PROGRAM CLASSES
        # ====================================================

        valid_classes_query = (
            Class.query
            .filter(
                Class.program_id == exam.program_id,
                Class.institution_id == exam.institution_id
            )
        )

        # ----------------------------------------------------
        # Branch
        # ----------------------------------------------------

        if exam.branch_id:

            valid_classes_query = (
                valid_classes_query
                .filter(
                    Class.branch_id == exam.branch_id
                )
            )

        # ----------------------------------------------------
        # Academic Year
        # ----------------------------------------------------

        if exam.academic_year_id:

            valid_classes_query = (
                valid_classes_query
                .filter(
                    Class.academic_year_id ==
                    exam.academic_year_id
                )
            )

        valid_classes = (
            valid_classes_query
            .all()
        )

        valid_class_map = {
            int(item.id): item
            for item in valid_classes
        }

        # ====================================================
        # VALID SECTIONS
        # ====================================================

        valid_class_ids = list(
            valid_class_map.keys()
        )

        valid_section_map = {}

        if valid_class_ids:

            valid_sections = (
                Section.query
                .filter(
                    Section.class_id.in_(
                        valid_class_ids
                    )
                )
                .all()
            )

            valid_section_map = {
                int(section.id): section
                for section in valid_sections
            }

        # ====================================================
        # VALID TEACHERS
        #
        # Teacher must be assigned through TeacherSubject.
        #
        # Program:
        #
        # Exam
        #   ↓
        # Program
        #   ↓
        # TeacherSubject
        #   ↓
        # Teacher
        # ====================================================

        valid_teacher_query = (
            Teacher.query
            .join(
                TeacherSubject,
                TeacherSubject.teacher_id ==
                Teacher.id
            )
            .filter(
                Teacher.institution_id ==
                exam.institution_id,

                Teacher.is_active.is_(True),

                Teacher.status == "active",

                TeacherSubject.institution_id ==
                exam.institution_id,

                TeacherSubject.program_id ==
                exam.program_id,

                TeacherSubject.status == "active"
            )
        )

        # ----------------------------------------------------
        # Branch
        # ----------------------------------------------------

        if exam.branch_id:

            valid_teacher_query = (
                valid_teacher_query
                .filter(
                    Teacher.branch_id ==
                    exam.branch_id
                )
                .filter(
                    db.or_(
                        TeacherSubject.branch_id ==
                        exam.branch_id,

                        TeacherSubject.branch_id.is_(None)
                    )
                )
            )

        valid_teachers = (
            valid_teacher_query
            .distinct()
            .all()
        )

        valid_teacher_map = {
            int(teacher.id): teacher
            for teacher in valid_teachers
        }

        # ====================================================
        # EXISTING EXAM SUBJECTS
        # ====================================================

        existing_rows = (
            ExamSubject.query
            .filter(
                ExamSubject.exam_id ==
                exam.id
            )
            .all()
        )

        existing_combinations = set()

        for item in existing_rows:

            existing_combinations.add(
                (
                    int(item.subject_id),

                    int(item.class_id)
                    if item.class_id is not None
                    else None,

                    int(item.section_id)
                    if item.section_id is not None
                    else None
                )
            )

        # ====================================================
        # REQUEST DUPLICATES
        # ====================================================

        request_combinations = set()

        # ====================================================
        # NEW OBJECTS
        # ====================================================

        new_exam_subjects = []

        # ====================================================
        # PROCESS EACH ROW
        # ====================================================

        for index in range(row_count):

            row_number = index + 1

            # ==================================================
            # SUBJECT
            # ==================================================

            raw_subject_id = (
                subject_ids[index]
                if index < len(subject_ids)
                else ""
            )

            raw_subject_id = (
                str(raw_subject_id).strip()
            )

            if not raw_subject_id:

                flash(
                    f"Please select a subject on row {row_number}.",
                    "danger"
                )

                return redirect(
                    url_for(
                        "main.add_exam_subject",
                        exam_id=exam.id
                    )
                )

            try:

                subject_id = int(
                    raw_subject_id
                )

            except (
                TypeError,
                ValueError
            ):

                flash(
                    f"Invalid subject on row {row_number}.",
                    "danger"
                )

                return redirect(
                    url_for(
                        "main.add_exam_subject",
                        exam_id=exam.id
                    )
                )

            subject = valid_subject_map.get(
                subject_id
            )

            if not subject:

                flash(
                    f"Subject on row {row_number} does not belong to the selected exam program.",
                    "danger"
                )

                return redirect(
                    url_for(
                        "main.add_exam_subject",
                        exam_id=exam.id
                    )
                )

            # ==================================================
            # CLASS
            # ==================================================

            raw_class_id = (
                class_ids[index]
                if index < len(class_ids)
                else ""
            )

            raw_class_id = (
                str(raw_class_id).strip()
                if raw_class_id
                else ""
            )

            class_id = None
            selected_class = None

            if raw_class_id:

                try:

                    class_id = int(
                        raw_class_id
                    )

                except (
                    TypeError,
                    ValueError
                ):

                    flash(
                        f"Invalid class on row {row_number}.",
                        "danger"
                    )

                    return redirect(
                        url_for(
                            "main.add_exam_subject",
                            exam_id=exam.id
                        )
                    )

                selected_class = (
                    valid_class_map.get(
                        class_id
                    )
                )

                if not selected_class:

                    flash(
                        f"Class on row {row_number} does not belong to the selected exam program.",
                        "danger"
                    )

                    return redirect(
                        url_for(
                            "main.add_exam_subject",
                            exam_id=exam.id
                        )
                    )

            # ==================================================
            # SECTION
            # ==================================================

            raw_section_id = (
                section_ids[index]
                if index < len(section_ids)
                else ""
            )

            raw_section_id = (
                str(raw_section_id).strip()
                if raw_section_id
                else ""
            )

            section_id = None

            if raw_section_id:

                # ----------------------------------------------
                # Section requires Class
                # ----------------------------------------------

                if not class_id:

                    flash(
                        f"Please select a class before selecting a section on row {row_number}.",
                        "danger"
                    )

                    return redirect(
                        url_for(
                            "main.add_exam_subject",
                            exam_id=exam.id
                        )
                    )

                try:

                    section_id = int(
                        raw_section_id
                    )

                except (
                    TypeError,
                    ValueError
                ):

                    flash(
                        f"Invalid section on row {row_number}.",
                        "danger"
                    )

                    return redirect(
                        url_for(
                            "main.add_exam_subject",
                            exam_id=exam.id
                        )
                    )

                section = (
                    valid_section_map.get(
                        section_id
                    )
                )

                if not section:

                    flash(
                        f"Section on row {row_number} is not valid.",
                        "danger"
                    )

                    return redirect(
                        url_for(
                            "main.add_exam_subject",
                            exam_id=exam.id
                        )
                    )

                if int(section.class_id) != int(
                    class_id
                ):

                    flash(
                        f"Section on row {row_number} does not belong to the selected class.",
                        "danger"
                    )

                    return redirect(
                        url_for(
                            "main.add_exam_subject",
                            exam_id=exam.id
                        )
                    )

            # ==================================================
            # TEACHER
            # ==================================================

            raw_teacher_id = (
                teacher_ids[index]
                if index < len(teacher_ids)
                else ""
            )

            raw_teacher_id = (
                str(raw_teacher_id).strip()
                if raw_teacher_id
                else ""
            )

            teacher_id = None

            if raw_teacher_id:

                try:

                    teacher_id = int(
                        raw_teacher_id
                    )

                except (
                    TypeError,
                    ValueError
                ):

                    flash(
                        f"Invalid teacher on row {row_number}.",
                        "danger"
                    )

                    return redirect(
                        url_for(
                            "main.add_exam_subject",
                            exam_id=exam.id
                        )
                    )

                teacher = valid_teacher_map.get(
                    teacher_id
                )

                if not teacher:

                    flash(
                        f"Teacher on row {row_number} is not assigned to the selected program.",
                        "danger"
                    )

                    return redirect(
                        url_for(
                            "main.add_exam_subject",
                            exam_id=exam.id
                        )
                    )

                # ----------------------------------------------
                # Verify TeacherSubject
                # Program + Subject
                # ----------------------------------------------

                teacher_assignment_query = (
                    TeacherSubject.query
                    .filter(
                        TeacherSubject.teacher_id ==
                        teacher_id,

                        TeacherSubject.program_id ==
                        exam.program_id,

                        TeacherSubject.subject_id ==
                        subject_id,

                        TeacherSubject.institution_id ==
                        exam.institution_id,

                        TeacherSubject.status ==
                        "active"
                    )
                )

                # ------------------------------------------------
                # Branch assignment
                # ------------------------------------------------

                if exam.branch_id:

                    teacher_assignment_query = (
                        teacher_assignment_query
                        .filter(
                            db.or_(
                                TeacherSubject.branch_id ==
                                exam.branch_id,

                                TeacherSubject.branch_id.is_(None)
                            )
                        )
                    )

                teacher_assignment = (
                    teacher_assignment_query
                    .first()
                )

                # ------------------------------------------------
                # If no subject-specific assignment exists,
                # allow program-level assignment.
                # ------------------------------------------------

                if not teacher_assignment:

                    teacher_assignment_query = (
                        TeacherSubject.query
                        .filter(
                            TeacherSubject.teacher_id ==
                            teacher_id,

                            TeacherSubject.program_id ==
                            exam.program_id,

                            TeacherSubject.institution_id ==
                            exam.institution_id,

                            TeacherSubject.status ==
                            "active",

                            db.or_(
                                TeacherSubject.subject_id.is_(None),
                                TeacherSubject.subject_id ==
                                subject_id
                            )
                        )
                    )

                    if exam.branch_id:

                        teacher_assignment_query = (
                            teacher_assignment_query
                            .filter(
                                db.or_(
                                    TeacherSubject.branch_id ==
                                    exam.branch_id,

                                    TeacherSubject.branch_id.is_(None)
                                )
                            )
                        )

                    teacher_assignment = (
                        teacher_assignment_query
                        .first()
                    )

                if not teacher_assignment:

                    flash(
                        f"{teacher.full_name} is not assigned to {subject.name}.",
                        "danger"
                    )

                    return redirect(
                        url_for(
                            "main.add_exam_subject",
                            exam_id=exam.id
                        )
                    )

            # ==================================================
            # MAX MARKS
            # ==================================================

            raw_max_marks = (
                max_marks_list[index]
                if index < len(max_marks_list)
                else "100"
            )

            try:

                max_marks = float(
                    raw_max_marks
                )

            except (
                TypeError,
                ValueError
            ):

                flash(
                    f"Invalid maximum marks on row {row_number}.",
                    "danger"
                )

                return redirect(
                    url_for(
                        "main.add_exam_subject",
                        exam_id=exam.id
                    )
                )

            if max_marks <= 0:

                flash(
                    f"Maximum marks must be greater than zero on row {row_number}.",
                    "danger"
                )

                return redirect(
                    url_for(
                        "main.add_exam_subject",
                        exam_id=exam.id
                    )
                )

            # ==================================================
            # PASS MARKS
            # ==================================================

            raw_pass_marks = (
                pass_marks_list[index]
                if index < len(pass_marks_list)
                else "50"
            )

            try:

                pass_marks = float(
                    raw_pass_marks
                )

            except (
                TypeError,
                ValueError
            ):

                flash(
                    f"Invalid pass marks on row {row_number}.",
                    "danger"
                )

                return redirect(
                    url_for(
                        "main.add_exam_subject",
                        exam_id=exam.id
                    )
                )

            if pass_marks < 0:

                flash(
                    f"Pass marks cannot be negative on row {row_number}.",
                    "danger"
                )

                return redirect(
                    url_for(
                        "main.add_exam_subject",
                        exam_id=exam.id
                    )
                )

            if pass_marks > max_marks:

                flash(
                    f"Pass marks cannot exceed maximum marks on row {row_number}.",
                    "danger"
                )

                return redirect(
                    url_for(
                        "main.add_exam_subject",
                        exam_id=exam.id
                    )
                )

            # ==================================================
            # WEIGHT
            # ==================================================

            raw_weight = (
                weight_list[index]
                if index < len(weight_list)
                else "100"
            )

            try:

                weight = float(
                    raw_weight
                )

            except (
                TypeError,
                ValueError
            ):

                flash(
                    f"Invalid weight on row {row_number}.",
                    "danger"
                )

                return redirect(
                    url_for(
                        "main.add_exam_subject",
                        exam_id=exam.id
                    )
                )

            if weight <= 0:

                flash(
                    f"Weight must be greater than zero on row {row_number}.",
                    "danger"
                )

                return redirect(
                    url_for(
                        "main.add_exam_subject",
                        exam_id=exam.id
                    )
                )

            # ==================================================
            # DISPLAY ORDER
            # ==================================================

            raw_display_order = (
                display_order_list[index]
                if index < len(display_order_list)
                else ""
            )

            try:

                display_order = int(
                    raw_display_order
                )

            except (
                TypeError,
                ValueError
            ):

                display_order = (
                    index + 1
                )

            if display_order <= 0:

                display_order = (
                    index + 1
                )

            # ==================================================
            # DUPLICATE KEY
            #
            # exam + subject + class + section
            # ==================================================

            combination = (
                subject_id,
                class_id,
                section_id
            )

            # ==================================================
            # DUPLICATE IN CURRENT REQUEST
            # ==================================================

            if combination in request_combinations:

                class_text = (
                    selected_class.name
                    if selected_class
                    else "All Classes"
                )

                flash(
                    f"{subject.name} is duplicated on row {row_number} for {class_text}.",
                    "danger"
                )

                return redirect(
                    url_for(
                        "main.add_exam_subject",
                        exam_id=exam.id
                    )
                )

            request_combinations.add(
                combination
            )

            # ==================================================
            # DUPLICATE IN DATABASE
            # ==================================================

            if combination in existing_combinations:

                class_text = (
                    selected_class.name
                    if selected_class
                    else "All Classes"
                )

                flash(
                    f"{subject.name} already exists for {class_text}.",
                    "warning"
                )

                return redirect(
                    url_for(
                        "main.add_exam_subject",
                        exam_id=exam.id
                    )
                )

            # ==================================================
            # CREATE EXAM SUBJECT
            # ==================================================

            exam_subject = ExamSubject(
                exam_id=exam.id,

                subject_id=subject_id,

                class_id=class_id,

                section_id=section_id,

                teacher_id=teacher_id,

                max_marks=max_marks,

                pass_marks=pass_marks,

                weight=weight,

                display_order=display_order,

                status=status
            )

            new_exam_subjects.append(
                exam_subject
            )

        # ====================================================
        # NOTHING TO SAVE
        # ====================================================

        if not new_exam_subjects:

            flash(
                "No exam subjects were prepared.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.add_exam_subject",
                    exam_id=exam.id
                )
            )

        # ====================================================
        # SAVE ALL
        # ====================================================

        try:

            db.session.add_all(
                new_exam_subjects
            )

            db.session.commit()

        except Exception as exc:

            db.session.rollback()

            current_app.logger.exception(
                "Failed to create multiple exam subjects: %s",
                exc
            )

            flash(
                "An error occurred while adding the exam subjects. No changes were saved.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.add_exam_subject",
                    exam_id=exam.id
                )
            )

        # ====================================================
        # SUCCESS
        # ====================================================

        flash(
            f"{len(new_exam_subjects)} exam subject(s) added successfully.",
            "success"
        )

        return redirect(
            url_for(
                "main.all_exam_subjects",
                exam_id=exam.id
            )
        )

    # ========================================================
    # GET DATA
    # ========================================================

    # ========================================================
    # AVAILABLE PROGRAM IDS
    # ========================================================

    program_ids = list({
        int(exam.program_id)
        for exam in exams
        if exam.program_id
    })

    # ========================================================
    # SUBJECTS
    #
    # IMPORTANT:
    # All subjects belonging to available programs.
    # ========================================================

    subjects = []

    if program_ids:

        subjects_query = (
            Subject.query
            .filter(
                Subject.program_id.in_(
                    program_ids
                ),
                Subject.status == "active"
            )
        )

        # ----------------------------------------------------
        # Institution
        # ----------------------------------------------------

        if current_role != "superadmin":

            subjects_query = (
                subjects_query
                .filter(
                    Subject.institution_id ==
                    institution_id
                )
            )

        # ----------------------------------------------------
        # Branch
        #
        # NULL branch = shared subject
        # ----------------------------------------------------

        if current_role == "branch_admin":

            subjects_query = (
                subjects_query
                .filter(
                    db.or_(
                        Subject.branch_id ==
                        branch_id,

                        Subject.branch_id.is_(None)
                    )
                )
            )

        subjects = (
            subjects_query
            .order_by(
                Subject.name.asc()
            )
            .all()
        )

    # ========================================================
    # CLASSES
    # ========================================================

    classes = []

    if program_ids:

        classes_query = (
            Class.query
            .filter(
                Class.program_id.in_(
                    program_ids
                )
            )
        )

        # ----------------------------------------------------
        # Institution
        # ----------------------------------------------------

        if current_role != "superadmin":

            classes_query = (
                classes_query
                .filter(
                    Class.institution_id ==
                    institution_id
                )
            )

        # ----------------------------------------------------
        # Branch
        # ----------------------------------------------------

        if current_role == "branch_admin":

            classes_query = (
                classes_query
                .filter(
                    Class.branch_id ==
                    branch_id
                )
            )

        classes = (
            classes_query
            .order_by(
                Class.name.asc()
            )
            .all()
        )

    # ========================================================
    # SECTIONS
    # ========================================================

    sections = []

    available_class_ids = [
        int(item.id)
        for item in classes
    ]

    if available_class_ids:

        sections = (
            Section.query
            .filter(
                Section.class_id.in_(
                    available_class_ids
                )
            )
            .order_by(
                Section.name.asc()
            )
            .all()
        )

    # ========================================================
    # TEACHERS
    #
    # ONLY PROGRAM ASSIGNED TEACHERS
    #
    # NOT ALL BRANCH TEACHERS
    # ========================================================

    teachers = []

    if program_ids:

        teachers_query = (
            Teacher.query
            .join(
                TeacherSubject,
                TeacherSubject.teacher_id ==
                Teacher.id
            )
            .filter(
                Teacher.is_active.is_(True),

                Teacher.status == "active",

                TeacherSubject.program_id.in_(
                    program_ids
                ),

                TeacherSubject.status == "active"
            )
        )

        # ----------------------------------------------------
        # SUPERADMIN
        # ----------------------------------------------------

        if current_role == "superadmin":

            pass

        # ----------------------------------------------------
        # SCHOOL ADMIN
        # ----------------------------------------------------

        elif current_role == "school_admin":

            if not institution_id:
                abort(403)

            teachers_query = (
                teachers_query
                .filter(
                    Teacher.institution_id ==
                    institution_id,

                    TeacherSubject.institution_id ==
                    institution_id
                )
            )

        # ----------------------------------------------------
        # BRANCH ADMIN
        # ----------------------------------------------------

        elif current_role == "branch_admin":

            if not institution_id or not branch_id:
                abort(403)

            teachers_query = (
                teachers_query
                .filter(
                    Teacher.institution_id ==
                    institution_id,

                    Teacher.branch_id ==
                    branch_id,

                    db.or_(
                        TeacherSubject.branch_id ==
                        branch_id,

                        TeacherSubject.branch_id.is_(None)
                    )
                )
            )

        teachers = (
            teachers_query
            .distinct()
            .order_by(
                Teacher.full_name.asc()
            )
            .all()
        )

    # ========================================================
    # SELECTED EXAM
    # ========================================================

    selected_exam_id = request.args.get(
        "exam_id",
        type=int
    )

    # ========================================================
    # RENDER
    # ========================================================

    return render_template(
        "backend/pages/exam_subjects/add_exam_subject.html",

        exams=exams,

        subjects=subjects,

        classes=classes,

        sections=sections,

        teachers=teachers,

        selected_exam_id=selected_exam_id,

        user=current_user
    )


@bp.route(
    "/exam-subjects/bulk-add",
    methods=["GET", "POST"]
)
@login_required
def bulk_add_exam_subjects():

    # ========================================================
    # ROLE SECURITY
    # ========================================================

    allowed_roles = {
        "superadmin",
        "school_admin",
        "branch_admin",
    }

    raw_role = getattr(
        current_user,
        "role",
        None
    )

    if hasattr(raw_role, "value"):
        current_role = raw_role.value
    else:
        current_role = str(raw_role or "")

    current_role = (
        current_role
        .lower()
        .strip()
    )

    if current_role not in allowed_roles:
        abort(403)

    # ========================================================
    # CURRENT USER SCOPE
    # ========================================================

    institution_id = getattr(
        current_user,
        "institution_id",
        None
    )

    branch_id = getattr(
        current_user,
        "branch_id",
        None
    )

    # ========================================================
    # LOAD AVAILABLE EXAMS
    # ========================================================

    exams_query = (
        Exam.query
        .join(
            Program,
            Program.id == Exam.program_id
        )
        .filter(
            Exam.program_id.isnot(None)
        )
    )

    # --------------------------------------------------------
    # SUPERADMIN
    # --------------------------------------------------------

    if current_role == "superadmin":
        pass

    # --------------------------------------------------------
    # SCHOOL ADMIN
    # --------------------------------------------------------

    elif current_role == "school_admin":

        if not institution_id:
            abort(403)

        exams_query = exams_query.filter(
            Exam.institution_id == institution_id
        )

    # --------------------------------------------------------
    # BRANCH ADMIN
    # --------------------------------------------------------

    elif current_role == "branch_admin":

        if not institution_id or not branch_id:
            abort(403)

        exams_query = exams_query.filter(
            Exam.institution_id == institution_id,
            Exam.branch_id == branch_id
        )

    exams = (
        exams_query
        .order_by(
            Exam.name.asc()
        )
        .all()
    )

    # ========================================================
    # POST
    # ========================================================

    if request.method == "POST":

        # ====================================================
        # EXAM
        # ====================================================

        exam_id = request.form.get(
            "exam_id",
            type=int
        )

        if not exam_id:

            flash(
                "Please select an exam.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.bulk_add_exam_subjects"
                )
            )

        # ====================================================
        # LOAD EXAM WITH SECURITY
        # ====================================================

        exam_query = (
            Exam.query
            .filter(
                Exam.id == exam_id
            )
        )

        if current_role == "school_admin":

            exam_query = exam_query.filter(
                Exam.institution_id == institution_id
            )

        elif current_role == "branch_admin":

            exam_query = exam_query.filter(
                Exam.institution_id == institution_id,
                Exam.branch_id == branch_id
            )

        exam = exam_query.first()

        if not exam:

            flash(
                "The selected exam does not exist or you do not have permission to manage it.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.bulk_add_exam_subjects"
                )
            )

        # ====================================================
        # PROGRAM
        # ====================================================

        if not exam.program_id:

            flash(
                "The selected exam has no program assigned.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.bulk_add_exam_subjects",
                    exam_id=exam.id
                )
            )

        program = (
            Program.query
            .filter(
                Program.id == exam.program_id,
                Program.institution_id == exam.institution_id
            )
            .first()
        )

        if not program:

            flash(
                "The program assigned to this exam was not found.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.bulk_add_exam_subjects",
                    exam_id=exam.id
                )
            )

        # ====================================================
        # MAX MARKS
        # ====================================================

        raw_max_marks = request.form.get(
            "max_marks",
            "100"
        )

        try:

            max_marks = float(
                raw_max_marks
            )

        except (
            TypeError,
            ValueError
        ):

            flash(
                "Maximum marks must be a valid number.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.bulk_add_exam_subjects",
                    exam_id=exam.id
                )
            )

        if max_marks <= 0:

            flash(
                "Maximum marks must be greater than zero.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.bulk_add_exam_subjects",
                    exam_id=exam.id
                )
            )

        # ====================================================
        # PASS MARKS
        # ====================================================

        raw_pass_marks = request.form.get(
            "pass_marks",
            "50"
        )

        try:

            pass_marks = float(
                raw_pass_marks
            )

        except (
            TypeError,
            ValueError
        ):

            flash(
                "Pass marks must be a valid number.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.bulk_add_exam_subjects",
                    exam_id=exam.id
                )
            )

        if pass_marks < 0:

            flash(
                "Pass marks cannot be negative.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.bulk_add_exam_subjects",
                    exam_id=exam.id
                )
            )

        if pass_marks > max_marks:

            flash(
                "Pass marks cannot exceed maximum marks.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.bulk_add_exam_subjects",
                    exam_id=exam.id
                )
            )

        # ====================================================
        # WEIGHT
        # ====================================================

        raw_weight = request.form.get(
            "weight",
            "100"
        )

        try:

            weight = float(
                raw_weight
            )

        except (
            TypeError,
            ValueError
        ):

            flash(
                "Weight must be a valid number.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.bulk_add_exam_subjects",
                    exam_id=exam.id
                )
            )

        if weight <= 0:

            flash(
                "Weight must be greater than zero.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.bulk_add_exam_subjects",
                    exam_id=exam.id
                )
            )

        # ====================================================
        # STATUS
        # ====================================================

        status = request.form.get(
            "status",
            "active"
        )

        status = (
            status.strip().lower()
            if status
            else "active"
        )

        if status not in {
            "active",
            "inactive"
        }:

            status = "active"

        # ====================================================
        # LOAD SUBJECTS
        # ========================================================

        subjects_query = (
            Subject.query
            .filter(
                Subject.program_id == exam.program_id,
                Subject.institution_id == exam.institution_id,
                Subject.status == "active"
            )
        )

        if exam.branch_id:

            subjects_query = (
                subjects_query
                .filter(
                    db.or_(
                        Subject.branch_id == exam.branch_id,
                        Subject.branch_id.is_(None)
                    )
                )
            )

        subjects = (
            subjects_query
            .order_by(
                Subject.name.asc()
            )
            .all()
        )

        if not subjects:

            flash(
                "No active subjects were found for this exam program.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.bulk_add_exam_subjects",
                    exam_id=exam.id
                )
            )

        # ====================================================
        # LOAD CLASSES
        # ========================================================

        classes_query = (
            Class.query
            .filter(
                Class.program_id == exam.program_id,
                Class.institution_id == exam.institution_id
            )
        )

        if exam.branch_id:

            classes_query = (
                classes_query
                .filter(
                    Class.branch_id == exam.branch_id
                )
            )

        if exam.academic_year_id:

            classes_query = (
                classes_query
                .filter(
                    Class.academic_year_id ==
                    exam.academic_year_id
                )
            )

        classes = (
            classes_query
            .order_by(
                Class.name.asc()
            )
            .all()
        )

        if not classes:

            flash(
                "No classes were found for this exam program.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.bulk_add_exam_subjects",
                    exam_id=exam.id
                )
            )

        # ====================================================
        # EXISTING EXAM SUBJECTS
        # ====================================================

        existing_rows = (
            ExamSubject.query
            .filter(
                ExamSubject.exam_id == exam.id
            )
            .all()
        )

        existing_combinations = {
            (
                int(row.subject_id),

                int(row.class_id)
                if row.class_id is not None
                else None,

                int(row.section_id)
                if row.section_id is not None
                else None
            )
            for row in existing_rows
        }

        # ====================================================
        # LOAD TEACHER SUBJECT ASSIGNMENTS
        #
        # ONLY ACTIVE TEACHER ASSIGNMENTS
        # FOR THIS PROGRAM + SUBJECT
        # ====================================================

        teacher_query = (
            db.session.query(
                TeacherSubject,
                Teacher
            )
            .join(
                Teacher,
                Teacher.id ==
                TeacherSubject.teacher_id
            )
            .filter(
                Teacher.institution_id ==
                exam.institution_id,

                Teacher.is_active.is_(True),

                Teacher.status == "active",

                TeacherSubject.institution_id ==
                exam.institution_id,

                TeacherSubject.program_id ==
                exam.program_id,

                TeacherSubject.status == "active",

                TeacherSubject.subject_id.isnot(None)
            )
        )

        # ----------------------------------------------------
        # BRANCH SECURITY
        # ----------------------------------------------------

        if exam.branch_id:

            teacher_query = (
                teacher_query
                .filter(
                    Teacher.branch_id ==
                    exam.branch_id,

                    db.or_(
                        TeacherSubject.branch_id ==
                        exam.branch_id,

                        TeacherSubject.branch_id.is_(None)
                    )
                )
            )

        teacher_rows = (
            teacher_query
            .order_by(
                Teacher.full_name.asc()
            )
            .all()
        )

        # ====================================================
        # GROUP TEACHERS BY SUBJECT
        # ====================================================

        teachers_by_subject = {}

        for assignment, teacher in teacher_rows:

            subject_id = int(
                assignment.subject_id
            )

            teachers_by_subject.setdefault(
                subject_id,
                []
            ).append(
                teacher
            )

        # ====================================================
        # DETERMINE SUBJECTS THAT CAN BE SUBMITTED
        #
        # IMPORTANT:
        #
        # NO TEACHER = SKIP
        #
        # ONE TEACHER = SUBMIT
        #
        # MULTIPLE TEACHERS = SKIP
        #
        # WE NEVER GUESS BETWEEN MULTIPLE TEACHERS.
        # ====================================================

        selected_teacher_by_subject = {}

        missing_teacher_subjects = []

        multiple_teacher_subjects = []

        assigned_subjects = []

        for subject in subjects:

            subject_id = int(
                subject.id
            )

            assigned_teachers = (
                teachers_by_subject.get(
                    subject_id,
                    []
                )
            )

            # ------------------------------------------------
            # NO TEACHER
            # ------------------------------------------------

            if not assigned_teachers:

                missing_teacher_subjects.append(
                    subject.name
                )

                continue

            # ------------------------------------------------
            # MULTIPLE TEACHERS
            # ------------------------------------------------

            if len(assigned_teachers) > 1:

                multiple_teacher_subjects.append(
                    subject.name
                )

                continue

            # ------------------------------------------------
            # EXACTLY ONE ASSIGNED TEACHER
            # ------------------------------------------------

            teacher = assigned_teachers[0]

            selected_teacher_by_subject[
                subject_id
            ] = teacher

            assigned_subjects.append(
                subject
            )

        # ====================================================
        # IF NOTHING HAS A TEACHER
        # ====================================================

        if not assigned_subjects:

            if missing_teacher_subjects:

                names = ", ".join(
                    missing_teacher_subjects
                )

                flash(
                    f"No teacher is assigned to these subjects: {names}. "
                    f"No exam subjects were created. "
                    f"Assign teachers first.",
                    "danger"
                )

            elif multiple_teacher_subjects:

                names = ", ".join(
                    multiple_teacher_subjects
                )

                flash(
                    f"These subjects have multiple active teacher assignments: {names}. "
                    f"No exam subjects were created because a teacher cannot be selected automatically.",
                    "warning"
                )

            return redirect(
                url_for(
                    "main.bulk_add_exam_subjects",
                    exam_id=exam.id
                )
            )

        # ====================================================
        # BUILD BULK RECORDS
        #
        # ONLY SUBJECTS WITH ASSIGNED TEACHERS
        #
        # SUBJECT × CLASS
        #
        # SECTION = NULL
        # ====================================================

        new_exam_subjects = []

        request_combinations = set()

        display_order = (
            db.session.query(
                db.func.max(
                    ExamSubject.display_order
                )
            )
            .filter(
                ExamSubject.exam_id == exam.id
            )
            .scalar()
            or 0
        )

        skipped_existing = []

        skipped_no_teacher = []

        skipped_multiple_teachers = []

        for class_item in classes:

            for subject in assigned_subjects:

                subject_id = int(
                    subject.id
                )

                combination = (
                    subject_id,
                    int(class_item.id),
                    None
                )

                # --------------------------------------------
                # EXISTING
                # --------------------------------------------

                if combination in existing_combinations:

                    skipped_existing.append(
                        f"{subject.name} - {class_item.name}"
                    )

                    continue

                # --------------------------------------------
                # DUPLICATE REQUEST
                # --------------------------------------------

                if combination in request_combinations:
                    continue

                request_combinations.add(
                    combination
                )

                # --------------------------------------------
                # TEACHER
                # --------------------------------------------

                teacher = (
                    selected_teacher_by_subject.get(
                        subject_id
                    )
                )

                if not teacher:

                    skipped_no_teacher.append(
                        subject.name
                    )

                    continue

                # --------------------------------------------
                # DISPLAY ORDER
                # --------------------------------------------

                display_order += 1

                # --------------------------------------------
                # CREATE
                # --------------------------------------------

                exam_subject = ExamSubject(
                    exam_id=exam.id,

                    subject_id=subject.id,

                    class_id=class_item.id,

                    # ----------------------------------------
                    # SECTION OPTIONAL
                    # ----------------------------------------
                    # NULL = ALL SECTIONS OF THIS CLASS
                    # ----------------------------------------

                    section_id=None,

                    teacher_id=teacher.id,

                    max_marks=max_marks,

                    pass_marks=pass_marks,

                    weight=weight,

                    display_order=display_order,

                    status=status
                )

                new_exam_subjects.append(
                    exam_subject
                )

        # ====================================================
        # NOTHING NEW
        # ====================================================

        if not new_exam_subjects:

            if skipped_existing:

                flash(
                    "All assigned subject/class combinations already exist for this exam.",
                    "warning"
                )

            else:

                flash(
                    "No new exam subjects were prepared.",
                    "warning"
                )

            # ------------------------------------------------
            # SHOW MISSING TEACHERS IF ANY
            # ------------------------------------------------

            if missing_teacher_subjects:

                names = ", ".join(
                    missing_teacher_subjects
                )

                flash(
                    f"Skipped subjects without teachers: {names}.",
                    "warning"
                )

            # ------------------------------------------------
            # SHOW MULTIPLE TEACHERS IF ANY
            # ------------------------------------------------

            if multiple_teacher_subjects:

                names = ", ".join(
                    multiple_teacher_subjects
                )

                flash(
                    f"Skipped subjects with multiple teachers: {names}.",
                    "warning"
                )

            return redirect(
                url_for(
                    "main.all_exam_subjects",
                    exam_id=exam.id
                )
            )

        # ====================================================
        # SAVE
        # ====================================================

        try:

            db.session.add_all(
                new_exam_subjects
            )

            db.session.commit()

        except Exception as exc:

            db.session.rollback()

            current_app.logger.exception(
                "Bulk exam subject creation failed: %s",
                exc
            )

            flash(
                "An error occurred while creating the exam subjects. "
                "No changes were saved.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.bulk_add_exam_subjects",
                    exam_id=exam.id
                )
            )

        # ====================================================
        # SUCCESS MESSAGE
        # ====================================================

        success_message = (
            f"{len(new_exam_subjects)} exam subject(s) "
            f"were created successfully for "
            f"{len(classes)} class(es) and "
            f"{len(assigned_subjects)} assigned subject(s)."
        )

        if skipped_existing:

            success_message += (
                f" {len(skipped_existing)} existing "
                f"combination(s) were skipped."
            )

        flash(
            success_message,
            "success"
        )

        # ====================================================
        # WARNING: SUBJECTS WITHOUT TEACHER
        # ====================================================

        if missing_teacher_subjects:

            names = ", ".join(
                missing_teacher_subjects
            )

            flash(
                f"Skipped subjects without assigned teachers: {names}.",
                "warning"
            )

        # ====================================================
        # WARNING: MULTIPLE TEACHERS
        # ====================================================

        if multiple_teacher_subjects:

            names = ", ".join(
                multiple_teacher_subjects
            )

            flash(
                f"Skipped subjects with multiple active teachers: {names}. "
                f"Assign one active teacher before adding them.",
                "warning"
            )

        # ====================================================
        # REDIRECT
        # ====================================================

        return redirect(
            url_for(
                "main.all_exam_subjects",
                exam_id=exam.id
            )
        )

    # ========================================================
    # GET
    # ========================================================

    selected_exam_id = request.args.get(
        "exam_id",
        type=int
    )

    # ========================================================
    # OPTIONAL GET DATA
    #
    # This allows the template to show which subjects have
    # teachers assigned and which subjects do not.
    # ========================================================

    selected_exam = None
    subjects = []
    classes = []
    teachers_by_subject = {}
    assigned_subject_ids = set()
    missing_teacher_subject_ids = set()

    if selected_exam_id:

        # ----------------------------------------------------
        # SECURITY
        # ----------------------------------------------------

        selected_exam_query = (
            Exam.query
            .filter(
                Exam.id == selected_exam_id
            )
        )

        if current_role == "school_admin":

            selected_exam_query = (
                selected_exam_query
                .filter(
                    Exam.institution_id ==
                    institution_id
                )
            )

        elif current_role == "branch_admin":

            selected_exam_query = (
                selected_exam_query
                .filter(
                    Exam.institution_id ==
                    institution_id,

                    Exam.branch_id ==
                    branch_id
                )
            )

        selected_exam = (
            selected_exam_query
            .first()
        )

        if selected_exam and selected_exam.program_id:

            # =================================================
            # GET SUBJECTS
            # =================================================

            subjects_query = (
                Subject.query
                .filter(
                    Subject.program_id ==
                    selected_exam.program_id,

                    Subject.institution_id ==
                    selected_exam.institution_id,

                    Subject.status == "active"
                )
            )

            if selected_exam.branch_id:

                subjects_query = (
                    subjects_query
                    .filter(
                        db.or_(
                            Subject.branch_id ==
                            selected_exam.branch_id,

                            Subject.branch_id.is_(None)
                        )
                    )
                )

            subjects = (
                subjects_query
                .order_by(
                    Subject.name.asc()
                )
                .all()
            )

            # =================================================
            # GET CLASSES
            # =================================================

            classes_query = (
                Class.query
                .filter(
                    Class.program_id ==
                    selected_exam.program_id,

                    Class.institution_id ==
                    selected_exam.institution_id
                )
            )

            if selected_exam.branch_id:

                classes_query = (
                    classes_query
                    .filter(
                        Class.branch_id ==
                        selected_exam.branch_id
                    )
                )

            if selected_exam.academic_year_id:

                classes_query = (
                    classes_query
                    .filter(
                        Class.academic_year_id ==
                        selected_exam.academic_year_id
                    )
                )

            classes = (
                classes_query
                .order_by(
                    Class.name.asc()
                )
                .all()
            )

            # =================================================
            # TEACHER ASSIGNMENTS
            # =================================================

            teacher_query = (
                db.session.query(
                    TeacherSubject,
                    Teacher
                )
                .join(
                    Teacher,
                    Teacher.id ==
                    TeacherSubject.teacher_id
                )
                .filter(
                    Teacher.institution_id ==
                    selected_exam.institution_id,

                    Teacher.is_active.is_(True),

                    Teacher.status == "active",

                    TeacherSubject.institution_id ==
                    selected_exam.institution_id,

                    TeacherSubject.program_id ==
                    selected_exam.program_id,

                    TeacherSubject.status == "active",

                    TeacherSubject.subject_id.isnot(None)
                )
            )

            if selected_exam.branch_id:

                teacher_query = (
                    teacher_query
                    .filter(
                        Teacher.branch_id ==
                        selected_exam.branch_id,

                        db.or_(
                            TeacherSubject.branch_id ==
                            selected_exam.branch_id,

                            TeacherSubject.branch_id.is_(None)
                        )
                    )
                )

            teacher_rows = (
                teacher_query
                .order_by(
                    Teacher.full_name.asc()
                )
                .all()
            )

            # =================================================
            # GROUP BY SUBJECT
            # =================================================

            for assignment, teacher in teacher_rows:

                subject_id = int(
                    assignment.subject_id
                )

                teachers_by_subject.setdefault(
                    subject_id,
                    []
                ).append(
                    teacher
                )

            # =================================================
            # ASSIGNMENT STATUS
            # =================================================

            for subject in subjects:

                assigned = (
                    teachers_by_subject.get(
                        int(subject.id),
                        []
                    )
                )

                if assigned:
                    assigned_subject_ids.add(
                        int(subject.id)
                    )
                else:
                    missing_teacher_subject_ids.add(
                        int(subject.id)
                    )

    # ========================================================
    # GET RENDER
    # ========================================================

    return render_template(
        "backend/pages/exam_subjects/bulk_add_exam_subjects.html",

        exams=exams,

        selected_exam_id=selected_exam_id,

        selected_exam=selected_exam,

        subjects=subjects,

        classes=classes,

        teachers_by_subject=teachers_by_subject,

        assigned_subject_ids=assigned_subject_ids,

        missing_teacher_subject_ids=missing_teacher_subject_ids,

        user=current_user
    )



# ============================================================
# VIEW SINGLE EXAM SUBJECT
# ============================================================

@bp.route(
    "/exam-subjects/<int:exam_subject_id>",
    methods=["GET"]
)
@login_required
def view_exam_subject(exam_subject_id):

    # ========================================================
    # SECURITY
    # ========================================================

    if not _exam_subject_can_view():
        abort(403)

    # ========================================================
    # QUERY
    # ========================================================

    query = (
        ExamSubject.query
        .join(
            Exam,
            Exam.id == ExamSubject.exam_id
        )
        .filter(
            ExamSubject.id == exam_subject_id
        )
    )

    # ========================================================
    # SCOPE
    # ========================================================

    role = getattr(
        current_user,
        "role",
        None
    )

    if role == "school_admin":

        institution_id = getattr(
            current_user,
            "institution_id",
            None
        )

        query = query.filter(
            Exam.institution_id == institution_id
        )

    elif role == "branch_admin":

        institution_id = getattr(
            current_user,
            "institution_id",
            None
        )

        branch_id = getattr(
            current_user,
            "branch_id",
            None
        )

        query = query.filter(
            Exam.institution_id == institution_id,
            Exam.branch_id == branch_id
        )

    elif role == "teacher":

        # Teacher can see only subjects assigned to them.
        teacher_id = getattr(
            current_user,
            "teacher_id",
            None
        )

        if teacher_id:

            query = query.filter(
                ExamSubject.teacher_id == teacher_id
            )

        else:

            query = query.filter(False)

    exam_subject = query.first()

    if not exam_subject:
        abort(404)

    # ========================================================
    # RENDER
    # ========================================================

    return render_template(
        "backend/pages/exam_subjects/view_exam_subject.html",
        exam_subject=exam_subject,
    )


# ============================================================
# ALL EXAM SUBJECTS
# ============================================================

@bp.route(
    "/exam-subjects",
    methods=["GET"]
)
@login_required
def all_exam_subjects():

    # ========================================================
    # SECURITY
    # ========================================================

    if not _exam_subject_can_view():
        abort(403)

    # ========================================================
    # CURRENT ROLE
    # ========================================================

    role = getattr(
        current_user,
        "role",
        None
    )

    # ========================================================
    # FILTERS
    # ========================================================

    search = (
        request.args.get(
            "search",
            ""
        )
        .strip()
    )

    status = (
        request.args.get(
            "status",
            ""
        )
        .strip()
        .lower()
    )

    exam_id = request.args.get(
        "exam_id",
        type=int
    )

    subject_id = request.args.get(
        "subject_id",
        type=int
    )

    class_id = request.args.get(
        "class_id",
        type=int
    )

    section_id = request.args.get(
        "section_id",
        type=int
    )

    teacher_id = request.args.get(
        "teacher_id",
        type=int
    )

    # ========================================================
    # PAGINATION
    # ========================================================

    page = request.args.get(
        "page",
        1,
        type=int
    )

    per_page = request.args.get(
        "per_page",
        25,
        type=int
    )

    allowed_per_page = {
        10,
        25,
        50,
        100,
    }

    if per_page not in allowed_per_page:
        per_page = 25

    # ========================================================
    # BASE QUERY
    # ========================================================

    query = (
        ExamSubject.query
        .join(
            Exam,
            Exam.id == ExamSubject.exam_id
        )
        .join(
            Subject,
            Subject.id == ExamSubject.subject_id
        )
    )

    # ========================================================
    # ROLE SCOPE
    # ========================================================

    if role == "superadmin":

        # Superadmin can see everything.
        pass

    elif role == "school_admin":

        institution_id = getattr(
            current_user,
            "institution_id",
            None
        )

        if not institution_id:

            query = query.filter(False)

        else:

            query = query.filter(
                Exam.institution_id == institution_id
            )

    elif role == "branch_admin":

        institution_id = getattr(
            current_user,
            "institution_id",
            None
        )

        branch_id = getattr(
            current_user,
            "branch_id",
            None
        )

        if not institution_id or not branch_id:

            query = query.filter(False)

        else:

            query = query.filter(
                Exam.institution_id == institution_id,
                Exam.branch_id == branch_id
            )

    elif role == "teacher":

        current_teacher_id = getattr(
            current_user,
            "teacher_id",
            None
        )

        if not current_teacher_id:

            query = query.filter(False)

        else:

            query = query.filter(
                ExamSubject.teacher_id ==
                current_teacher_id
            )

    else:

        query = query.filter(False)

    # ========================================================
    # SEARCH
    # ========================================================

    if search:

        search_term = f"%{search}%"

        query = query.filter(
            db.or_(
                Exam.name.ilike(search_term),
                Exam.code.ilike(search_term),
                Subject.name.ilike(search_term),
                Subject.code.ilike(search_term),
            )
        )

    # ========================================================
    # STATUS
    # ========================================================

    if status:

        query = query.filter(
            ExamSubject.status == status
        )

    # ========================================================
    # EXAM
    # ========================================================

    if exam_id:

        query = query.filter(
            ExamSubject.exam_id == exam_id
        )

    # ========================================================
    # SUBJECT
    # ========================================================

    if subject_id:

        query = query.filter(
            ExamSubject.subject_id == subject_id
        )

    # ========================================================
    # CLASS
    # ========================================================

    if class_id:

        query = query.filter(
            ExamSubject.class_id == class_id
        )

    # ========================================================
    # SECTION
    # ========================================================

    if section_id:

        query = query.filter(
            ExamSubject.section_id == section_id
        )

    # ========================================================
    # TEACHER
    # ========================================================

    if teacher_id:

        query = query.filter(
            ExamSubject.teacher_id == teacher_id
        )

    # ========================================================
    # ORDER
    # ========================================================

    query = query.order_by(
        ExamSubject.display_order.asc(),
        ExamSubject.id.desc()
    )

    # ========================================================
    # PAGINATION
    # ========================================================

    pagination = query.paginate(
        page=page,
        per_page=per_page,
        error_out=False
    )

    # ========================================================
    # FILTER DATA
    # ========================================================

    # --------------------------------------------------------
    # EXAMS
    # --------------------------------------------------------

    exams_query = Exam.query

    if role == "school_admin":

        institution_id = getattr(
            current_user,
            "institution_id",
            None
        )

        exams_query = exams_query.filter(
            Exam.institution_id == institution_id
        )

    elif role == "branch_admin":

        institution_id = getattr(
            current_user,
            "institution_id",
            None
        )

        branch_id = getattr(
            current_user,
            "branch_id",
            None
        )

        exams_query = exams_query.filter(
            Exam.institution_id == institution_id,
            Exam.branch_id == branch_id
        )

    elif role == "teacher":

        current_teacher_id = getattr(
            current_user,
            "teacher_id",
            None
        )

        if current_teacher_id:

            exams_query = (
                exams_query
                .join(
                    ExamSubject,
                    ExamSubject.exam_id == Exam.id
                )
                .filter(
                    ExamSubject.teacher_id ==
                    current_teacher_id
                )
                .distinct()
            )

        else:

            exams_query = exams_query.filter(False)

    elif role not in {
        "superadmin",
        "school_admin",
        "branch_admin",
        "teacher",
    }:

        exams_query = exams_query.filter(False)

    exams = (
        exams_query
        .order_by(
            Exam.name.asc()
        )
        .all()
    )

    # --------------------------------------------------------
    # SUBJECTS
    # --------------------------------------------------------

    subjects_query = Subject.query

    if role == "teacher":

        current_teacher_id = getattr(
            current_user,
            "teacher_id",
            None
        )

        if current_teacher_id:

            subjects_query = (
                subjects_query
                .join(
                    ExamSubject,
                    ExamSubject.subject_id == Subject.id
                )
                .filter(
                    ExamSubject.teacher_id ==
                    current_teacher_id
                )
                .distinct()
            )

        else:

            subjects_query = subjects_query.filter(False)

    elif role not in {
        "superadmin",
        "school_admin",
        "branch_admin",
    }:

        subjects_query = subjects_query.filter(False)

    subjects = (
        subjects_query
        .order_by(
            Subject.name.asc()
        )
        .all()
    )

    # --------------------------------------------------------
    # CLASSES
    # --------------------------------------------------------

    classes_query = Class.query

    if role == "teacher":

        current_teacher_id = getattr(
            current_user,
            "teacher_id",
            None
        )

        if current_teacher_id:

            classes_query = (
                classes_query
                .join(
                    ExamSubject,
                    ExamSubject.class_id == Class.id
                )
                .filter(
                    ExamSubject.teacher_id ==
                    current_teacher_id
                )
                .distinct()
            )

        else:

            classes_query = classes_query.filter(False)

    elif role not in {
        "superadmin",
        "school_admin",
        "branch_admin",
    }:

        classes_query = classes_query.filter(False)

    classes = (
        classes_query
        .order_by(
            Class.name.asc()
        )
        .all()
    )

    # --------------------------------------------------------
    # SECTIONS
    # --------------------------------------------------------

    sections_query = Section.query

    if role == "teacher":

        current_teacher_id = getattr(
            current_user,
            "teacher_id",
            None
        )

        if current_teacher_id:

            sections_query = (
                sections_query
                .join(
                    ExamSubject,
                    ExamSubject.section_id == Section.id
                )
                .filter(
                    ExamSubject.teacher_id ==
                    current_teacher_id
                )
                .distinct()
            )

        else:

            sections_query = sections_query.filter(False)

    elif role not in {
        "superadmin",
        "school_admin",
        "branch_admin",
    }:

        sections_query = sections_query.filter(False)

    sections = (
        sections_query
        .order_by(
            Section.name.asc()
        )
        .all()
    )

    # --------------------------------------------------------
    # TEACHERS
    # --------------------------------------------------------

    teachers_query = Teacher.query

    if role == "teacher":

        current_teacher_id = getattr(
            current_user,
            "teacher_id",
            None
        )

        if current_teacher_id:

            teachers_query = teachers_query.filter(
                Teacher.id == current_teacher_id
            )

        else:

            teachers_query = teachers_query.filter(False)

    elif role not in {
        "superadmin",
        "school_admin",
        "branch_admin",
    }:

        teachers_query = teachers_query.filter(False)

    teachers = (
        teachers_query
        .order_by(
            Teacher.full_name.asc()
            if hasattr(Teacher, "full_name")
            else Teacher.id.asc()
        )
        .all()
    )

    # ========================================================
    # STATISTICS
    # ========================================================

    # --------------------------------------------------------
    # Statistics query
    #
    # IMPORTANT:
    # We use the same ROLE SCOPE but do NOT use the
    # user's current filters.
    # --------------------------------------------------------

    stats_query = (
        ExamSubject.query
        .join(
            Exam,
            Exam.id == ExamSubject.exam_id
        )
    )

    # ========================================================
    # STATISTICS ROLE SCOPE
    # ========================================================

    if role == "superadmin":

        pass

    elif role == "school_admin":

        institution_id = getattr(
            current_user,
            "institution_id",
            None
        )

        if not institution_id:

            stats_query = stats_query.filter(False)

        else:

            stats_query = stats_query.filter(
                Exam.institution_id == institution_id
            )

    elif role == "branch_admin":

        institution_id = getattr(
            current_user,
            "institution_id",
            None
        )

        branch_id = getattr(
            current_user,
            "branch_id",
            None
        )

        if not institution_id or not branch_id:

            stats_query = stats_query.filter(False)

        else:

            stats_query = stats_query.filter(
                Exam.institution_id == institution_id,
                Exam.branch_id == branch_id
            )

    elif role == "teacher":

        current_teacher_id = getattr(
            current_user,
            "teacher_id",
            None
        )

        if not current_teacher_id:

            stats_query = stats_query.filter(False)

        else:

            stats_query = stats_query.filter(
                ExamSubject.teacher_id ==
                current_teacher_id
            )

    else:

        stats_query = stats_query.filter(False)

    # ========================================================
    # TOTAL
    # ========================================================

    total_exam_subjects = (
        stats_query
        .with_entities(
            db.func.count(
                ExamSubject.id
            )
        )
        .scalar()
        or 0
    )

    # ========================================================
    # ACTIVE
    # ========================================================

    active_exam_subjects = (
        stats_query
        .filter(
            ExamSubject.status == "active"
        )
        .with_entities(
            db.func.count(
                ExamSubject.id
            )
        )
        .scalar()
        or 0
    )

    # ========================================================
    # INACTIVE
    # ========================================================

    inactive_exam_subjects = (
        stats_query
        .filter(
            ExamSubject.status == "inactive"
        )
        .with_entities(
            db.func.count(
                ExamSubject.id
            )
        )
        .scalar()
        or 0
    )

    # ========================================================
    # TEACHER ASSIGNED
    # ========================================================

    exam_subjects_with_teacher = (
        stats_query
        .filter(
            ExamSubject.teacher_id.isnot(None)
        )
        .with_entities(
            db.func.count(
                ExamSubject.id
            )
        )
        .scalar()
        or 0
    )

    # ========================================================
    # TEACHER NOT ASSIGNED
    # ========================================================

    exam_subjects_without_teacher = (
        stats_query
        .filter(
            ExamSubject.teacher_id.is_(None)
        )
        .with_entities(
            db.func.count(
                ExamSubject.id
            )
        )
        .scalar()
        or 0
    )

    # ========================================================
    # CLASS ASSIGNED
    # ========================================================

    exam_subjects_with_class = (
        stats_query
        .filter(
            ExamSubject.class_id.isnot(None)
        )
        .with_entities(
            db.func.count(
                ExamSubject.id
            )
        )
        .scalar()
        or 0
    )

    # ========================================================
    # RENDER
    # ========================================================

    return render_template(

        "backend/pages/exam_subjects/all_exam_subjects.html",

        # ----------------------------------------------------
        # MAIN DATA
        # ----------------------------------------------------

        exam_subjects=pagination.items,

        pagination=pagination,

        # ----------------------------------------------------
        # FILTER DATA
        # ----------------------------------------------------

        exams=exams,

        subjects=subjects,

        classes=classes,

        sections=sections,

        teachers=teachers,

        # ----------------------------------------------------
        # FILTER VALUES
        # ----------------------------------------------------

        search=search,

        status=status,

        selected_exam_id=exam_id,

        selected_subject_id=subject_id,

        selected_class_id=class_id,

        selected_section_id=section_id,

        selected_teacher_id=teacher_id,

        selected_status=status,

        per_page=per_page,

        # ----------------------------------------------------
        # STATISTICS
        # ----------------------------------------------------

        total_exam_subjects=total_exam_subjects,

        active_exam_subjects=active_exam_subjects,

        inactive_exam_subjects=inactive_exam_subjects,

        exam_subjects_with_teacher=
            exam_subjects_with_teacher,

        exam_subjects_without_teacher=
            exam_subjects_without_teacher,

        exam_subjects_with_class=
            exam_subjects_with_class,

        # ----------------------------------------------------
        # CURRENT USER
        # ----------------------------------------------------

        user=current_user
    )


# ============================================================
# EDIT EXAM SUBJECT
# ============================================================

@bp.route(
    "/exam-subjects/<int:exam_subject_id>/edit",
    methods=["GET", "POST"]
)
@login_required
def edit_exam_subject(exam_subject_id):

    # ========================================================
    # ROLE SECURITY
    # ========================================================

    allowed_roles = {
        "superadmin",
        "school_admin",
        "branch_admin",
    }

    current_role = getattr(
        current_user,
        "role",
        None
    )

    if current_role not in allowed_roles:
        abort(403)

    # ========================================================
    # CURRENT USER SCOPE
    # ========================================================

    institution_id = getattr(
        current_user,
        "institution_id",
        None
    )

    branch_id = getattr(
        current_user,
        "branch_id",
        None
    )

    # ========================================================
    # LOAD EXAM SUBJECT
    # ========================================================

    exam_subject_query = (
        ExamSubject.query
        .join(
            Exam,
            Exam.id == ExamSubject.exam_id
        )
        .filter(
            ExamSubject.id == exam_subject_id
        )
    )

    # ========================================================
    # INSTITUTION / BRANCH SECURITY
    # ========================================================

    if current_role == "school_admin":

        if not institution_id:
            abort(403)

        exam_subject_query = (
            exam_subject_query
            .filter(
                Exam.institution_id == institution_id
            )
        )

    elif current_role == "branch_admin":

        if not institution_id or not branch_id:
            abort(403)

        exam_subject_query = (
            exam_subject_query
            .filter(
                Exam.institution_id == institution_id,
                Exam.branch_id == branch_id
            )
        )

    # ========================================================
    # GET EXAM SUBJECT
    # ========================================================

    exam_subject = (
        exam_subject_query
        .first()
    )

    if not exam_subject:
        abort(404)

    # ========================================================
    # EXAM
    # ========================================================

    exam = exam_subject.exam

    if not exam:
        abort(404)

    # ========================================================
    # PROGRAM
    # ========================================================

    if not exam.program_id:
        flash(
            "The exam has no program assigned.",
            "danger"
        )

        return redirect(
            url_for(
                "main.all_exam_subjects"
            )
        )

    program = (
        Program.query
        .filter(
            Program.id == exam.program_id
        )
        .first()
    )

    if not program:
        flash(
            "The program assigned to this exam was not found.",
            "danger"
        )

        return redirect(
            url_for(
                "main.all_exam_subjects"
            )
        )

    # ========================================================
    # POST
    # ========================================================

    if request.method == "POST":

        # ====================================================
        # SUBJECT
        # ====================================================

        raw_subject_id = request.form.get(
            "subject_id"
        )

        raw_subject_id = (
            str(raw_subject_id).strip()
            if raw_subject_id
            else ""
        )

        if not raw_subject_id:

            flash(
                "Please select a subject.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.edit_exam_subject",
                    exam_subject_id=exam_subject.id
                )
            )

        try:

            subject_id = int(
                raw_subject_id
            )

        except (
            TypeError,
            ValueError
        ):

            flash(
                "Invalid subject.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.edit_exam_subject",
                    exam_subject_id=exam_subject.id
                )
            )

        # ====================================================
        # VALID SUBJECT
        #
        # Subject must belong to:
        #
        # Exam.program_id
        # Exam.institution_id
        #
        # Branch can be:
        #
        #   exam.branch_id
        #   NULL/shared
        # ====================================================

        subject_query = (
            Subject.query
            .filter(
                Subject.id == subject_id,
                Subject.program_id == exam.program_id,
                Subject.institution_id == exam.institution_id,
                Subject.status == "active"
            )
        )

        if exam.branch_id:

            subject_query = (
                subject_query
                .filter(
                    db.or_(
                        Subject.branch_id == exam.branch_id,
                        Subject.branch_id.is_(None)
                    )
                )
            )

        subject = (
            subject_query
            .first()
        )

        if not subject:

            flash(
                "The selected subject does not belong to the selected exam program.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.edit_exam_subject",
                    exam_subject_id=exam_subject.id
                )
            )

        # ====================================================
        # CLASS
        # ====================================================

        raw_class_id = request.form.get(
            "class_id"
        )

        raw_class_id = (
            str(raw_class_id).strip()
            if raw_class_id
            else ""
        )

        class_id = None
        selected_class = None

        if raw_class_id:

            try:

                class_id = int(
                    raw_class_id
                )

            except (
                TypeError,
                ValueError
            ):

                flash(
                    "Invalid class.",
                    "danger"
                )

                return redirect(
                    url_for(
                        "main.edit_exam_subject",
                        exam_subject_id=exam_subject.id
                    )
                )

            class_query = (
                Class.query
                .filter(
                    Class.id == class_id,
                    Class.program_id == exam.program_id,
                    Class.institution_id == exam.institution_id
                )
            )

            # ------------------------------------------------
            # Branch
            # ------------------------------------------------

            if exam.branch_id:

                class_query = (
                    class_query
                    .filter(
                        Class.branch_id == exam.branch_id
                    )
                )

            # ------------------------------------------------
            # Academic Year
            # ------------------------------------------------

            if exam.academic_year_id:

                class_query = (
                    class_query
                    .filter(
                        Class.academic_year_id ==
                        exam.academic_year_id
                    )
                )

            selected_class = (
                class_query
                .first()
            )

            if not selected_class:

                flash(
                    "The selected class does not belong to the exam program.",
                    "danger"
                )

                return redirect(
                    url_for(
                        "main.edit_exam_subject",
                        exam_subject_id=exam_subject.id
                    )
                )

        # ====================================================
        # SECTION
        # ====================================================

        raw_section_id = request.form.get(
            "section_id"
        )

        raw_section_id = (
            str(raw_section_id).strip()
            if raw_section_id
            else ""
        )

        section_id = None
        selected_section = None

        if raw_section_id:

            # ------------------------------------------------
            # Section requires class
            # ------------------------------------------------

            if not class_id:

                flash(
                    "Please select a class before selecting a section.",
                    "danger"
                )

                return redirect(
                    url_for(
                        "main.edit_exam_subject",
                        exam_subject_id=exam_subject.id
                    )
                )

            try:

                section_id = int(
                    raw_section_id
                )

            except (
                TypeError,
                ValueError
            ):

                flash(
                    "Invalid section.",
                    "danger"
                )

                return redirect(
                    url_for(
                        "main.edit_exam_subject",
                        exam_subject_id=exam_subject.id
                    )
                )

            selected_section = (
                Section.query
                .filter(
                    Section.id == section_id,
                    Section.class_id == class_id
                )
                .first()
            )

            if not selected_section:

                flash(
                    "The selected section does not belong to the selected class.",
                    "danger"
                )

                return redirect(
                    url_for(
                        "main.edit_exam_subject",
                        exam_subject_id=exam_subject.id
                    )
                )

        # ====================================================
        # TEACHER
        # ====================================================

        raw_teacher_id = request.form.get(
            "teacher_id"
        )

        raw_teacher_id = (
            str(raw_teacher_id).strip()
            if raw_teacher_id
            else ""
        )

        teacher_id = None
        teacher = None

        if raw_teacher_id:

            try:

                teacher_id = int(
                    raw_teacher_id
                )

            except (
                TypeError,
                ValueError
            ):

                flash(
                    "Invalid teacher.",
                    "danger"
                )

                return redirect(
                    url_for(
                        "main.edit_exam_subject",
                        exam_subject_id=exam_subject.id
                    )
                )

            # ------------------------------------------------
            # Teacher base validation
            # ------------------------------------------------

            teacher_query = (
                Teacher.query
                .filter(
                    Teacher.id == teacher_id,
                    Teacher.institution_id ==
                    exam.institution_id,
                    Teacher.is_active.is_(True),
                    Teacher.status == "active"
                )
            )

            if exam.branch_id:

                teacher_query = (
                    teacher_query
                    .filter(
                        Teacher.branch_id ==
                        exam.branch_id
                    )
                )

            teacher = (
                teacher_query
                .first()
            )

            if not teacher:

                flash(
                    "The selected teacher is not available for this exam.",
                    "danger"
                )

                return redirect(
                    url_for(
                        "main.edit_exam_subject",
                        exam_subject_id=exam_subject.id
                    )
                )

            # ------------------------------------------------
            # TeacherSubject
            #
            # Program + Subject
            # ------------------------------------------------

            teacher_assignment_query = (
                TeacherSubject.query
                .filter(
                    TeacherSubject.teacher_id ==
                    teacher_id,

                    TeacherSubject.program_id ==
                    exam.program_id,

                    TeacherSubject.institution_id ==
                    exam.institution_id,

                    TeacherSubject.status ==
                    "active",

                    db.or_(
                        TeacherSubject.subject_id.is_(None),
                        TeacherSubject.subject_id ==
                        subject_id
                    )
                )
            )

            # ------------------------------------------------
            # Branch
            # ------------------------------------------------

            if exam.branch_id:

                teacher_assignment_query = (
                    teacher_assignment_query
                    .filter(
                        db.or_(
                            TeacherSubject.branch_id ==
                            exam.branch_id,

                            TeacherSubject.branch_id.is_(None)
                        )
                    )
                )

            # ------------------------------------------------
            # Academic Year
            # ------------------------------------------------

            if exam.academic_year_id:

                teacher_assignment_query = (
                    teacher_assignment_query
                    .filter(
                        db.or_(
                            TeacherSubject.academic_year_id ==
                            exam.academic_year_id,

                            TeacherSubject.academic_year_id.is_(None)
                        )
                    )
                )

            teacher_assignment = (
                teacher_assignment_query
                .first()
            )

            if not teacher_assignment:

                flash(
                    f"{teacher.full_name} is not assigned to {subject.name}.",
                    "danger"
                )

                return redirect(
                    url_for(
                        "main.edit_exam_subject",
                        exam_subject_id=exam_subject.id
                    )
                )

            # ------------------------------------------------
            # Class / Section compatibility
            #
            # TeacherSubject class_id NULL
            # = program-wide assignment
            #
            # TeacherSubject section_id NULL
            # = all sections
            # ------------------------------------------------

            compatible_assignment_query = (
                TeacherSubject.query
                .filter(
                    TeacherSubject.teacher_id ==
                    teacher_id,

                    TeacherSubject.program_id ==
                    exam.program_id,

                    TeacherSubject.institution_id ==
                    exam.institution_id,

                    TeacherSubject.status ==
                    "active",

                    db.or_(
                        TeacherSubject.subject_id.is_(None),
                        TeacherSubject.subject_id ==
                        subject_id
                    )
                )
            )

            if exam.branch_id:

                compatible_assignment_query = (
                    compatible_assignment_query
                    .filter(
                        db.or_(
                            TeacherSubject.branch_id ==
                            exam.branch_id,

                            TeacherSubject.branch_id.is_(None)
                        )
                    )
                )

            if exam.academic_year_id:

                compatible_assignment_query = (
                    compatible_assignment_query
                    .filter(
                        db.or_(
                            TeacherSubject.academic_year_id ==
                            exam.academic_year_id,

                            TeacherSubject.academic_year_id.is_(None)
                        )
                    )
                )

            # ------------------------------------------------
            # Class compatibility
            # ------------------------------------------------

            if class_id:

                compatible_assignment_query = (
                    compatible_assignment_query
                    .filter(
                        db.or_(
                            TeacherSubject.class_id.is_(None),
                            TeacherSubject.class_id ==
                            class_id
                        )
                    )
                )

            else:

                compatible_assignment_query = (
                    compatible_assignment_query
                    .filter(
                        TeacherSubject.class_id.is_(None)
                    )
                )

            # ------------------------------------------------
            # Section compatibility
            # ------------------------------------------------

            if section_id:

                compatible_assignment_query = (
                    compatible_assignment_query
                    .filter(
                        db.or_(
                            TeacherSubject.section_id.is_(None),
                            TeacherSubject.section_id ==
                            section_id
                        )
                    )
                )

            else:

                compatible_assignment_query = (
                    compatible_assignment_query
                    .filter(
                        TeacherSubject.section_id.is_(None)
                    )
                )

            compatible_assignment = (
                compatible_assignment_query
                .first()
            )

            if not compatible_assignment:

                flash(
                    f"{teacher.full_name} is not assigned to the selected class/section for {subject.name}.",
                    "danger"
                )

                return redirect(
                    url_for(
                        "main.edit_exam_subject",
                        exam_subject_id=exam_subject.id
                    )
                )

        # ====================================================
        # MAX MARKS
        # ====================================================

        raw_max_marks = request.form.get(
            "max_marks",
            "100"
        )

        try:

            max_marks = float(
                raw_max_marks
            )

        except (
            TypeError,
            ValueError
        ):

            flash(
                "Invalid maximum marks.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.edit_exam_subject",
                    exam_subject_id=exam_subject.id
                )
            )

        if max_marks <= 0:

            flash(
                "Maximum marks must be greater than zero.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.edit_exam_subject",
                    exam_subject_id=exam_subject.id
                )
            )

        # ====================================================
        # PASS MARKS
        # ====================================================

        raw_pass_marks = request.form.get(
            "pass_marks",
            "50"
        )

        try:

            pass_marks = float(
                raw_pass_marks
            )

        except (
            TypeError,
            ValueError
        ):

            flash(
                "Invalid pass marks.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.edit_exam_subject",
                    exam_subject_id=exam_subject.id
                )
            )

        if pass_marks < 0:

            flash(
                "Pass marks cannot be negative.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.edit_exam_subject",
                    exam_subject_id=exam_subject.id
                )
            )

        if pass_marks > max_marks:

            flash(
                "Pass marks cannot exceed maximum marks.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.edit_exam_subject",
                    exam_subject_id=exam_subject.id
                )
            )

        # ====================================================
        # WEIGHT
        # ====================================================

        raw_weight = request.form.get(
            "weight",
            "100"
        )

        try:

            weight = float(
                raw_weight
            )

        except (
            TypeError,
            ValueError
        ):

            flash(
                "Invalid weight.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.edit_exam_subject",
                    exam_subject_id=exam_subject.id
                )
            )

        if weight <= 0:

            flash(
                "Weight must be greater than zero.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.edit_exam_subject",
                    exam_subject_id=exam_subject.id
                )
            )

        # ====================================================
        # DISPLAY ORDER
        # ====================================================

        raw_display_order = request.form.get(
            "display_order",
            "1"
        )

        try:

            display_order = int(
                raw_display_order
            )

        except (
            TypeError,
            ValueError
        ):

            display_order = 1

        if display_order <= 0:

            display_order = 1

        # ====================================================
        # STATUS
        # ====================================================

        status = request.form.get(
            "status",
            "active"
        )

        status = (
            status.strip().lower()
            if status
            else "active"
        )

        if status not in {
            "active",
            "inactive"
        }:

            status = "active"

        # ====================================================
        # DUPLICATE PROTECTION
        #
        # exam + subject + class + section
        #
        # EXCLUDE CURRENT RECORD
        # ====================================================

        duplicate_query = (
            ExamSubject.query
            .filter(
                ExamSubject.exam_id == exam.id,

                ExamSubject.subject_id ==
                subject_id,

                ExamSubject.id !=
                exam_subject.id
            )
        )

        # ----------------------------------------------------
        # Class
        # ----------------------------------------------------

        if class_id is None:

            duplicate_query = (
                duplicate_query
                .filter(
                    ExamSubject.class_id.is_(None)
                )
            )

        else:

            duplicate_query = (
                duplicate_query
                .filter(
                    ExamSubject.class_id ==
                    class_id
                )
            )

        # ----------------------------------------------------
        # Section
        # ----------------------------------------------------

        if section_id is None:

            duplicate_query = (
                duplicate_query
                .filter(
                    ExamSubject.section_id.is_(None)
                )
            )

        else:

            duplicate_query = (
                duplicate_query
                .filter(
                    ExamSubject.section_id ==
                    section_id
                )
            )

        duplicate = (
            duplicate_query
            .first()
        )

        if duplicate:

            class_text = (
                selected_class.name
                if selected_class
                else "All Classes"
            )

            section_text = (
                selected_section.name
                if selected_section
                else "All Sections"
            )

            flash(
                f"{subject.name} already exists for {class_text} / {section_text}.",
                "warning"
            )

            return redirect(
                url_for(
                    "main.edit_exam_subject",
                    exam_subject_id=exam_subject.id
                )
            )

        # ====================================================
        # UPDATE
        # ====================================================

        exam_subject.subject_id = subject_id
        exam_subject.class_id = class_id
        exam_subject.section_id = section_id
        exam_subject.teacher_id = teacher_id
        exam_subject.max_marks = max_marks
        exam_subject.pass_marks = pass_marks
        exam_subject.weight = weight
        exam_subject.display_order = display_order
        exam_subject.status = status

        # ====================================================
        # SAVE
        # ====================================================

        try:

            db.session.commit()

        except Exception as exc:

            db.session.rollback()

            current_app.logger.exception(
                "Failed to update exam subject %s: %s",
                exam_subject_id,
                exc
            )

            flash(
                "An error occurred while updating the exam subject. No changes were saved.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.edit_exam_subject",
                    exam_subject_id=exam_subject.id
                )
            )

        # ====================================================
        # SUCCESS
        # ====================================================

        flash(
            "Exam subject updated successfully.",
            "success"
        )

        return redirect(
            url_for(
                "main.view_exam_subject",
                exam_subject_id=exam_subject.id
            )
        )

    # ========================================================
    # GET DATA
    # ========================================================

    # ========================================================
    # SUBJECTS
    #
    # Only subjects belonging to this exam's program.
    # ========================================================

    subjects_query = (
        Subject.query
        .filter(
            Subject.program_id == exam.program_id,
            Subject.institution_id == exam.institution_id,
            Subject.status == "active"
        )
    )

    if exam.branch_id:

        subjects_query = (
            subjects_query
            .filter(
                db.or_(
                    Subject.branch_id == exam.branch_id,
                    Subject.branch_id.is_(None)
                )
            )
        )

    subjects = (
        subjects_query
        .order_by(
            Subject.name.asc()
        )
        .all()
    )

    # ========================================================
    # CLASSES
    #
    # Optional.
    #
    # Some programs have no classes.
    # ========================================================

    classes_query = (
        Class.query
        .filter(
            Class.program_id == exam.program_id,
            Class.institution_id == exam.institution_id
        )
    )

    if exam.branch_id:

        classes_query = (
            classes_query
            .filter(
                Class.branch_id == exam.branch_id
            )
        )

    if exam.academic_year_id:

        classes_query = (
            classes_query
            .filter(
                Class.academic_year_id ==
                exam.academic_year_id
            )
        )

    classes = (
        classes_query
        .order_by(
            Class.name.asc()
        )
        .all()
    )

    # ========================================================
    # SECTIONS
    # ========================================================

    class_ids = [
        int(item.id)
        for item in classes
    ]

    sections = []

    if class_ids:

        sections = (
            Section.query
            .filter(
                Section.class_id.in_(
                    class_ids
                )
            )
            .order_by(
                Section.name.asc()
            )
            .all()
        )

    # ========================================================
    # PROGRAM TEACHERS
    #
    # IMPORTANT:
    # NOT ALL BRANCH TEACHERS.
    #
    # Only teachers assigned to:
    #
    # Exam Program
    #      ↓
    # TeacherSubject
    #      ↓
    # Teacher
    # ========================================================

    teachers_query = (
        Teacher.query
        .join(
            TeacherSubject,
            TeacherSubject.teacher_id ==
            Teacher.id
        )
        .filter(
            Teacher.institution_id ==
            exam.institution_id,

            Teacher.is_active.is_(True),

            Teacher.status == "active",

            TeacherSubject.institution_id ==
            exam.institution_id,

            TeacherSubject.program_id ==
            exam.program_id,

            TeacherSubject.status ==
            "active"
        )
    )

    # ========================================================
    # BRANCH
    # ========================================================

    if exam.branch_id:

        teachers_query = (
            teachers_query
            .filter(
                Teacher.branch_id ==
                exam.branch_id,

                db.or_(
                    TeacherSubject.branch_id ==
                    exam.branch_id,

                    TeacherSubject.branch_id.is_(None)
                )
            )
        )

    # ========================================================
    # ACADEMIC YEAR
    # ========================================================

    if exam.academic_year_id:

        teachers_query = (
            teachers_query
            .filter(
                db.or_(
                    TeacherSubject.academic_year_id ==
                    exam.academic_year_id,

                    TeacherSubject.academic_year_id.is_(None)
                )
            )
        )

    teachers = (
        teachers_query
        .distinct()
        .order_by(
            Teacher.full_name.asc()
        )
        .all()
    )

    # ========================================================
    # RENDER
    # ========================================================

    return render_template(
        "backend/pages/exam_subjects/edit_exam_subject.html",

        exam_subject=exam_subject,

        exam=exam,

        program=program,

        subjects=subjects,

        classes=classes,

        sections=sections,

        teachers=teachers,

        user=current_user
    )




# ============================================================
# DELETE EXAM SUBJECT
# ============================================================
# ============================================================
# DELETE EXAM SUBJECT
# ============================================================

@bp.route(
    "/exam-subjects/<int:exam_subject_id>/delete",
    methods=["POST"]
)
@login_required
def delete_exam_subject(exam_subject_id):

    # ========================================================
    # SECURITY
    # ========================================================

    if not _exam_subject_can_manage():
        abort(403)

    # ========================================================
    # LOAD WITH SCOPE
    # ========================================================

    query = (
        ExamSubject.query
        .join(
            Exam,
            Exam.id == ExamSubject.exam_id
        )
        .filter(
            ExamSubject.id == exam_subject_id
        )
    )

    query = _exam_subject_scope_query(
        query
    )

    exam_subject = query.first()

    if not exam_subject:

        # AJAX / FETCH REQUEST
        if request.headers.get(
            "X-Requested-With"
        ) == "XMLHttpRequest":

            return jsonify({
                "success": False,
                "message": "Exam subject was not found."
            }), 404

        abort(404)

    # ========================================================
    # DELETE
    # ========================================================

    try:

        db.session.delete(
            exam_subject
        )

        db.session.commit()

        # ====================================================
        # AJAX RESPONSE
        # ====================================================

        if request.headers.get(
            "X-Requested-With"
        ) == "XMLHttpRequest":

            return jsonify({
                "success": True,
                "message": "Exam subject deleted successfully."
            }), 200

        # ====================================================
        # NORMAL POST RESPONSE
        # ====================================================

        flash(
            "Exam subject deleted successfully.",
            "success"
        )

    except Exception as e:

        db.session.rollback()

        current_app.logger.exception(
            "Error deleting ExamSubject ID %s: %s",
            exam_subject_id,
            e
        )

        # ====================================================
        # AJAX ERROR
        # ====================================================

        if request.headers.get(
            "X-Requested-With"
        ) == "XMLHttpRequest":

            return jsonify({
                "success": False,
                "message": "Unable to delete exam subject."
            }), 500

        # ====================================================
        # NORMAL POST ERROR
        # ====================================================

        flash(
            "Unable to delete exam subject.",
            "danger"
        )

    # ========================================================
    # NORMAL POST REDIRECT
    # ========================================================

    return redirect(
        url_for(
            "main.all_exam_subjects"
        )
    )

# ============================================================
# DELETE ENTIRE EXAM
# DELETE EXAM + ALL EXAM SUBJECTS
# ============================================================

@bp.route(
    "/exam/<int:exam_id>/delete",
    methods=["POST"]
)
@login_required
def delete_exam_subjs(exam_id):

    # ========================================================
    # SECURITY
    # ========================================================

    if not _exam_can_manage():
        abort(403)

    # ========================================================
    # LOAD EXAM WITH USER SCOPE
    # ========================================================

    query = (
        Exam.query
        .filter(
            Exam.id == exam_id
        )
    )

    query = _exam_scope_query(
        query
    )

    exam = query.first()

    # ========================================================
    # EXAM NOT FOUND
    # ========================================================

    if not exam:

        if request.headers.get(
            "X-Requested-With"
        ) == "XMLHttpRequest":

            return jsonify({
                "success": False,
                "message": "Exam was not found."
            }), 404

        flash(
            "Exam was not found.",
            "danger"
        )

        return redirect(
            url_for(
                "main.all_exam_subjects"
            )
        )

    # ========================================================
    # EXAM INFORMATION
    # ========================================================

    exam_name = (
        getattr(
            exam,
            "name",
            None
        )
        or
        getattr(
            exam,
            "title",
            None
        )
        or
        f"Exam #{exam.id}"
    )

    exam_id_value = exam.id

    # ========================================================
    # DELETE EXAM SUBJECTS ONLY
    # ========================================================

    try:

        # ----------------------------------------------------
        # DELETE ALL EXAM SUBJECTS BELONGING TO THIS EXAM
        # ----------------------------------------------------

        deleted_exam_subjects = (
            ExamSubject.query
            .filter(
                ExamSubject.exam_id == exam.id
            )
            .delete(
                synchronize_session=False
            )
        )

        # ====================================================
        # COMMIT
        # ====================================================

        db.session.commit()

        # ====================================================
        # SUCCESS
        # ====================================================

        message = (
            f"{deleted_exam_subjects} exam subject(s) "
            f"from {exam_name} were deleted successfully."
        )

        # ====================================================
        # AJAX RESPONSE
        # ====================================================

        if request.headers.get(
            "X-Requested-With"
        ) == "XMLHttpRequest":

            return jsonify({

                "success": True,

                "message": message,

                "exam_id": exam_id_value,

                "deleted_exam_subjects":
                    deleted_exam_subjects

            }), 200

        # ====================================================
        # NORMAL RESPONSE
        # ====================================================

        flash(
            message,
            "success"
        )

        return redirect(
            url_for(
                "main.all_exam_subjects"
            )
        )

    # ========================================================
    # ERROR
    # ========================================================

    except Exception:

        db.session.rollback()

        current_app.logger.exception(
            "Unable to delete ExamSubjects for Exam ID %s",
            exam_id_value
        )

        # ====================================================
        # AJAX ERROR
        # ====================================================

        if request.headers.get(
            "X-Requested-With"
        ) == "XMLHttpRequest":

            return jsonify({

                "success": False,

                "message":
                    "Unable to delete the exam subjects. "
                    "They may have other related records."

            }), 500

        # ====================================================
        # NORMAL ERROR
        # ====================================================

        flash(
            "Unable to delete the exam subjects. "
            "They may have other related records.",
            "danger"
        )

        return redirect(
            url_for(
                "main.all_exam_subjects"
            )
        )


# ============================================================
# ALL STUDENT ATTENDANCE
# SUPERADMIN / SCHOOL ADMIN / BRANCH ADMIN
# ============================================================

@bp.route(
    "/attendance/students",
    methods=["GET"]
)
@login_required
def all_student_attendance():

    # ========================================================
    # SECURITY
    # ========================================================

    allowed_roles = {
        "superadmin",
        "school_admin",
        "institution_admin",
        "branch_admin",
    }

    raw_role = getattr(
        current_user,
        "role",
        None
    )

    user_role = (
        raw_role.value
        if hasattr(raw_role, "value")
        else str(raw_role or "")
    ).strip().lower()

    if user_role not in allowed_roles:
        abort(403)

    # ========================================================
    # CURRENT USER SCOPE
    # ========================================================

    user_institution_id = getattr(
        current_user,
        "institution_id",
        None
    )

    user_branch_id = getattr(
        current_user,
        "branch_id",
        None
    )

    # ========================================================
    # ROLE SCOPE VALIDATION
    # ========================================================

    if user_role in {
        "school_admin",
        "institution_admin",
    }:

        if not user_institution_id:
            abort(403)

    elif user_role == "branch_admin":

        if not user_institution_id:
            abort(403)

        if not user_branch_id:
            abort(403)

    # ========================================================
    # SAFE INTEGER PARSER
    # ========================================================

    def parse_optional_id(
        value,
        field_name
    ):

        if value in (
            None,
            "",
            "None",
            "null",
        ):
            return None

        try:
            parsed = int(value)

        except (
            TypeError,
            ValueError
        ):
            abort(
                400,
                description=f"Invalid {field_name}."
            )

        if parsed <= 0:
            abort(
                400,
                description=f"Invalid {field_name}."
            )

        return parsed

    # ========================================================
    # REQUEST FILTERS
    # ========================================================

    search = request.args.get(
        "search",
        "",
        type=str
    ).strip()

    institution_id = request.args.get(
        "institution_id",
        "",
        type=str
    ).strip()

    branch_id = request.args.get(
        "branch_id",
        "",
        type=str
    ).strip()

    class_id = request.args.get(
        "class_id",
        "",
        type=str
    ).strip()

    section_id = request.args.get(
        "section_id",
        "",
        type=str
    ).strip()

    subject_id = request.args.get(
        "subject_id",
        "",
        type=str
    ).strip()

    teacher_id = request.args.get(
        "teacher_id",
        "",
        type=str
    ).strip()

    status = request.args.get(
        "status",
        "",
        type=str
    ).strip().lower()

    session_type = request.args.get(
        "session_type",
        "",
        type=str
    ).strip().lower()

    date_from = request.args.get(
        "date_from",
        "",
        type=str
    ).strip()

    date_to = request.args.get(
        "date_to",
        "",
        type=str
    ).strip()

    # ========================================================
    # PARSE IDs
    # ========================================================

    requested_institution_id = parse_optional_id(
        institution_id,
        "institution_id"
    )

    requested_branch_id = parse_optional_id(
        branch_id,
        "branch_id"
    )

    requested_class_id = parse_optional_id(
        class_id,
        "class_id"
    )

    requested_section_id = parse_optional_id(
        section_id,
        "section_id"
    )

    requested_subject_id = parse_optional_id(
        subject_id,
        "subject_id"
    )

    requested_teacher_id = parse_optional_id(
        teacher_id,
        "teacher_id"
    )

    # ========================================================
    # ROLE-BASED FILTER SECURITY
    # ========================================================

    if user_role in {
        "school_admin",
        "institution_admin",
    }:

        if requested_institution_id is not None:

            if requested_institution_id != int(
                user_institution_id
            ):
                abort(403)

    elif user_role == "branch_admin":

        if requested_institution_id is not None:

            if requested_institution_id != int(
                user_institution_id
            ):
                abort(403)

        if requested_branch_id is not None:

            if requested_branch_id != int(
                user_branch_id
            ):
                abort(403)

    # ========================================================
    # ALLOWED ATTENDANCE STATUSES
    # ========================================================

    allowed_attendance_statuses = {
        "present",
        "absent",
        "late",
        "excused",
        "sick",
        "leave",
    }

    if status:

        if status not in allowed_attendance_statuses:

            abort(
                400,
                description="Invalid attendance status."
            )

    # ========================================================
    # ALLOWED SESSION TYPES
    # ========================================================

    allowed_session_types = {
        "class",
        "subject",
        "morning",
        "afternoon",
        "exam",
        "other",
    }

    if session_type:

        if session_type not in allowed_session_types:

            abort(
                400,
                description="Invalid attendance session type."
            )

    # ========================================================
    # DATE PARSING
    # ========================================================

    parsed_date_from = None
    parsed_date_to = None

    if date_from:

        try:

            parsed_date_from = datetime.strptime(
                date_from,
                "%Y-%m-%d"
            ).date()

        except ValueError:

            abort(
                400,
                description="Invalid date_from. Use YYYY-MM-DD."
            )

    if date_to:

        try:

            parsed_date_to = datetime.strptime(
                date_to,
                "%Y-%m-%d"
            ).date()

        except ValueError:

            abort(
                400,
                description="Invalid date_to. Use YYYY-MM-DD."
            )

    if (
        parsed_date_from
        and parsed_date_to
        and parsed_date_from > parsed_date_to
    ):

        abort(
            400,
            description="date_from cannot be after date_to."
        )

    # ========================================================
    # PAGINATION
    # ========================================================

    try:

        page = int(
            request.args.get(
                "page",
                1
            )
        )

    except (
        TypeError,
        ValueError
    ):

        page = 1

    try:

        per_page = int(
            request.args.get(
                "per_page",
                25
            )
        )

    except (
        TypeError,
        ValueError
    ):

        per_page = 25

    if page < 1:
        page = 1

    allowed_per_page = {
        10,
        25,
        50,
        100,
    }

    if per_page not in allowed_per_page:
        per_page = 25

    # ========================================================
    # COMMON ATTENDANCE QUERY
    #
    # IMPORTANT:
    # Main records and statistics MUST use
    # exactly the same base query.
    # ========================================================

    base_query = (
        AttendanceRecord.query

        # Attendance Session
        .join(
            AttendanceRecord.session
        )

        # Student
        .join(
            AttendanceRecord.student
        )

        # Enrollment
        .outerjoin(
            AttendanceRecord.enrollment
        )

        # Teacher
        .join(
            Teacher,
            AttendanceSession.teacher_id
            == Teacher.id
        )

        # Subject
        .outerjoin(
            Subject,
            AttendanceSession.subject_id
            == Subject.id
        )

        # Class
        .join(
            Class,
            AttendanceSession.class_id
            == Class.id
        )

        # Section
        .outerjoin(
            Section,
            AttendanceSession.section_id
            == Section.id
        )
    )

    # ========================================================
    # SECURITY SCOPE
    # ========================================================

    if user_role in {
        "school_admin",
        "institution_admin",
    }:

        base_query = base_query.filter(
            AttendanceSession.institution_id
            == user_institution_id
        )

    elif user_role == "branch_admin":

        base_query = base_query.filter(
            AttendanceSession.institution_id
            == user_institution_id,

            AttendanceSession.branch_id
            == user_branch_id
        )

    # ========================================================
    # INSTITUTION FILTER
    # ========================================================

    if requested_institution_id is not None:

        base_query = base_query.filter(
            AttendanceSession.institution_id
            == requested_institution_id
        )

    # ========================================================
    # BRANCH FILTER
    # ========================================================

    if requested_branch_id is not None:

        base_query = base_query.filter(
            AttendanceSession.branch_id
            == requested_branch_id
        )

    # ========================================================
    # CLASS FILTER
    # ========================================================

    if requested_class_id is not None:

        base_query = base_query.filter(
            AttendanceSession.class_id
            == requested_class_id
        )

    # ========================================================
    # SECTION FILTER
    # ========================================================

    if requested_section_id is not None:

        base_query = base_query.filter(
            AttendanceSession.section_id
            == requested_section_id
        )

    # ========================================================
    # SUBJECT FILTER
    # ========================================================

    if requested_subject_id is not None:

        base_query = base_query.filter(
            AttendanceSession.subject_id
            == requested_subject_id
        )

    # ========================================================
    # TEACHER FILTER
    # ========================================================

    if requested_teacher_id is not None:

        base_query = base_query.filter(
            AttendanceSession.teacher_id
            == requested_teacher_id
        )

    # ========================================================
    # STATUS FILTER
    # ========================================================

    if status:

        base_query = base_query.filter(
            AttendanceRecord.status
            == status
        )

    # ========================================================
    # SESSION TYPE FILTER
    # ========================================================

    if session_type:

        base_query = base_query.filter(
            AttendanceSession.session_type
            == session_type
        )

    # ========================================================
    # DATE FROM
    # ========================================================

    if parsed_date_from:

        base_query = base_query.filter(
            AttendanceSession.attendance_date
            >= parsed_date_from
        )

    # ========================================================
    # DATE TO
    # ========================================================

    if parsed_date_to:

        base_query = base_query.filter(
            AttendanceSession.attendance_date
            <= parsed_date_to
        )

    # ========================================================
    # SEARCH
    #
    # IMPORTANT:
    # Teacher.roll_no has been REMOVED.
    # Your Teacher model does not have roll_no.
    # ========================================================

    if search:

        search_pattern = f"%{search}%"

        search_conditions = [

            # ------------------------------------------------
            # STUDENT
            # ------------------------------------------------

            Student.full_name.ilike(
                search_pattern
            ),

            Student.admission_no.ilike(
                search_pattern
            ),

            Student.roll_no.ilike(
                search_pattern
            ),

            Student.username.ilike(
                search_pattern
            ),

            # ------------------------------------------------
            # TEACHER
            # ------------------------------------------------

            Teacher.full_name.ilike(
                search_pattern
            ),

            Teacher.username.ilike(
                search_pattern
            ),

            # ------------------------------------------------
            # SUBJECT
            # ------------------------------------------------

            Subject.name.ilike(
                search_pattern
            ),

            # ------------------------------------------------
            # CLASS
            # ------------------------------------------------

            Class.name.ilike(
                search_pattern
            ),

            # ------------------------------------------------
            # SECTION
            # ------------------------------------------------

            Section.name.ilike(
                search_pattern
            ),
        ]

        base_query = base_query.filter(
            or_(
                *search_conditions
            )
        )

    # ========================================================
    # MAIN RECORDS
    # ========================================================

    records_query = (
        base_query
        .order_by(
            AttendanceSession.attendance_date.desc(),
            AttendanceRecord.created_at.desc(),
            AttendanceRecord.id.desc()
        )
    )

    # ========================================================
    # PAGINATION
    # ========================================================

    pagination = records_query.paginate(
        page=page,
        per_page=per_page,
        error_out=False
    )

    attendance_records = pagination.items

    # ========================================================
    # STATISTICS
    #
    # SAME base_query.
    #
    # This fixes the problem where:
    #
    # records = 2
    # statistics = 0
    #
    # ========================================================

    from sqlalchemy import func, case

    stats_row = (
        base_query
        .with_entities(

            func.count(
                AttendanceRecord.id
            ).label(
                "total_attendance"
            ),

            func.sum(
                case(
                    (
                        AttendanceRecord.status
                        == "present",
                        1
                    ),
                    else_=0
                )
            ).label(
                "present_count"
            ),

            func.sum(
                case(
                    (
                        AttendanceRecord.status
                        == "absent",
                        1
                    ),
                    else_=0
                )
            ).label(
                "absent_count"
            ),

            func.sum(
                case(
                    (
                        AttendanceRecord.status
                        == "late",
                        1
                    ),
                    else_=0
                )
            ).label(
                "late_count"
            ),

            func.sum(
                case(
                    (
                        AttendanceRecord.status
                        == "excused",
                        1
                    ),
                    else_=0
                )
            ).label(
                "excused_count"
            ),

            func.sum(
                case(
                    (
                        AttendanceRecord.status
                        == "sick",
                        1
                    ),
                    else_=0
                )
            ).label(
                "sick_count"
            ),

            func.sum(
                case(
                    (
                        AttendanceRecord.status
                        == "leave",
                        1
                    ),
                    else_=0
                )
            ).label(
                "leave_count"
            ),
        )
        .first()
    )

    # ========================================================
    # SAFE STATISTICS VALUES
    # ========================================================

    total_attendance = int(
        stats_row.total_attendance or 0
    )

    present_count = int(
        stats_row.present_count or 0
    )

    absent_count = int(
        stats_row.absent_count or 0
    )

    late_count = int(
        stats_row.late_count or 0
    )

    excused_count = int(
        stats_row.excused_count or 0
    )

    sick_count = int(
        stats_row.sick_count or 0
    )

    leave_count = int(
        stats_row.leave_count or 0
    )

    # ========================================================
    # ATTENDANCE PERCENTAGE
    # ========================================================

    if total_attendance > 0:

        attendance_percentage = round(
            (
                present_count
                / total_attendance
            ) * 100,
            2
        )

    else:

        attendance_percentage = 0

    # ========================================================
    # FILTER DATA
    # ========================================================

    # ========================================================
    # INSTITUTIONS
    # ========================================================

    institutions_query = Institution.query

    if user_role in {
        "school_admin",
        "institution_admin",
        "branch_admin",
    }:

        institutions_query = institutions_query.filter(
            Institution.id
            == user_institution_id
        )

    institutions = (
        institutions_query
        .order_by(
            Institution.name.asc()
        )
        .all()
    )

    # ========================================================
    # BRANCHES
    # ========================================================

    branches_query = Branch.query

    if user_role in {
        "school_admin",
        "institution_admin",
    }:

        branches_query = branches_query.filter(
            Branch.institution_id
            == user_institution_id
        )

    elif user_role == "branch_admin":

        branches_query = branches_query.filter(
            Branch.institution_id
            == user_institution_id,

            Branch.id
            == user_branch_id
        )

    elif user_role == "superadmin":

        if requested_institution_id is not None:

            branches_query = branches_query.filter(
                Branch.institution_id
                == requested_institution_id
            )

    branches = (
        branches_query
        .order_by(
            Branch.name.asc()
        )
        .all()
    )

    # ========================================================
    # CLASSES
    # ========================================================

    classes_query = Class.query

    if user_role in {
        "school_admin",
        "institution_admin",
    }:

        classes_query = classes_query.filter(
            Class.institution_id
            == user_institution_id
        )

    elif user_role == "branch_admin":

        classes_query = classes_query.filter(
            Class.institution_id
            == user_institution_id,

            Class.branch_id
            == user_branch_id
        )

    elif user_role == "superadmin":

        if requested_institution_id is not None:

            classes_query = classes_query.filter(
                Class.institution_id
                == requested_institution_id
            )

        if requested_branch_id is not None:

            classes_query = classes_query.filter(
                Class.branch_id
                == requested_branch_id
            )

    # --------------------------------------------------------
    # APPLY SELECTED FILTERS
    # --------------------------------------------------------

    if requested_institution_id is not None:

        classes_query = classes_query.filter(
            Class.institution_id
            == requested_institution_id
        )

    if requested_branch_id is not None:

        classes_query = classes_query.filter(
            Class.branch_id
            == requested_branch_id
        )

    classes = (
        classes_query
        .order_by(
            Class.name.asc()
        )
        .all()
    )

    # ========================================================
    # SECTIONS
    # ========================================================

    sections_query = Section.query

    if user_role in {
        "school_admin",
        "institution_admin",
    }:

        sections_query = sections_query.filter(
            Section.institution_id
            == user_institution_id
        )

    elif user_role == "branch_admin":

        sections_query = sections_query.filter(
            Section.institution_id
            == user_institution_id,

            Section.branch_id
            == user_branch_id
        )

    elif user_role == "superadmin":

        if requested_institution_id is not None:

            sections_query = sections_query.filter(
                Section.institution_id
                == requested_institution_id
            )

        if requested_branch_id is not None:

            sections_query = sections_query.filter(
                Section.branch_id
                == requested_branch_id
            )

    if requested_class_id is not None:

        sections_query = sections_query.filter(
            Section.class_id
            == requested_class_id
        )

    sections = (
        sections_query
        .order_by(
            Section.name.asc()
        )
        .all()
    )

    # ========================================================
    # SUBJECTS
    # ========================================================

    subjects_query = Subject.query

    if user_role in {
        "school_admin",
        "institution_admin",
        "branch_admin",
    }:

        subjects_query = subjects_query.filter(
            Subject.institution_id
            == user_institution_id
        )

    elif user_role == "superadmin":

        if requested_institution_id is not None:

            subjects_query = subjects_query.filter(
                Subject.institution_id
                == requested_institution_id
            )

    subjects = (
        subjects_query
        .order_by(
            Subject.name.asc()
        )
        .all()
    )

    # ========================================================
    # TEACHERS
    # ========================================================

    teachers_query = Teacher.query

    if user_role in {
        "school_admin",
        "institution_admin",
    }:

        teachers_query = teachers_query.filter(
            Teacher.institution_id
            == user_institution_id
        )

    elif user_role == "branch_admin":

        teachers_query = teachers_query.filter(
            Teacher.institution_id
            == user_institution_id,

            Teacher.branch_id
            == user_branch_id
        )

    elif user_role == "superadmin":

        if requested_institution_id is not None:

            teachers_query = teachers_query.filter(
                Teacher.institution_id
                == requested_institution_id
            )

        if requested_branch_id is not None:

            teachers_query = teachers_query.filter(
                Teacher.branch_id
                == requested_branch_id
            )

    teachers = (
        teachers_query
        .order_by(
            Teacher.full_name.asc()
        )
        .all()
    )

    # ========================================================
    # RENDER
    # ========================================================

    return render_template(
        "backend/pages/attendance/all_student_attendance.html",

        # ====================================================
        # RECORDS
        # ====================================================

        attendance_records=attendance_records,

        pagination=pagination,

        page=page,

        per_page=per_page,

        # ====================================================
        # FILTER VALUES
        # ====================================================

        search=search,

        selected_institution_id=institution_id,

        selected_branch_id=branch_id,

        selected_class_id=class_id,

        selected_section_id=section_id,

        selected_subject_id=subject_id,

        selected_teacher_id=teacher_id,

        selected_status=status,

        selected_session_type=session_type,

        selected_date_from=date_from,
        user=current_user,

        selected_date_to=date_to,

        # ====================================================
        # FILTER DATA
        # ====================================================

        institutions=institutions,

        branches=branches,

        classes=classes,

        sections=sections,

        subjects=subjects,

        teachers=teachers,

        # ====================================================
        # STATISTICS
        # ====================================================

        total_attendance=total_attendance,

        present_count=present_count,

        absent_count=absent_count,

        late_count=late_count,

        excused_count=excused_count,

        sick_count=sick_count,

        leave_count=leave_count,

        attendance_percentage=attendance_percentage,

        # ====================================================
        # OPTIONS
        # ====================================================

        attendance_statuses=[
            "present",
            "absent",
            "late",
            "excused",
            "sick",
            "leave",
        ],

        session_types=[
            "class",
            "subject",
            "morning",
            "afternoon",
            "exam",
            "other",
        ],
    )





@bp.route(
    "/attendance/record/<int:record_id>/status",
    methods=["POST"]
)
@login_required
def update_attendance_record_status(record_id):

    # ============================================================
    # ROLE SECURITY
    # ============================================================

    role = current_user.role

    if hasattr(role, "value"):
        role = role.value

    role = str(role or "").strip().lower()

    allowed_roles = {
        "superadmin",
        "school_admin",
        "institution_admin",
        "branch_admin",
    }

    if role not in allowed_roles:
        return jsonify({
            "success": False,
            "message": "You are not authorized to update attendance."
        }), 403


    # ============================================================
    # LOAD ATTENDANCE RECORD
    # ============================================================

    record = (
        AttendanceRecord.query
        .join(
            AttendanceSession,
            AttendanceRecord.attendance_session_id
            == AttendanceSession.id
        )
        .filter(
            AttendanceRecord.id == record_id
        )
        .first()
    )

    if not record:
        return jsonify({
            "success": False,
            "message": "Attendance record was not found."
        }), 404


    # ============================================================
    # LOAD SESSION
    # ============================================================

    session = record.session

    if not session:
        return jsonify({
            "success": False,
            "message": "Attendance session was not found."
        }), 404


    # ============================================================
    # INSTITUTION / BRANCH SECURITY
    # ============================================================

    if role != "superadmin":

        user_institution_id = getattr(
            current_user,
            "institution_id",
            None
        )

        # --------------------------------------------------------
        # USER MUST BELONG TO AN INSTITUTION
        # --------------------------------------------------------

        if not user_institution_id:
            return jsonify({
                "success": False,
                "message": (
                    "Your account is not linked to an institution."
                )
            }), 403


        # --------------------------------------------------------
        # INSTITUTION SCOPE
        # --------------------------------------------------------

        if session.institution_id != user_institution_id:
            return jsonify({
                "success": False,
                "message": (
                    "You cannot update attendance outside "
                    "your institution."
                )
            }), 403


        # --------------------------------------------------------
        # BRANCH ADMIN SCOPE
        # --------------------------------------------------------

        if role == "branch_admin":

            user_branch_id = getattr(
                current_user,
                "branch_id",
                None
            )

            if not user_branch_id:
                return jsonify({
                    "success": False,
                    "message": (
                        "Your account is not linked to a branch."
                    )
                }), 403


            if session.branch_id != user_branch_id:
                return jsonify({
                    "success": False,
                    "message": (
                        "You cannot update attendance outside "
                        "your branch."
                    )
                }), 403


    # ============================================================
    # SESSION STATUS SECURITY
    # ============================================================

    session_status = (
        str(session.status or "")
        .strip()
        .lower()
    )

    if session_status in {
        "locked",
        "cancelled",
    }:

        return jsonify({
            "success": False,
            "message": (
                "This attendance session is "
                "locked or cancelled and cannot be changed."
            )
        }), 409


    # ============================================================
    # REQUEST DATA
    # ============================================================

    data = request.get_json(silent=True)

    if not data:
        data = request.form


    # ============================================================
    # STATUS
    # ============================================================

    status = str(
        data.get("status", "")
    ).strip().lower()


    # ============================================================
    # NOTES
    # ============================================================

    notes = data.get("notes")

    if notes is not None:

        notes = str(notes).strip()

        if not notes:
            notes = None


    # ============================================================
    # ALLOWED ATTENDANCE STATUSES
    # ============================================================

    allowed_statuses = {
        "present",
        "absent",
        "late",
        "excused",
    }

    if status not in allowed_statuses:

        return jsonify({
            "success": False,
            "message": (
                "Invalid attendance status. "
                "Allowed statuses are Present, Absent, "
                "Late, and Excused."
            )
        }), 400


    # ============================================================
    # OLD STATUS
    # ============================================================

    old_status = (
        str(record.status).strip().lower()
        if record.status
        else None
    )


    # ============================================================
    # MINUTES LATE
    # ============================================================

    minutes_late = None


    if status == "late":

        raw_minutes_late = data.get(
            "minutes_late"
        )


        # --------------------------------------------------------
        # DEFAULT TO 1 MINUTE IF NOT PROVIDED
        # --------------------------------------------------------

        if raw_minutes_late in (
            None,
            "",
        ):

            minutes_late = 1

        else:

            try:

                # Prevent values such as 10.5
                # from silently becoming 10.

                if isinstance(
                    raw_minutes_late,
                    str
                ):

                    raw_minutes_late = (
                        raw_minutes_late.strip()
                    )


                minutes_late = int(
                    raw_minutes_late
                )

            except (
                TypeError,
                ValueError
            ):

                return jsonify({
                    "success": False,
                    "message": (
                        "Minutes late must be "
                        "a valid whole number."
                    )
                }), 400


        # --------------------------------------------------------
        # NEGATIVE VALUE
        # --------------------------------------------------------

        if minutes_late < 0:

            return jsonify({
                "success": False,
                "message": (
                    "Minutes late cannot be negative."
                )
            }), 400


        # --------------------------------------------------------
        # OPTIONAL SAFETY LIMIT
        # --------------------------------------------------------
        #
        # 24 hours = 1440 minutes.
        #
        # This prevents accidental values such as
        # 999999 from being stored.
        #

        if minutes_late > 1440:

            return jsonify({
                "success": False,
                "message": (
                    "Minutes late cannot be greater "
                    "than 1440 minutes."
                )
            }), 400


    # ============================================================
    # UPDATE STATUS
    # ============================================================

    record.status = status


    # ============================================================
    # UPDATE NOTES
    # ============================================================

    record.notes = notes


    # ============================================================
    # PRESENT
    # ============================================================

    if status == "present":

        # --------------------------------------------------------
        # Present means the student attended normally.
        #
        # We intentionally do not create a fake check-in time.
        # We also clear minutes_late because the student is no
        # longer marked as late.
        # --------------------------------------------------------

        record.minutes_late = None


    # ============================================================
    # ABSENT
    # ============================================================

    elif status == "absent":

        # --------------------------------------------------------
        # Absent student should not retain timing information.
        # --------------------------------------------------------

        record.check_in = None
        record.check_out = None
        record.minutes_late = None


    # ============================================================
    # LATE
    # ============================================================

    elif status == "late":

        # --------------------------------------------------------
        # Late student attended but arrived late.
        #
        # We store the exact number of minutes provided by the
        # administrator.
        # --------------------------------------------------------

        record.minutes_late = minutes_late


    # ============================================================
    # EXCUSED
    # ============================================================

    elif status == "excused":

        # --------------------------------------------------------
        # Excused means the student is officially excused from
        # attendance.
        #
        # No late information should remain.
        # --------------------------------------------------------

        record.check_in = None
        record.check_out = None
        record.minutes_late = None


    # ============================================================
    # UPDATED TIME
    # ============================================================

    record.updated_at = datetime.utcnow()


    # ============================================================
    # SAVE DATABASE
    # ============================================================

    try:

        db.session.commit()

    except Exception:

        db.session.rollback()

        return jsonify({
            "success": False,
            "message": (
                "Attendance could not be updated. "
                "Please try again."
            )
        }), 500


    # ============================================================
    # RESPONSE
    # ============================================================

    return jsonify({
        "success": True,
        "message": "Attendance updated successfully.",

        "record_id": record.id,

        "old_status": old_status,

        "status": record.status,

        "status_label": (
            record.status.capitalize()
        ),

        "minutes_late": (
            record.minutes_late
            if record.minutes_late is not None
            else None
        ),

        "notes": record.notes or "",

    }), 200




# ============================================================
# ATTENDANCE REPORTS
# TODAY / YESTERDAY / WEEKLY / MONTHLY / YEARLY
# GROUP BY CLASS / SUBJECT / PROGRAM
# PostgreSQL / Neon
# ============================================================
# ============================================================
# ATTENDANCE REPORTS
# ============================================================
@bp.route(
    "/attendance/reports",
    methods=["GET"]
)
@login_required
def attendance_reports():

    # ========================================================
    # SECURITY
    # ========================================================

    user = current_user

    allowed_roles = {
        "superadmin",
        "school_admin",
        "branch_admin",
        "teacher",
    }

    if not user.is_authenticated:
        abort(403)

    user_role = getattr(
        user,
        "role",
        None
    )

    if user_role not in allowed_roles:
        abort(403)

    institution_id = getattr(
        user,
        "institution_id",
        None
    )

    user_branch_id = getattr(
        user,
        "branch_id",
        None
    )

    # ========================================================
    # BASIC USER SCOPE VALIDATION
    # ========================================================

    if (
        user_role != "superadmin"
        and not institution_id
    ):
        abort(403)

    if (
        user_role == "branch_admin"
        and not user_branch_id
    ):
        abort(403)

    # ========================================================
    # FILTERS
    # ========================================================

    search = request.args.get(
        "search",
        "",
        type=str
    ).strip()

    academic_year_id = request.args.get(
        "academic_year_id",
        type=int
    )

    branch_id = request.args.get(
        "branch_id",
        type=int
    )

    class_id = request.args.get(
        "class_id",
        type=int
    )

    section_id = request.args.get(
        "section_id",
        type=int
    )

    subject_id = request.args.get(
        "subject_id",
        type=int
    )

    teacher_id = request.args.get(
        "teacher_id",
        type=int
    )

    status = request.args.get(
        "status",
        "",
        type=str
    ).strip().lower()

    date_from = request.args.get(
        "date_from",
        "",
        type=str
    ).strip()

    date_to = request.args.get(
        "date_to",
        "",
        type=str
    ).strip()

    # ========================================================
    # VALID STATUSES
    # ========================================================

    valid_statuses = {
        "present",
        "absent",
        "late",
        "excused",
        "sick",
        "leave",
    }

    if status not in valid_statuses:
        status = ""

    # ========================================================
    # DATE PARSING
    # ========================================================

    parsed_date_from = None
    parsed_date_to = None

    if date_from:

        try:

            parsed_date_from = datetime.strptime(
                date_from,
                "%Y-%m-%d"
            ).date()

        except (
            TypeError,
            ValueError
        ):

            parsed_date_from = None

    if date_to:

        try:

            parsed_date_to = datetime.strptime(
                date_to,
                "%Y-%m-%d"
            ).date()

        except (
            TypeError,
            ValueError
        ):

            parsed_date_to = None

    # ========================================================
    # FIX INVALID DATE RANGE
    # ========================================================

    if (
        parsed_date_from
        and parsed_date_to
        and parsed_date_from > parsed_date_to
    ):

        parsed_date_from, parsed_date_to = (
            parsed_date_to,
            parsed_date_from
        )

        date_from = (
            parsed_date_from.isoformat()
        )

        date_to = (
            parsed_date_to.isoformat()
        )

    # ========================================================
    # PAGINATION SETTINGS
    # ========================================================

    allowed_per_page = (
        10,
        25,
        50,
        100,
    )

    try:

        per_page = int(
            request.args.get(
                "per_page",
                25
            )
        )

    except (
        TypeError,
        ValueError
    ):

        per_page = 25

    if per_page not in allowed_per_page:
        per_page = 25

    try:

        page = int(
            request.args.get(
                "page",
                1
            )
        )

    except (
        TypeError,
        ValueError
    ):

        page = 1

    if page < 1:
        page = 1

    # ========================================================
    # TEACHER LOGIN SCOPE
    # ========================================================

    current_teacher_id = None

    if user_role == "teacher":

        teacher = getattr(
            g,
            "teacher",
            None
        )

        if not teacher:
            abort(403)

        current_teacher_id = getattr(
            teacher,
            "id",
            None
        )

        if not current_teacher_id:
            abort(403)

    # ========================================================
    # EFFECTIVE BRANCH
    # ========================================================

    effective_branch_id = branch_id

    if user_role == "branch_admin":

        if effective_branch_id is None:

            effective_branch_id = (
                user_branch_id
            )

        elif (
            effective_branch_id
            != user_branch_id
        ):

            abort(403)

    # ========================================================
    # EFFECTIVE TEACHER
    # ========================================================

    effective_teacher_id = teacher_id

    if user_role == "teacher":

        if effective_teacher_id is None:

            effective_teacher_id = (
                current_teacher_id
            )

        elif (
            effective_teacher_id
            != current_teacher_id
        ):

            abort(403)

    # ========================================================
    # STUDENT SEARCH HELPER
    # ========================================================

    def apply_student_search(
        model_query
    ):

        if not search:
            return model_query

        search_pattern = (
            f"%{search}%"
        )

        conditions = []

        if hasattr(
            Student,
            "name"
        ):

            conditions.append(
                Student.name.ilike(
                    search_pattern
                )
            )

        if hasattr(
            Student,
            "full_name"
        ):

            conditions.append(
                Student.full_name.ilike(
                    search_pattern
                )
            )

        if hasattr(
            Student,
            "admission_no"
        ):

            conditions.append(
                Student.admission_no.ilike(
                    search_pattern
                )
            )

        if hasattr(
            Student,
            "student_id"
        ):

            conditions.append(
                Student.student_id.ilike(
                    search_pattern
                )
            )

        if hasattr(
            Student,
            "roll_no"
        ):

            conditions.append(
                Student.roll_no.ilike(
                    search_pattern
                )
            )

        if conditions:

            model_query = model_query.filter(
                or_(*conditions)
            )

        return model_query

    # ========================================================
    # BASE REPORT QUERY
    # ========================================================

    query = (
        AttendanceRecord.query
        .join(
            AttendanceSession,
            AttendanceRecord.attendance_session_id
            == AttendanceSession.id
        )
        .join(
            Student,
            AttendanceRecord.student_id
            == Student.id
        )
        .filter(
            AttendanceRecord.student_id.isnot(None)
        )
    )

    # ========================================================
    # INSTITUTION SECURITY
    # ========================================================

    if user_role != "superadmin":

        query = query.filter(
            AttendanceSession.institution_id
            == institution_id
        )

    # ========================================================
    # BRANCH SECURITY / FILTER
    # ========================================================

    if effective_branch_id:

        query = query.filter(
            AttendanceSession.branch_id
            == effective_branch_id
        )

    # ========================================================
    # TEACHER SECURITY / FILTER
    # ========================================================

    if effective_teacher_id:

        query = query.filter(
            AttendanceSession.teacher_id
            == effective_teacher_id
        )

    # ========================================================
    # ACADEMIC YEAR
    # ========================================================

    if academic_year_id:

        query = query.filter(
            AttendanceSession.academic_year_id
            == academic_year_id
        )

    # ========================================================
    # CLASS
    # ========================================================

    if class_id:

        query = query.filter(
            AttendanceSession.class_id
            == class_id
        )

    # ========================================================
    # SECTION
    # ========================================================

    if section_id:

        query = query.filter(
            AttendanceSession.section_id
            == section_id
        )

    # ========================================================
    # SUBJECT
    # ========================================================

    if subject_id:

        query = query.filter(
            AttendanceSession.subject_id
            == subject_id
        )

    # ========================================================
    # STATUS
    # ========================================================

    if status:

        query = query.filter(
            AttendanceRecord.status
            == status
        )

    # ========================================================
    # DATE FROM
    # ========================================================

    if parsed_date_from:

        query = query.filter(
            AttendanceSession.attendance_date
            >= parsed_date_from
        )

    # ========================================================
    # DATE TO
    # ========================================================

    if parsed_date_to:

        query = query.filter(
            AttendanceSession.attendance_date
            <= parsed_date_to
        )

    # ========================================================
    # STUDENT SEARCH
    # ========================================================

    query = apply_student_search(
        query
    )

    # ========================================================
    # ORDER
    # ========================================================

    query = query.order_by(
        AttendanceSession.attendance_date.desc(),
        AttendanceRecord.id.desc()
    )

    # ========================================================
    # FIRST PAGINATION
    # ========================================================

    pagination = query.paginate(
        page=page,
        per_page=per_page,
        error_out=False
    )

    # ========================================================
    # CRITICAL PAGINATION FIX
    #
    # Example:
    #
    # Total records = 2
    # Per page       = 25
    # Available pages = 1
    #
    # But URL may contain:
    #
    # ?page=2
    #
    # That produces:
    #
    # Showing 0 of 2
    #
    # So automatically move to the last valid page.
    # ========================================================

    if (
        pagination.total > 0
        and page > pagination.pages
    ):

        page = pagination.pages

        if page < 1:
            page = 1

        pagination = query.paginate(
            page=page,
            per_page=per_page,
            error_out=False
        )

    # ========================================================
    # FINAL REPORT DATA
    # ========================================================

    attendance_reports_data = (
        pagination.items
    )

    # ========================================================
    # STATISTICS QUERY
    #
    # IMPORTANT:
    # Uses exactly the same security
    # and filters as the main report.
    # ========================================================

    stats_query = (
        AttendanceRecord.query
        .join(
            AttendanceSession,
            AttendanceRecord.attendance_session_id
            == AttendanceSession.id
        )
        .join(
            Student,
            AttendanceRecord.student_id
            == Student.id
        )
        .filter(
            AttendanceRecord.student_id.isnot(None)
        )
    )

    # ========================================================
    # STATISTICS INSTITUTION
    # ========================================================

    if user_role != "superadmin":

        stats_query = stats_query.filter(
            AttendanceSession.institution_id
            == institution_id
        )

    # ========================================================
    # STATISTICS BRANCH
    # ========================================================

    if effective_branch_id:

        stats_query = stats_query.filter(
            AttendanceSession.branch_id
            == effective_branch_id
        )

    # ========================================================
    # STATISTICS TEACHER
    # ========================================================

    if effective_teacher_id:

        stats_query = stats_query.filter(
            AttendanceSession.teacher_id
            == effective_teacher_id
        )

    # ========================================================
    # STATISTICS ACADEMIC YEAR
    # ========================================================

    if academic_year_id:

        stats_query = stats_query.filter(
            AttendanceSession.academic_year_id
            == academic_year_id
        )

    # ========================================================
    # STATISTICS CLASS
    # ========================================================

    if class_id:

        stats_query = stats_query.filter(
            AttendanceSession.class_id
            == class_id
        )

    # ========================================================
    # STATISTICS SECTION
    # ========================================================

    if section_id:

        stats_query = stats_query.filter(
            AttendanceSession.section_id
            == section_id
        )

    # ========================================================
    # STATISTICS SUBJECT
    # ========================================================

    if subject_id:

        stats_query = stats_query.filter(
            AttendanceSession.subject_id
            == subject_id
        )

    # ========================================================
    # STATISTICS STATUS
    # ========================================================

    if status:

        stats_query = stats_query.filter(
            AttendanceRecord.status
            == status
        )

    # ========================================================
    # STATISTICS DATE FROM
    # ========================================================

    if parsed_date_from:

        stats_query = stats_query.filter(
            AttendanceSession.attendance_date
            >= parsed_date_from
        )

    # ========================================================
    # STATISTICS DATE TO
    # ========================================================

    if parsed_date_to:

        stats_query = stats_query.filter(
            AttendanceSession.attendance_date
            <= parsed_date_to
        )

    # ========================================================
    # STATISTICS SEARCH
    # ========================================================

    stats_query = apply_student_search(
        stats_query
    )

    # ========================================================
    # TOTAL ATTENDANCE
    # ========================================================

    total_attendance = (
        stats_query
        .with_entities(
            func.count(
                AttendanceRecord.id
            )
        )
        .scalar()
        or 0
    )

    # ========================================================
    # PRESENT
    # ========================================================

    present_count = (
        stats_query
        .filter(
            AttendanceRecord.status
            == "present"
        )
        .with_entities(
            func.count(
                AttendanceRecord.id
            )
        )
        .scalar()
        or 0
    )

    # ========================================================
    # ABSENT
    # ========================================================

    absent_count = (
        stats_query
        .filter(
            AttendanceRecord.status
            == "absent"
        )
        .with_entities(
            func.count(
                AttendanceRecord.id
            )
        )
        .scalar()
        or 0
    )

    # ========================================================
    # LATE
    # ========================================================

    late_count = (
        stats_query
        .filter(
            AttendanceRecord.status
            == "late"
        )
        .with_entities(
            func.count(
                AttendanceRecord.id
            )
        )
        .scalar()
        or 0
    )

    # ========================================================
    # EXCUSED
    # ========================================================

    excused_count = (
        stats_query
        .filter(
            AttendanceRecord.status
            == "excused"
        )
        .with_entities(
            func.count(
                AttendanceRecord.id
            )
        )
        .scalar()
        or 0
    )

    # ========================================================
    # SICK
    # ========================================================

    sick_count = (
        stats_query
        .filter(
            AttendanceRecord.status
            == "sick"
        )
        .with_entities(
            func.count(
                AttendanceRecord.id
            )
        )
        .scalar()
        or 0
    )

    # ========================================================
    # LEAVE
    # ========================================================

    leave_count = (
        stats_query
        .filter(
            AttendanceRecord.status
            == "leave"
        )
        .with_entities(
            func.count(
                AttendanceRecord.id
            )
        )
        .scalar()
        or 0
    )

    # ========================================================
    # UNIQUE STUDENTS
    # ========================================================

    total_students = (
        stats_query
        .with_entities(
            func.count(
                func.distinct(
                    AttendanceRecord.student_id
                )
            )
        )
        .scalar()
        or 0
    )

    # ========================================================
    # ATTENDANCE RATE
    # ========================================================

    attendance_rate = 0

    if total_attendance:

        attendance_rate = round(
            (
                present_count
                + late_count
            )
            / total_attendance
            * 100,
            1
        )

    # ========================================================
    # ACADEMIC YEARS
    # ========================================================

    academic_year_query = (
        AcademicYear.query
    )

    if user_role != "superadmin":

        academic_year_query = (
            academic_year_query.filter(
                AcademicYear.institution_id
                == institution_id
            )
        )

    academic_years = (
        academic_year_query
        .order_by(
            AcademicYear.id.desc()
        )
        .all()
    )

    # ========================================================
    # BRANCHES
    # ========================================================

    branch_query = Branch.query

    if user_role != "superadmin":

        branch_query = (
            branch_query.filter(
                Branch.institution_id
                == institution_id
            )
        )

    if user_role == "branch_admin":

        branch_query = (
            branch_query.filter(
                Branch.id
                == user_branch_id
            )
        )

    branches = (
        branch_query
        .order_by(
            Branch.name.asc()
        )
        .all()
    )

    # ========================================================
    # CLASSES
    # ========================================================

    class_query = Class.query

    if hasattr(
        Class,
        "institution_id"
    ):

        if user_role != "superadmin":

            class_query = (
                class_query.filter(
                    Class.institution_id
                    == institution_id
                )
            )

    if hasattr(
        Class,
        "branch_id"
    ):

        if effective_branch_id:

            class_query = (
                class_query.filter(
                    Class.branch_id
                    == effective_branch_id
                )
            )

    classes = (
        class_query
        .order_by(
            Class.name.asc()
        )
        .all()
    )

    # ========================================================
    # ACCESSIBLE CLASS IDS
    # ========================================================

    accessible_class_ids = {
        item.id
        for item in classes
        if getattr(
            item,
            "id",
            None
        )
    }

    # ========================================================
    # SECTIONS
    # ========================================================

    section_query = Section.query

    if class_id:

        # ----------------------------------------------------
        # If selected class is not accessible,
        # do not expose sections from it.
        # ----------------------------------------------------

        if (
            accessible_class_ids
            and class_id
            not in accessible_class_ids
        ):

            section_query = section_query.filter(
                Section.id == -1
            )

        else:

            section_query = (
                section_query.filter(
                    Section.class_id
                    == class_id
                )
            )

    else:

        # ----------------------------------------------------
        # No class selected:
        # show only sections belonging to
        # accessible classes.
        # ----------------------------------------------------

        if accessible_class_ids:

            section_query = (
                section_query.filter(
                    Section.class_id.in_(
                        accessible_class_ids
                    )
                )
            )

        else:

            section_query = (
                section_query.filter(
                    Section.id == -1
                )
            )

    sections = (
        section_query
        .order_by(
            Section.name.asc()
        )
        .all()
    )

    # ========================================================
    # SUBJECTS
    # ========================================================

    subject_query = Subject.query

    if hasattr(
        Subject,
        "institution_id"
    ):

        if user_role != "superadmin":

            subject_query = (
                subject_query.filter(
                    Subject.institution_id
                    == institution_id
                )
            )

    subjects = (
        subject_query
        .order_by(
            Subject.name.asc()
        )
        .all()
    )

    # ========================================================
    # TEACHERS
    # ========================================================

    teacher_query = Teacher.query

    if hasattr(
        Teacher,
        "institution_id"
    ):

        if user_role != "superadmin":

            teacher_query = (
                teacher_query.filter(
                    Teacher.institution_id
                    == institution_id
                )
            )

    if hasattr(
        Teacher,
        "branch_id"
    ):

        if effective_branch_id:

            teacher_query = (
                teacher_query.filter(
                    Teacher.branch_id
                    == effective_branch_id
                )
            )

    # ========================================================
    # TEACHER USER SCOPE
    # ========================================================

    if user_role == "teacher":

        teacher_query = (
            teacher_query.filter(
                Teacher.id
                == current_teacher_id
            )
        )

    teachers = (
        teacher_query
        .order_by(
            Teacher.full_name.asc()
        )
        .all()
    )

    # ========================================================
    # IMPORTANT:
    # Keep displayed filter value compatible with
    # the selected URL value.
    #
    # For branch_admin / teacher, effective values are used
    # for security, while original values remain available
    # to the template.
    # ========================================================

    # ========================================================
    # RENDER
    # ========================================================

    return render_template(
        "backend/pages/attendance/attendance_reports.html",

        # ====================================================
        # REPORT DATA
        # ====================================================

        attendance_reports=attendance_reports_data,

        pagination=pagination,

        # ====================================================
        # STATISTICS
        # ====================================================

        total_students=total_students,

        total_attendance=total_attendance,

        present_count=present_count,

        absent_count=absent_count,

        late_count=late_count,

        excused_count=excused_count,

        sick_count=sick_count,

        leave_count=leave_count,

        attendance_rate=attendance_rate,

        # ====================================================
        # FILTER VALUES
        # ====================================================

        search=search,

        academic_year_id=academic_year_id,

        branch_id=branch_id,

        class_id=class_id,

        section_id=section_id,

        subject_id=subject_id,

        teacher_id=teacher_id,

        status=status,

        date_from=date_from,

        date_to=date_to,

        per_page=per_page,

        page=page,

        # ====================================================
        # EFFECTIVE SECURITY VALUES
        # ====================================================

        effective_branch_id=effective_branch_id,

        effective_teacher_id=effective_teacher_id,

        # ====================================================
        # FILTER OPTIONS
        # ====================================================

        academic_years=academic_years,

        branches=branches,

        classes=classes,

        sections=sections,

        subjects=subjects,

        teachers=teachers,
        user=current_user
    )


# ============================================================
# ABSENT REPORTS
# FULL CORRECTED ROUTE
# PostgreSQL / Neon
#
# SORT:
#   Highest Absence Rate
#   ↓
#   Lowest Absence Rate
#
# PRINT:
#   /attendance/absent-reports?print=1
#
# ============================================================

@bp.route(
    "/attendance/absent-reports",
    methods=["GET"]
)
@login_required
def absent_reports():

    # ========================================================
    # SECURITY
    # ========================================================

    role = getattr(
        current_user,
        "role",
        None
    )

    allowed_roles = {
        "superadmin",
        "school_admin",
        "branch_admin",
        "teacher",
    }

    if role not in allowed_roles:
        abort(403)

    # ========================================================
    # CURRENT TEACHER
    # ========================================================

    teacher = None

    if role == "teacher":

        teacher = getattr(
            g,
            "teacher",
            None
        )

        if not teacher:
            abort(403)

    # ========================================================
    # INSTITUTION SCOPE
    # ========================================================

    if role == "teacher":

        institution_id = getattr(
            teacher,
            "institution_id",
            None
        )

    else:

        institution_id = getattr(
            current_user,
            "institution_id",
            None
        )

    if not institution_id:
        abort(403)

    # ========================================================
    # PRINT MODE
    # ========================================================

    print_mode = (
        request.args.get(
            "print",
            "",
            type=str
        ).lower()
        in {
            "1",
            "true",
            "yes",
        }
    )

    # ========================================================
    # FILTERS
    # ========================================================

    search = request.args.get(
        "search",
        "",
        type=str
    ).strip()

    academic_year_id = request.args.get(
        "academic_year_id",
        "",
        type=str
    ).strip()

    branch_id = request.args.get(
        "branch_id",
        "",
        type=str
    ).strip()

    teacher_id = request.args.get(
        "teacher_id",
        "",
        type=str
    ).strip()

    class_id = request.args.get(
        "class_id",
        "",
        type=str
    ).strip()

    section_id = request.args.get(
        "section_id",
        "",
        type=str
    ).strip()

    subject_id = request.args.get(
        "subject_id",
        "",
        type=str
    ).strip()

    date_from = request.args.get(
        "date_from",
        "",
        type=str
    ).strip()

    date_to = request.args.get(
        "date_to",
        "",
        type=str
    ).strip()

    # ========================================================
    # PER PAGE
    # ========================================================

    per_page = request.args.get(
        "per_page",
        25,
        type=int
    )

    allowed_per_page = {
        10,
        25,
        50,
        100,
    }

    if per_page not in allowed_per_page:
        per_page = 25

    # ========================================================
    # PAGE
    # ========================================================

    page = request.args.get(
        "page",
        1,
        type=int
    )

    if page < 1:
        page = 1

    # ========================================================
    # DATE PARSING
    # ========================================================

    parsed_date_from = None
    parsed_date_to = None

    if date_from:

        try:

            parsed_date_from = (
                datetime.strptime(
                    date_from,
                    "%Y-%m-%d"
                ).date()
            )

        except (
            ValueError,
            TypeError
        ):

            date_from = ""
            parsed_date_from = None

    if date_to:

        try:

            parsed_date_to = (
                datetime.strptime(
                    date_to,
                    "%Y-%m-%d"
                ).date()
            )

        except (
            ValueError,
            TypeError
        ):

            date_to = ""
            parsed_date_to = None

    # ========================================================
    # FIX REVERSED DATES
    # ========================================================

    if (
        parsed_date_from
        and parsed_date_to
        and parsed_date_from
        > parsed_date_to
    ):

        parsed_date_from, parsed_date_to = (
            parsed_date_to,
            parsed_date_from
        )

        date_from = (
            parsed_date_from.strftime(
                "%Y-%m-%d"
            )
        )

        date_to = (
            parsed_date_to.strftime(
                "%Y-%m-%d"
            )
        )

    # ========================================================
    # BASE ATTENDANCE QUERY
    # ========================================================
    #
    # IMPORTANT:
    #
    # This query contains ALL matching attendance records.
    #
    # It is NOT absent-only.
    #
    # This is required to calculate the student's
    # real absence rate.
    #
    # ========================================================

    attendance_query = (
        db.session.query(
            AttendanceRecord
        )
        .join(
            AttendanceSession,
            AttendanceRecord.attendance_session_id
            == AttendanceSession.id
        )
        .filter(
            AttendanceSession.institution_id
            == institution_id
        )
    )

    # ========================================================
    # TEACHER SECURITY
    # ========================================================

    if role == "teacher":

        attendance_query = (
            attendance_query
            .filter(
                AttendanceSession.teacher_id
                == teacher.id
            )
        )

        if teacher.branch_id:

            attendance_query = (
                attendance_query
                .filter(
                    AttendanceSession.branch_id
                    == teacher.branch_id
                )
            )

    # ========================================================
    # BRANCH ADMIN SECURITY
    # ========================================================

    elif role == "branch_admin":

        current_branch_id = getattr(
            current_user,
            "branch_id",
            None
        )

        if current_branch_id:

            attendance_query = (
                attendance_query
                .filter(
                    AttendanceSession.branch_id
                    == current_branch_id
                )
            )

    # ========================================================
    # ACADEMIC YEAR
    # ========================================================

    if academic_year_id:

        try:

            academic_year_value = int(
                academic_year_id
            )

            attendance_query = (
                attendance_query
                .filter(
                    AttendanceSession.academic_year_id
                    == academic_year_value
                )
            )

        except (
            ValueError,
            TypeError
        ):

            academic_year_id = ""

    # ========================================================
    # BRANCH FILTER
    # ========================================================

    if branch_id:

        try:

            requested_branch_id = int(
                branch_id
            )

            # ------------------------------------------------
            # TEACHER CANNOT ESCAPE OWN BRANCH
            # ------------------------------------------------

            if role == "teacher":

                if (
                    teacher.branch_id
                    and requested_branch_id
                    != teacher.branch_id
                ):
                    abort(403)

            # ------------------------------------------------
            # BRANCH ADMIN CANNOT ESCAPE OWN BRANCH
            # ------------------------------------------------

            if role == "branch_admin":

                current_branch_id = getattr(
                    current_user,
                    "branch_id",
                    None
                )

                if (
                    current_branch_id
                    and requested_branch_id
                    != current_branch_id
                ):
                    abort(403)

            attendance_query = (
                attendance_query
                .filter(
                    AttendanceSession.branch_id
                    == requested_branch_id
                )
            )

        except (
            ValueError,
            TypeError
        ):

            branch_id = ""

    # ========================================================
    # TEACHER FILTER
    # ========================================================

    if teacher_id:

        try:

            requested_teacher_id = int(
                teacher_id
            )

            # ------------------------------------------------
            # TEACHER CAN ONLY SELECT HIMSELF
            # ------------------------------------------------

            if role == "teacher":

                if (
                    requested_teacher_id
                    != teacher.id
                ):
                    abort(403)

            attendance_query = (
                attendance_query
                .filter(
                    AttendanceSession.teacher_id
                    == requested_teacher_id
                )
            )

        except (
            ValueError,
            TypeError
        ):

            teacher_id = ""

    # ========================================================
    # CLASS FILTER
    # ========================================================

    if class_id:

        try:

            attendance_query = (
                attendance_query
                .filter(
                    AttendanceSession.class_id
                    == int(class_id)
                )
            )

        except (
            ValueError,
            TypeError
        ):

            class_id = ""

    # ========================================================
    # SECTION FILTER
    # ========================================================

    if section_id:

        try:

            attendance_query = (
                attendance_query
                .filter(
                    AttendanceSession.section_id
                    == int(section_id)
                )
            )

        except (
            ValueError,
            TypeError
        ):

            section_id = ""

    # ========================================================
    # SUBJECT FILTER
    # ========================================================

    if subject_id:

        try:

            attendance_query = (
                attendance_query
                .filter(
                    AttendanceSession.subject_id
                    == int(subject_id)
                )
            )

        except (
            ValueError,
            TypeError
        ):

            subject_id = ""

    # ========================================================
    # DATE FROM
    # ========================================================

    if parsed_date_from:

        attendance_query = (
            attendance_query
            .filter(
                AttendanceSession.attendance_date
                >= parsed_date_from
            )
        )

    # ========================================================
    # DATE TO
    # ========================================================

    if parsed_date_to:

        attendance_query = (
            attendance_query
            .filter(
                AttendanceSession.attendance_date
                <= parsed_date_to
            )
        )

    # ========================================================
    # SEARCH
    # ========================================================
    #
    # Student:
    #   admission_no
    #   roll_no
    #   name
    #
    # ========================================================

    if search:

        search_pattern = (
            f"%{search}%"
        )

        attendance_query = (
            attendance_query
            .join(
                Student,
                AttendanceRecord.student_id
                == Student.id
            )
            .filter(
                or_(
                    Student.admission_no.ilike(
                        search_pattern
                    ),

                    Student.roll_no.ilike(
                        search_pattern
                    ),

                    Student.name.ilike(
                        search_pattern
                    )
                )
            )
        )

    # ========================================================
    # ABSENT CONDITION
    # ========================================================

    absent_condition = (
        func.lower(
            func.trim(
                AttendanceRecord.status
            )
        ) == "absent"
    )

    # ========================================================
    # TOTAL ATTENDANCE
    # ========================================================

    total_attendance = (
        attendance_query
        .with_entities(
            func.count(
                AttendanceRecord.id
            )
        )
        .scalar()
        or 0
    )

    # ========================================================
    # TOTAL ABSENT
    # ========================================================

    total_absent = (
        attendance_query
        .filter(
            absent_condition
        )
        .with_entities(
            func.count(
                AttendanceRecord.id
            )
        )
        .scalar()
        or 0
    )

    # ========================================================
    # TOTAL ABSENT STUDENTS
    # ========================================================

    total_absent_students = (
        attendance_query
        .filter(
            absent_condition
        )
        .with_entities(
            func.count(
                func.distinct(
                    AttendanceRecord.student_id
                )
            )
        )
        .scalar()
        or 0
    )

    # ========================================================
    # TOTAL ABSENT DAYS
    # ========================================================
    #
    # Same student absent in multiple subjects
    # on same date = ONE absent day.
    #
    # ========================================================

    absent_day_rows = (
        attendance_query
        .filter(
            absent_condition
        )
        .with_entities(
            AttendanceRecord.student_id,
            AttendanceSession.attendance_date
        )
        .distinct()
        .all()
    )

    total_absent_days = len(
        absent_day_rows
    )

    # ========================================================
    # OVERALL ABSENCE RATE
    # ========================================================

    if total_attendance > 0:

        overall_absence_rate = (
            total_absent
            / total_attendance
        ) * 100

    else:

        overall_absence_rate = 0.0

    # ========================================================
    # STUDENT STATISTICS
    # ========================================================
    #
    # Each student:
    #
    # total_attendance
    # absent_count
    # absence_rate
    #
    # ========================================================

    student_stats_query = (
        attendance_query
        .with_entities(

            AttendanceRecord.student_id.label(
                "student_id"
            ),

            func.count(
                AttendanceRecord.id
            ).label(
                "student_total_attendance"
            ),

            func.sum(
                case(
                    (
                        absent_condition,
                        1
                    ),
                    else_=0
                )
            ).label(
                "student_absent_count"
            )
        )
        .group_by(
            AttendanceRecord.student_id
        )
    )

    student_stats = {}

    for row in student_stats_query.all():

        student_total = int(
            row.student_total_attendance
            or 0
        )

        student_absent = int(
            row.student_absent_count
            or 0
        )

        if student_total > 0:

            student_rate = (
                student_absent
                / student_total
            ) * 100

        else:

            student_rate = 0.0

        student_stats[
            row.student_id
        ] = {
            "total_attendance":
                student_total,

            "absent_count":
                student_absent,

            "absence_rate":
                student_rate,
        }

    # ========================================================
    # ABSENT ONLY QUERY
    # ========================================================

    absent_query = (
        attendance_query
        .filter(
            absent_condition
        )
    )

    # ========================================================
    # LOAD ABSENT RECORDS
    # ========================================================

    absent_records = (
        absent_query
        .options(

            # ------------------------------------------------
            # STUDENT
            # ------------------------------------------------

            joinedload(
                AttendanceRecord.student
            ),

            # ------------------------------------------------
            # SESSION
            # ------------------------------------------------

            joinedload(
                AttendanceRecord.session
            ).joinedload(
                AttendanceSession.class_
            ),

            joinedload(
                AttendanceRecord.session
            ).joinedload(
                AttendanceSession.section
            ),

            joinedload(
                AttendanceRecord.session
            ).joinedload(
                AttendanceSession.subject
            ),

            joinedload(
                AttendanceRecord.session
            ).joinedload(
                AttendanceSession.teacher
            ),

            # ------------------------------------------------
            # MARKED BY TEACHER
            # ------------------------------------------------

            joinedload(
                AttendanceRecord.marked_by_teacher
            )
        )
        .all()
    )

    # ========================================================
    # ATTACH STATISTICS
    # ========================================================

    for record in absent_records:

        stats = student_stats.get(
            record.student_id,
            {
                "total_attendance": 0,
                "absent_count": 0,
                "absence_rate": 0.0,
            }
        )

        record.total_attendance = int(
            stats[
                "total_attendance"
            ]
        )

        record.absent_count = int(
            stats[
                "absent_count"
            ]
        )

        record.absence_rate = float(
            stats[
                "absence_rate"
            ]
        )

    # ========================================================
    # SORT
    # ========================================================
    #
    # HIGHEST ABSENCE RATE
    #          ↓
    # LOWEST ABSENCE RATE
    #
    # 1. Rate DESC
    # 2. Absent count DESC
    # 3. Date DESC
    # 4. Record ID DESC
    #
    # ========================================================

    def absent_sort_key(
        record
    ):

        rate = float(
            getattr(
                record,
                "absence_rate",
                0
            )
            or 0
        )

        absent_count = int(
            getattr(
                record,
                "absent_count",
                0
            )
            or 0
        )

        session = getattr(
            record,
            "session",
            None
        )

        attendance_date = getattr(
            session,
            "attendance_date",
            None
        )

        if not attendance_date:

            attendance_date = date.min

        record_id = int(
            getattr(
                record,
                "id",
                0
            )
            or 0
        )

        return (
            rate,
            absent_count,
            attendance_date,
            record_id,
        )

    absent_records.sort(
        key=absent_sort_key,
        reverse=True
    )

    # ========================================================
    # TOTAL REPORT RECORDS
    # ========================================================

    total_records = len(
        absent_records
    )

    # ========================================================
    # PRINT MODE
    # ========================================================
    #
    # Print page shows ALL filtered records.
    #
    # It does NOT paginate.
    #
    # ========================================================

    if print_mode:

        print_records = (
            absent_records
        )

    else:

        print_records = (
            absent_records
        )

    # ========================================================
    # PAGINATION
    # ========================================================

    total_pages = (
        math.ceil(
            total_records
            / per_page
        )
        if total_records
        else 1
    )

    if page > total_pages:

        page = total_pages

    # ========================================================
    # CURRENT PAGE
    # ========================================================

    if print_mode:

        paginated_records = (
            print_records
        )

    else:

        start_index = (
            (page - 1)
            * per_page
        )

        end_index = (
            start_index
            + per_page
        )

        paginated_records = (
            absent_records[
                start_index:end_index
            ]
        )

    # ========================================================
    # PAGINATION CLASS
    # ========================================================

    class ManualPagination:

        def __init__(
            self,
            items,
            page,
            per_page,
            total
        ):

            self.items = items

            self.page = page

            self.per_page = per_page

            self.total = total

            self.pages = (
                math.ceil(
                    total
                    / per_page
                )
                if total
                else 1
            )

        @property
        def has_prev(self):

            return (
                self.page > 1
            )

        @property
        def has_next(self):

            return (
                self.page
                < self.pages
            )

        @property
        def prev_num(self):

            if self.has_prev:

                return (
                    self.page - 1
                )

            return None

        @property
        def next_num(self):

            if self.has_next:

                return (
                    self.page + 1
                )

            return None

        def iter_pages(
            self,
            left_edge=2,
            left_current=2,
            right_current=3,
            right_edge=2
        ):

            last = 0

            for number in range(
                1,
                self.pages + 1
            ):

                if (
                    number
                    <= left_edge

                    or

                    (
                        number
                        >=
                        self.page
                        - left_current

                        and

                        number
                        <=
                        self.page
                        + right_current
                    )

                    or

                    number
                    >
                    self.pages
                    - right_edge
                ):

                    if (
                        last + 1
                        != number
                    ):

                        yield None

                    yield number

                    last = number

    # ========================================================
    # PAGINATION INSTANCE
    # ========================================================

    pagination = ManualPagination(
        paginated_records,
        page,
        per_page,
        total_records
    )

    # ========================================================
    # ACADEMIC YEARS
    # ========================================================

    academic_years = (
        AcademicYear.query
        .filter(
            AcademicYear.institution_id
            == institution_id
        )
        .order_by(
            AcademicYear.id.desc()
        )
        .all()
    )

    # ========================================================
    # BRANCHES
    # ========================================================

    branches_query = (
        Branch.query
        .filter(
            Branch.institution_id
            == institution_id
        )
    )

    if role == "teacher":

        if teacher.branch_id:

            branches_query = (
                branches_query
                .filter(
                    Branch.id
                    == teacher.branch_id
                )
            )

    elif role == "branch_admin":

        current_branch_id = getattr(
            current_user,
            "branch_id",
            None
        )

        if current_branch_id:

            branches_query = (
                branches_query
                .filter(
                    Branch.id
                    == current_branch_id
                )
            )

    branches = (
        branches_query
        .order_by(
            Branch.name.asc()
        )
        .all()
    )

    # ========================================================
    # TEACHERS
    # ========================================================
    #
    # IMPORTANT:
    #
    # Teacher model has:
    #   full_name
    #
    # NOT:
    #   name
    #
    # ========================================================

    teachers_query = (
        Teacher.query
        .filter(
            Teacher.institution_id
            == institution_id
        )
    )

    if role == "teacher":

        teachers_query = (
            teachers_query
            .filter(
                Teacher.id
                == teacher.id
            )
        )

    elif role == "branch_admin":

        current_branch_id = getattr(
            current_user,
            "branch_id",
            None
        )

        if current_branch_id:

            teachers_query = (
                teachers_query
                .filter(
                    Teacher.branch_id
                    == current_branch_id
                )
            )

    teachers = (
        teachers_query
        .order_by(
            Teacher.full_name.asc()
        )
        .all()
    )

    # ========================================================
    # CLASSES
    # ========================================================

    classes_query = (
        Class.query
        .filter(
            Class.institution_id
            == institution_id
        )
    )

    if role == "teacher":

        if teacher.branch_id:

            classes_query = (
                classes_query
                .filter(
                    Class.branch_id
                    == teacher.branch_id
                )
            )

    elif role == "branch_admin":

        current_branch_id = getattr(
            current_user,
            "branch_id",
            None
        )

        if current_branch_id:

            classes_query = (
                classes_query
                .filter(
                    Class.branch_id
                    == current_branch_id
                )
            )

    classes = (
        classes_query
        .order_by(
            Class.name.asc()
        )
        .all()
    )

    # ========================================================
    # SECTIONS
    # ========================================================

    sections_query = (
        Section.query
        .filter(
            Section.institution_id
            == institution_id
        )
    )

    if role == "teacher":

        if teacher.branch_id:

            sections_query = (
                sections_query
                .filter(
                    Section.branch_id
                    == teacher.branch_id
                )
            )

    elif role == "branch_admin":

        current_branch_id = getattr(
            current_user,
            "branch_id",
            None
        )

        if current_branch_id:

            sections_query = (
                sections_query
                .filter(
                    Section.branch_id
                    == current_branch_id
                )
            )

    sections = (
        sections_query
        .order_by(
            Section.name.asc()
        )
        .all()
    )

    # ========================================================
    # SUBJECTS
    # ========================================================

    subjects_query = (
        Subject.query
        .filter(
            Subject.institution_id
            == institution_id
        )
    )

    # --------------------------------------------------------
    # TEACHER SUBJECT SECURITY
    # --------------------------------------------------------

    if role == "teacher":

        subjects_query = (
            subjects_query
            .join(
                TeacherSubject,
                TeacherSubject.subject_id
                == Subject.id
            )
            .filter(
                TeacherSubject.teacher_id
                == teacher.id
            )
        )

    # --------------------------------------------------------
    # BRANCH ADMIN SUBJECT SECURITY
    # --------------------------------------------------------

    elif role == "branch_admin":

        current_branch_id = getattr(
            current_user,
            "branch_id",
            None
        )

        if current_branch_id:

            subjects_query = (
                subjects_query
                .filter(
                    or_(
                        Subject.branch_id
                        == current_branch_id,

                        Subject.branch_id.is_(None)
                    )
                )
            )

    subjects = (
        subjects_query
        .distinct()
        .order_by(
            Subject.name.asc()
        )
        .all()
    )

    # ========================================================
    # ACTIVE FILTER COUNT
    # ========================================================

    active_filters = sum(
        1
        for value in (
            search,
            academic_year_id,
            branch_id,
            teacher_id,
            class_id,
            section_id,
            subject_id,
            date_from,
            date_to,
        )
        if value
    )

    # ========================================================
    # FILTER SUMMARY
    # ========================================================

    filter_summary = {
        "search": search,
        "academic_year_id": academic_year_id,
        "branch_id": branch_id,
        "teacher_id": teacher_id,
        "class_id": class_id,
        "section_id": section_id,
        "subject_id": subject_id,
        "date_from": date_from,
        "date_to": date_to,
    }

    # ========================================================
    # RENDER
    # ========================================================

    return render_template(

        "backend/pages/attendance/absent_reports.html",

        # ====================================================
        # REPORT
        # ====================================================

        absent_reports=paginated_records,

        pagination=pagination,

        # ====================================================
        # FILTERS
        # ====================================================

        search=search,

        academic_year_id=academic_year_id,

        branch_id=branch_id,

        teacher_id=teacher_id,

        class_id=class_id,

        section_id=section_id,

        subject_id=subject_id,

        date_from=date_from,

        date_to=date_to,

        per_page=per_page,

        page=page,

        # ====================================================
        # DROPDOWNS
        # ====================================================

        academic_years=academic_years,

        branches=branches,

        teachers=teachers,

        classes=classes,

        sections=sections,

        subjects=subjects,

        # ====================================================
        # STATISTICS
        # ====================================================

        total_absent=total_absent,

        total_absent_students=(
            total_absent_students
        ),

        total_absent_days=(
            total_absent_days
        ),

        total_attendance=(
            total_attendance
        ),

        overall_absence_rate=(
            overall_absence_rate
        ),

        total_records=total_records,

        # ====================================================
        # FILTER INFORMATION
        # ====================================================

        active_filters=active_filters,

        filter_summary=filter_summary,

        # ====================================================
        # SORT
        # ====================================================

        sort_by="absence_rate",

        sort_direction="desc",

        sort_label=(
            "Highest Absence Rate"
        ),

        # ====================================================
        # PRINT
        # ====================================================

        print_mode=print_mode,
        user=current_user

    )


@bp.route(
    "/attendance/absent-reports/print",
    methods=["GET"]
)
@login_required
def print_absent_reports():

    # ==========================================================
    # SECURITY / ROLE
    # ==========================================================

    role = getattr(current_user, "role", None)

    allowed_roles = {
        "superadmin",
        "school_admin",
        "branch_admin",
        "teacher",
    }

    if role not in allowed_roles:
        abort(403)

    # ==========================================================
    # CURRENT TEACHER
    # ==========================================================

    teacher = None

    if role == "teacher":

        teacher = getattr(g, "teacher", None)

        if not teacher:
            abort(403)

    # ==========================================================
    # INSTITUTION
    # ==========================================================

    if role == "teacher":

        institution_id = getattr(
            teacher,
            "institution_id",
            None
        )

    else:

        institution_id = getattr(
            current_user,
            "institution_id",
            None
        )

    if not institution_id:
        abort(403)

    # ==========================================================
    # FILTERS
    # ==========================================================

    search = request.args.get(
        "search",
        "",
        type=str
    ).strip()

    academic_year_id = request.args.get(
        "academic_year_id",
        "",
        type=str
    ).strip()

    branch_id = request.args.get(
        "branch_id",
        "",
        type=str
    ).strip()

    teacher_id = request.args.get(
        "teacher_id",
        "",
        type=str
    ).strip()

    class_id = request.args.get(
        "class_id",
        "",
        type=str
    ).strip()

    section_id = request.args.get(
        "section_id",
        "",
        type=str
    ).strip()

    subject_id = request.args.get(
        "subject_id",
        "",
        type=str
    ).strip()

    date_from = request.args.get(
        "date_from",
        "",
        type=str
    ).strip()

    date_to = request.args.get(
        "date_to",
        "",
        type=str
    ).strip()

    # ==========================================================
    # DATE PARSING
    # ==========================================================

    parsed_date_from = None
    parsed_date_to = None

    if date_from:

        try:

            parsed_date_from = datetime.strptime(
                date_from,
                "%Y-%m-%d"
            ).date()

        except (ValueError, TypeError):

            date_from = ""
            parsed_date_from = None

    if date_to:

        try:

            parsed_date_to = datetime.strptime(
                date_to,
                "%Y-%m-%d"
            ).date()

        except (ValueError, TypeError):

            date_to = ""
            parsed_date_to = None

    # ==========================================================
    # SWAP INVALID DATE RANGE
    # ==========================================================

    if (
        parsed_date_from
        and parsed_date_to
        and parsed_date_from > parsed_date_to
    ):

        parsed_date_from, parsed_date_to = (
            parsed_date_to,
            parsed_date_from
        )

        date_from = parsed_date_from.strftime(
            "%Y-%m-%d"
        )

        date_to = parsed_date_to.strftime(
            "%Y-%m-%d"
        )

    # ==========================================================
    # BASE ATTENDANCE QUERY
    # ==========================================================

    attendance_query = (
        db.session.query(AttendanceRecord)
        .join(
            AttendanceSession,
            AttendanceRecord.attendance_session_id
            == AttendanceSession.id
        )
        .filter(
            AttendanceSession.institution_id
            == institution_id
        )
    )

    # ==========================================================
    # TEACHER SCOPE
    # ==========================================================

    teacher_branch_id = None
    current_teacher_id = None

    if role == "teacher":

        current_teacher_id = getattr(
            teacher,
            "id",
            None
        )

        teacher_branch_id = getattr(
            teacher,
            "branch_id",
            None
        )

        if current_teacher_id:

            attendance_query = attendance_query.filter(
                AttendanceSession.teacher_id
                == current_teacher_id
            )

        if teacher_branch_id:

            attendance_query = attendance_query.filter(
                AttendanceSession.branch_id
                == teacher_branch_id
            )

    # ==========================================================
    # BRANCH ADMIN SCOPE
    # ==========================================================

    current_branch_id = None

    if role == "branch_admin":

        current_branch_id = getattr(
            current_user,
            "branch_id",
            None
        )

        if current_branch_id:

            attendance_query = attendance_query.filter(
                AttendanceSession.branch_id
                == current_branch_id
            )

    # ==========================================================
    # ACADEMIC YEAR FILTER
    # ==========================================================

    academic_year_value = None

    if academic_year_id:

        try:

            academic_year_value = int(
                academic_year_id
            )

            attendance_query = attendance_query.filter(
                AttendanceSession.academic_year_id
                == academic_year_value
            )

        except (ValueError, TypeError):

            academic_year_id = ""
            academic_year_value = None

    # ==========================================================
    # BRANCH FILTER
    # ==========================================================

    branch_value = None

    if branch_id:

        try:

            branch_value = int(
                branch_id
            )

            # ----------------------------------------------
            # TEACHER SECURITY
            # ----------------------------------------------

            if role == "teacher":

                if (
                    teacher_branch_id
                    and branch_value
                    != teacher_branch_id
                ):

                    abort(403)

            # ----------------------------------------------
            # BRANCH ADMIN SECURITY
            # ----------------------------------------------

            if role == "branch_admin":

                if (
                    current_branch_id
                    and branch_value
                    != current_branch_id
                ):

                    abort(403)

            attendance_query = attendance_query.filter(
                AttendanceSession.branch_id
                == branch_value
            )

        except (ValueError, TypeError):

            branch_id = ""
            branch_value = None

    # ==========================================================
    # TEACHER FILTER
    # ==========================================================

    teacher_value = None

    if teacher_id:

        try:

            teacher_value = int(
                teacher_id
            )

            # ----------------------------------------------
            # TEACHER CAN ONLY PRINT OWN RECORDS
            # ----------------------------------------------

            if role == "teacher":

                if (
                    current_teacher_id
                    and teacher_value
                    != current_teacher_id
                ):

                    abort(403)

            attendance_query = attendance_query.filter(
                AttendanceSession.teacher_id
                == teacher_value
            )

        except (ValueError, TypeError):

            teacher_id = ""
            teacher_value = None

    # ==========================================================
    # CLASS FILTER
    # ==========================================================

    class_value = None

    if class_id:

        try:

            class_value = int(
                class_id
            )

            attendance_query = attendance_query.filter(
                AttendanceSession.class_id
                == class_value
            )

        except (ValueError, TypeError):

            class_id = ""
            class_value = None

    # ==========================================================
    # SECTION FILTER
    # ==========================================================

    section_value = None

    if section_id:

        try:

            section_value = int(
                section_id
            )

            attendance_query = attendance_query.filter(
                AttendanceSession.section_id
                == section_value
            )

        except (ValueError, TypeError):

            section_id = ""
            section_value = None

    # ==========================================================
    # SUBJECT FILTER
    # ==========================================================

    subject_value = None

    if subject_id:

        try:

            subject_value = int(
                subject_id
            )

            attendance_query = attendance_query.filter(
                AttendanceSession.subject_id
                == subject_value
            )

        except (ValueError, TypeError):

            subject_id = ""
            subject_value = None

    # ==========================================================
    # DATE FILTER
    # ==========================================================

    if parsed_date_from:

        attendance_query = attendance_query.filter(
            AttendanceSession.attendance_date
            >= parsed_date_from
        )

    if parsed_date_to:

        attendance_query = attendance_query.filter(
            AttendanceSession.attendance_date
            <= parsed_date_to
        )

    # ==========================================================
    # STUDENT SEARCH
    # ==========================================================

    if search:

        search_pattern = f"%{search}%"

        attendance_query = (
            attendance_query
            .join(
                Student,
                AttendanceRecord.student_id
                == Student.id
            )
            .filter(
                or_(
                    Student.admission_no.ilike(
                        search_pattern
                    ),
                    Student.roll_no.ilike(
                        search_pattern
                    ),
                    Student.name.ilike(
                        search_pattern
                    )
                )
            )
        )

    # ==========================================================
    # ABSENT CONDITION
    # ==========================================================

    absent_condition = (
        func.lower(
            func.trim(
                AttendanceRecord.status
            )
        ) == "absent"
    )

    # ==========================================================
    # TOTAL ATTENDANCE
    # ==========================================================

    total_attendance = (
        attendance_query
        .with_entities(
            func.count(
                AttendanceRecord.id
            )
        )
        .scalar()
        or 0
    )

    # ==========================================================
    # TOTAL ABSENT
    # ==========================================================

    total_absent = (
        attendance_query
        .filter(absent_condition)
        .with_entities(
            func.count(
                AttendanceRecord.id
            )
        )
        .scalar()
        or 0
    )

    # ==========================================================
    # UNIQUE ABSENT STUDENTS
    # ==========================================================

    total_absent_students = (
        attendance_query
        .filter(absent_condition)
        .with_entities(
            func.count(
                func.distinct(
                    AttendanceRecord.student_id
                )
            )
        )
        .scalar()
        or 0
    )

    # ==========================================================
    # ABSENT DAYS
    # ==========================================================

    absent_day_rows = (
        attendance_query
        .filter(absent_condition)
        .with_entities(
            AttendanceRecord.student_id,
            AttendanceSession.attendance_date
        )
        .distinct()
        .all()
    )

    total_absent_days = len(
        absent_day_rows
    )

    # ==========================================================
    # OVERALL ABSENCE RATE
    # ==========================================================

    overall_absence_rate = (
        (
            total_absent
            / total_attendance
        ) * 100
        if total_attendance
        else 0.0
    )

    # ==========================================================
    # STUDENT STATISTICS
    # ==========================================================

    student_stats_query = (
        attendance_query
        .with_entities(
            AttendanceRecord.student_id.label(
                "student_id"
            ),

            func.count(
                AttendanceRecord.id
            ).label(
                "student_total_attendance"
            ),

            func.sum(
                case(
                    (
                        absent_condition,
                        1
                    ),
                    else_=0
                )
            ).label(
                "student_absent_count"
            )
        )
        .group_by(
            AttendanceRecord.student_id
        )
    )

    student_stats = {}

    for row in student_stats_query.all():

        student_total = int(
            row.student_total_attendance
            or 0
        )

        student_absent = int(
            row.student_absent_count
            or 0
        )

        absence_rate = (
            (
                student_absent
                / student_total
            ) * 100
            if student_total
            else 0.0
        )

        student_stats[
            row.student_id
        ] = {

            "total_attendance":
                student_total,

            "absent_count":
                student_absent,

            "absence_rate":
                absence_rate,
        }

    # ==========================================================
    # ABSENT RECORDS
    # ==========================================================

    absent_records = (
        attendance_query
        .filter(absent_condition)
        .options(

            joinedload(
                AttendanceRecord.student
            ),

            joinedload(
                AttendanceRecord.session
            ).joinedload(
                AttendanceSession.class_
            ),

            joinedload(
                AttendanceRecord.session
            ).joinedload(
                AttendanceSession.section
            ),

            joinedload(
                AttendanceRecord.session
            ).joinedload(
                AttendanceSession.subject
            ),

            joinedload(
                AttendanceRecord.session
            ).joinedload(
                AttendanceSession.teacher
            ),

            joinedload(
                AttendanceRecord.marked_by_teacher
            )
        )
        .all()
    )

    # ==========================================================
    # ATTACH STUDENT STATISTICS
    # ==========================================================

    for record in absent_records:

        stats = student_stats.get(
            record.student_id,
            {
                "total_attendance": 0,
                "absent_count": 0,
                "absence_rate": 0.0,
            }
        )

        record.total_attendance = int(
            stats["total_attendance"]
        )

        record.absent_count = int(
            stats["absent_count"]
        )

        record.absence_rate = float(
            stats["absence_rate"]
        )

    # ==========================================================
    # SORT
    # ==========================================================

    def absent_sort_key(record):

        record_rate = float(
            getattr(
                record,
                "absence_rate",
                0
            )
            or 0
        )

        record_absent_count = int(
            getattr(
                record,
                "absent_count",
                0
            )
            or 0
        )

        session = getattr(
            record,
            "session",
            None
        )

        attendance_date = getattr(
            session,
            "attendance_date",
            None
        )

        if not attendance_date:

            attendance_date = date.min

        record_id = int(
            getattr(
                record,
                "id",
                0
            )
            or 0
        )

        return (
            record_rate,
            record_absent_count,
            attendance_date,
            record_id,
        )

    absent_records.sort(
        key=absent_sort_key,
        reverse=True
    )

    # ==========================================================
    # SELECTED BRANCH
    # ==========================================================

    selected_branch = None

    effective_branch_id = None

    if branch_value:

        effective_branch_id = branch_value

    elif role == "teacher":

        effective_branch_id = teacher_branch_id

    elif role == "branch_admin":

        effective_branch_id = current_branch_id

    if effective_branch_id:

        selected_branch = (
            Branch.query
            .filter(
                Branch.id
                == effective_branch_id,

                Branch.institution_id
                == institution_id
            )
            .first()
        )

    # ==========================================================
    # SELECTED ACADEMIC YEAR
    # ==========================================================

    selected_academic_year = None

    if academic_year_value:

        selected_academic_year = (
            AcademicYear.query
            .filter(
                AcademicYear.id
                == academic_year_value,

                AcademicYear.institution_id
                == institution_id
            )
            .first()
        )

    # ==========================================================
    # SELECTED TEACHER
    # ==========================================================

    selected_teacher = None

    if teacher_value:

        selected_teacher = (
            Teacher.query
            .filter(
                Teacher.id
                == teacher_value,

                Teacher.institution_id
                == institution_id
            )
            .first()
        )

    elif role == "teacher":

        selected_teacher = teacher

    # ==========================================================
    # SELECTED CLASS
    # ==========================================================

    selected_class = None

    if class_value:

        selected_class = (
            Class.query
            .filter(
                Class.id
                == class_value,

                Class.institution_id
                == institution_id
            )
            .first()
        )

    # ==========================================================
    # SELECTED SECTION
    # ==========================================================

    selected_section = None

    if section_value:

        selected_section = (
            Section.query
            .filter(
                Section.id
                == section_value,

                Section.institution_id
                == institution_id
            )
            .first()
        )

    # ==========================================================
    # SELECTED SUBJECT
    # ==========================================================

    selected_subject = None

    if subject_value:

        selected_subject = (
            Subject.query
            .filter(
                Subject.id
                == subject_value,

                Subject.institution_id
                == institution_id
            )
            .first()
        )

    # ==========================================================
    # SITE SETTINGS
    # ==========================================================
    #
    # Haddii SiteSettings uu yahay model-kaaga branding-ka.
    # Haddii aad site_settings global context hore u isticmaasho,
    # waxaad ka saari kartaa query-kan.
    #
    # ==========================================================

    site_settings = None

    try:

        site_settings = (
            SiteSettings.query
            .filter(
                SiteSettings.institution_id
                == institution_id
            )
            .first()
        )

    except NameError:

        # Haddii SiteSettings model uusan route-kan
        # scope-giisa ku jirin, template-ku fallback
        # ayuu isticmaali karaa.

        site_settings = None

    # ==========================================================
    # ACADEMIC YEAR DISPLAY NAME
    # ==========================================================

    academic_year_name = None

    if selected_academic_year:

        academic_year_name = (
            getattr(
                selected_academic_year,
                "name",
                None
            )
            or
            getattr(
                selected_academic_year,
                "year",
                None
            )
            or
            getattr(
                selected_academic_year,
                "title",
                None
            )
        )

    # ==========================================================
    # DISPLAY NAMES
    # ==========================================================

    teacher_name = None

    if selected_teacher:

        teacher_name = (
            getattr(
                selected_teacher,
                "full_name",
                None
            )
            or
            getattr(
                selected_teacher,
                "username",
                None
            )
        )

    class_name = None

    if selected_class:

        class_name = getattr(
            selected_class,
            "name",
            None
        )

    section_name = None

    if selected_section:

        section_name = getattr(
            selected_section,
            "name",
            None
        )

    subject_name = None

    if selected_subject:

        subject_name = getattr(
            selected_subject,
            "name",
            None
        )

    # ==========================================================
    # BRANCH DISPLAY
    # ==========================================================

    branch_name = None
    branch_code = None

    if selected_branch:

        branch_name = getattr(
            selected_branch,
            "name",
            None
        )

        branch_code = getattr(
            selected_branch,
            "code",
            None
        )

    # ==========================================================
    # REPORT FILTER COUNT
    # ==========================================================

    active_filters = 0

    for value in (
        search,
        academic_year_id,
        branch_id,
        teacher_id,
        class_id,
        section_id,
        subject_id,
        date_from,
        date_to,
    ):

        if value:

            active_filters += 1

    # ==========================================================
    # RENDER PRINT PAGE
    # ==========================================================

    return render_template(
        "backend/pages/attendance/print_absent_reports.html",

        # ------------------------------------------------------
        # RECORDS
        # ------------------------------------------------------

        absent_reports=absent_records,

        # ------------------------------------------------------
        # RAW FILTER VALUES
        # ------------------------------------------------------

        search=search,
        user=current_user,
        academic_year_id=academic_year_id,

        branch_id=branch_id,

        teacher_id=teacher_id,

        class_id=class_id,

        section_id=section_id,

        subject_id=subject_id,

        date_from=date_from,

        date_to=date_to,

        # ------------------------------------------------------
        # SELECTED OBJECTS
        # ------------------------------------------------------

        selected_academic_year=
            selected_academic_year,

        selected_branch=
            selected_branch,

        selected_teacher=
            selected_teacher,

        selected_class=
            selected_class,

        selected_section=
            selected_section,

        selected_subject=
            selected_subject,

        # ------------------------------------------------------
        # DISPLAY NAMES
        # ------------------------------------------------------

        academic_year_name=
            academic_year_name,

        branch_name=
            branch_name,

        branch_code=
            branch_code,

        teacher_name=
            teacher_name,

        class_name=
            class_name,

        section_name=
            section_name,

        subject_name=
            subject_name,

        # ------------------------------------------------------
        # SITE SETTINGS / BRANDING
        # ------------------------------------------------------

        site_settings=
            site_settings,

        # ------------------------------------------------------
        # STATISTICS
        # ------------------------------------------------------

        total_absent=
            total_absent,

        total_absent_students=
            total_absent_students,

        total_absent_days=
            total_absent_days,

        total_attendance=
            total_attendance,

        overall_absence_rate=
            overall_absence_rate,

        # ------------------------------------------------------
        # REPORT INFORMATION
        # ------------------------------------------------------

        active_filters=
            active_filters,

        generated_at=
            datetime.utcnow(),
    )

    


# ============================================================
# STUDENT FULL REPORT
# SEARCH STUDENT + ATTENDANCE + EXAMS + MARKS + RESULTS
# PostgreSQL / Neon
# ============================================================

@bp.route(
    "/student-report",
    methods=["GET"]
)
@login_required
def student_report():

    # ========================================================
    # HELPERS
    # ========================================================

    def first_value(obj, *names, default=None):
        """
        Safely return the first existing/non-empty attribute.
        """
        if obj is None:
            return default

        for name in names:
            try:
                value = getattr(obj, name, None)
            except Exception:
                value = None

            if value is not None and value != "":
                return value

        return default


    def object_name(obj, default="—"):
        """
        Safely get display name from any related object.
        """

        if obj is None:
            return default

        value = first_value(
            obj,
            "name",
            "full_name",
            "student_name",
            "title",
            "class_name",
            "section_name",
            "subject_name",
            "program_name",
            "academic_year_name",
            "term_name",
            "short_name",
            "code",
            default=None
        )

        if value is not None:
            return str(value)

        first_name = first_value(
            obj,
            "first_name",
            default=""
        )

        last_name = first_value(
            obj,
            "last_name",
            default=""
        )

        full = f"{first_name or ''} {last_name or ''}".strip()

        return full or default


    def normalize_id(value):
        """
        Convert query-string IDs safely.
        """
        if value in (None, "", "null", "None"):
            return None

        try:
            return int(value)
        except (TypeError, ValueError):
            return None


    def apply_optional_filter(query, model, field_name, value):
        """
        Apply a filter only if the model actually has the column.
        This prevents route crashes when an optional field is absent.
        """

        if value is None:
            return query

        column = getattr(model, field_name, None)

        if column is None:
            return query

        return query.filter(column == value)


    def normalize_status(value):
        if value is None:
            return ""

        return str(value).strip().lower()


    # ========================================================
    # CURRENT USER
    # ========================================================

    current_user = getattr(g, "user", None)

    if current_user is None:
        current_user = current_user if "current_user" in locals() else None

    # Flask-Login current_user fallback
    try:
        from flask_login import current_user as flask_current_user

        if current_user is None or not getattr(
            current_user,
            "is_authenticated",
            True
        ):
            current_user = flask_current_user

    except Exception:
        pass


    # ========================================================
    # ROLE
    # ========================================================

    user_role = str(
        first_value(
            current_user,
            "role",
            default=""
        ) or ""
    ).lower().strip()


    allowed_roles = {
        "superadmin",
        "school_admin",
        "institution_admin",
        "branch_admin",
        "teacher",
    }

    if user_role not in allowed_roles:
        abort(403)


    # ========================================================
    # CURRENT INSTITUTION / BRANCH
    # ========================================================

    user_institution_id = first_value(
        current_user,
        "institution_id",
        default=None
    )

    user_branch_id = first_value(
        current_user,
        "branch_id",
        default=None
    )


    # Teacher fallback
    teacher = getattr(g, "teacher", None)

    if user_role == "teacher" and teacher:

        if user_institution_id is None:
            user_institution_id = getattr(
                teacher,
                "institution_id",
                None
            )

        if user_branch_id is None:
            user_branch_id = getattr(
                teacher,
                "branch_id",
                None
            )


    # ========================================================
    # REQUEST FILTERS
    # ========================================================

    search = (
        request.args.get("search", "", type=str)
        .strip()
    )

    student_id = normalize_id(
        request.args.get("student_id")
    )

    academic_year_id = normalize_id(
        request.args.get("academic_year_id")
    )

    term_id = normalize_id(
        request.args.get("term_id")
    )


    # ========================================================
    # STUDENT QUERY
    #
    # IMPORTANT:
    # Do NOT load all students.
    # Only return limited search suggestions.
    # Suitable for very large databases.
    # ========================================================

    student_query = Student.query


    # ========================================================
    # ROLE SCOPING
    # ========================================================

    if user_role != "superadmin":

        if user_institution_id is not None:

            student_query = student_query.filter(
                Student.institution_id == user_institution_id
            )

        else:
            abort(403)


    # Branch admin / teacher
    if user_role in {
        "branch_admin",
        "teacher",
    }:

        if user_branch_id is not None:

            student_query = student_query.filter(
                Student.branch_id == user_branch_id
            )

        else:
            abort(403)


    # ========================================================
    # STUDENT SEARCH SUGGESTIONS
    # ========================================================

    student_results = []

    if search:

        search_pattern = f"%{search}%"

        search_conditions = []

        possible_student_fields = [
            "admission_no",
            "roll_no",
            "name",
            "full_name",
            "student_name",
            "first_name",
            "last_name",
        ]

        for field_name in possible_student_fields:

            column = getattr(
                Student,
                field_name,
                None
            )

            if column is not None:

                search_conditions.append(
                    column.ilike(search_pattern)
                )


        if search_conditions:

            student_results = (
                student_query
                .filter(or_(*search_conditions))
                .order_by(
                    getattr(
                        Student,
                        "name",
                        getattr(
                            Student,
                            "full_name",
                            Student.id
                        )
                    )
                )
                .limit(50)
                .all()
            )


    # ========================================================
    # LOAD EXACT STUDENT
    # ========================================================

    student = None

    if student_id:

        student = (
            student_query
            .filter(Student.id == student_id)
            .first()
        )

        if not student:
            abort(404)


    # ========================================================
    # IF SEARCH MATCHES EXACTLY ONE STUDENT
    #
    # We do NOT automatically select random first student.
    # If one exact match exists, select it.
    # ========================================================

    if student is None and search and student_results:

        normalized_search = search.lower().strip()

        exact_matches = []

        for item in student_results:

            candidate_values = [
                first_value(item, "admission_no"),
                first_value(item, "roll_no"),
                first_value(item, "name"),
                first_value(item, "full_name"),
                first_value(item, "student_name"),
            ]

            candidate_name = (
                f"{first_value(item, 'first_name', default='') or ''} "
                f"{first_value(item, 'last_name', default='') or ''}"
            ).strip()

            candidate_values.append(candidate_name)

            for candidate in candidate_values:

                if candidate is not None:

                    if str(candidate).strip().lower() == normalized_search:
                        exact_matches.append(item)
                        break


        if len(exact_matches) == 1:

            student = exact_matches[0]


    # ========================================================
    # DEFAULT EMPTY DATA
    # ========================================================

    institution = None
    branch = None

    enrollments = []
    current_enrollment = None
    enrollment_data = {
        "program": None,
        "academic_year": None,
        "class": None,
        "section": None,
    }

    attendance_rows = []
    attendance_total = 0

    attendance_summary = {
        "total": 0,
        "present": 0,
        "absent": 0,
        "late": 0,
        "excused": 0,
        "sick": 0,
        "leave": 0,
        "attendance_percentage": 0,
    }

    exam_mark_rows = []
    mark_total = 0

    student_results_exam = []

    result_summary = {
        "total_exams": 0,
        "passed": 0,
        "failed": 0,
        "incomplete": 0,
        "published": 0,
        "average_percentage": 0,
    }

    ranking_rows = []

    rank_summary = {
        "institution_position": None,
        "branch_position": None,
        "program_position": None,
        "class_position": None,
        "section_position": None,
    }


    # ========================================================
    # LOAD INSTITUTION / BRANCH
    # ========================================================

    if student:

        institution = getattr(
            student,
            "institution",
            None
        )

        branch = getattr(
            student,
            "branch",
            None
        )

        # ----------------------------------------------------
        # FALLBACK INSTITUTION
        # ----------------------------------------------------

        if institution is None:

            student_institution_id = getattr(
                student,
                "institution_id",
                None
            )

            if student_institution_id:

                institution = (
                    Institution.query
                    .filter(
                        Institution.id ==
                        student_institution_id
                    )
                    .first()
                )


        # ----------------------------------------------------
        # FALLBACK BRANCH
        # ----------------------------------------------------

        if branch is None:

            student_branch_id = getattr(
                student,
                "branch_id",
                None
            )

            if student_branch_id:

                branch = (
                    Branch.query
                    .filter(
                        Branch.id ==
                        student_branch_id
                    )
                    .first()
                )


        # ====================================================
        # ENROLLMENTS
        # ====================================================

        enrollment_query = (
            StudentEnrollment.query
            .filter(
                StudentEnrollment.student_id ==
                student.id
            )
        )


        # Institution safety
        if hasattr(
            StudentEnrollment,
            "institution_id"
        ):

            enrollment_query = enrollment_query.filter(
                StudentEnrollment.institution_id ==
                getattr(
                    student,
                    "institution_id",
                    user_institution_id
                )
            )


        # Branch safety
        if (
            user_role in {
                "branch_admin",
                "teacher",
            }
            and hasattr(
                StudentEnrollment,
                "branch_id"
            )
            and user_branch_id is not None
        ):

            enrollment_query = enrollment_query.filter(
                StudentEnrollment.branch_id ==
                user_branch_id
            )


        # Academic year filter
        enrollment_query = apply_optional_filter(
            enrollment_query,
            StudentEnrollment,
            "academic_year_id",
            academic_year_id
        )


        enrollments = (
            enrollment_query
            .order_by(
                StudentEnrollment.id.desc()
            )
            .all()
        )


        # ====================================================
        # CURRENT ENROLLMENT
        # ====================================================

        if enrollments:

            active_enrollment = None

            for enrollment in enrollments:

                status = normalize_status(
                    getattr(
                        enrollment,
                        "status",
                        ""
                    )
                )

                if status in {
                    "active",
                    "current",
                    "enrolled",
                }:

                    active_enrollment = enrollment
                    break


            current_enrollment = (
                active_enrollment
                or enrollments[0]
            )


        # ====================================================
        # ENROLLMENT DATA
        # ====================================================

        if current_enrollment:

            enrollment_data = {
                "program": getattr(
                    current_enrollment,
                    "program",
                    None
                ),

                "academic_year": getattr(
                    current_enrollment,
                    "academic_year",
                    None
                ),

                "class": getattr(
                    current_enrollment,
                    "class_",
                    getattr(
                        current_enrollment,
                        "classroom",
                        getattr(
                            current_enrollment,
                            "class",
                            None
                        )
                    )
                ),

                "section": getattr(
                    current_enrollment,
                    "section",
                    None
                ),
            }


        # ====================================================
        # ATTENDANCE
        # ====================================================

        try:

            attendance_query = (
                AttendanceRecord.query
                .join(
                    AttendanceRecord.session
                )
                .filter(
                    AttendanceRecord.student_id ==
                    student.id
                )
            )


            # Session institution
            attendance_session_model = (
                getattr(
                    AttendanceRecord,
                    "session",
                    None
                )
            )


            # Academic year
            if academic_year_id:

                session_rel = getattr(
                    AttendanceRecord,
                    "session",
                    None
                )

                if session_rel is not None:

                    try:

                        attendance_query = (
                            attendance_query
                            .filter(
                                AttendanceSession.academic_year_id
                                ==
                                academic_year_id
                            )
                        )

                    except Exception:
                        pass


            # Term
            if term_id:

                try:

                    attendance_query = (
                        attendance_query
                        .filter(
                            AttendanceSession.term_id ==
                            term_id
                        )
                    )

                except Exception:
                    pass


            # Institution
            try:

                attendance_query = (
                    attendance_query
                    .filter(
                        AttendanceSession.institution_id ==
                        getattr(
                            student,
                            "institution_id",
                            user_institution_id
                        )
                    )
                )

            except Exception:
                pass


            # Branch
            if (
                user_role in {
                    "branch_admin",
                    "teacher",
                }
                and user_branch_id is not None
            ):

                try:

                    attendance_query = (
                        attendance_query
                        .filter(
                            AttendanceSession.branch_id ==
                            user_branch_id
                        )
                    )

                except Exception:
                    pass


            attendance_records = (
                attendance_query
                .order_by(
                    AttendanceRecord.id.desc()
                )
                .all()
            )


            # ------------------------------------------------
            # BUILD ATTENDANCE ROWS
            # ------------------------------------------------

            for record in attendance_records:

                session = getattr(
                    record,
                    "session",
                    None
                )

                status = first_value(
                    record,
                    "status",
                    "attendance_status",
                    default=""
                )


                date_value = first_value(
                    record,
                    "attendance_date",
                    "date",
                    default=None
                )

                if date_value is None and session:

                    date_value = first_value(
                        session,
                        "attendance_date",
                        "date",
                        "session_date",
                        default=None
                    )


                row = {
                    "record": record,
                    "session": session,
                    "date": date_value,
                    "status": status,
                    "minutes_late": first_value(
                        record,
                        "minutes_late",
                        "late_minutes",
                        default=None
                    ),
                    "check_in": first_value(
                        record,
                        "check_in",
                        "check_in_time",
                        default=None
                    ),
                    "check_out": first_value(
                        record,
                        "check_out",
                        "check_out_time",
                        default=None
                    ),
                    "notes": first_value(
                        record,
                        "notes",
                        "note",
                        "remarks",
                        default=None
                    ),
                }

                attendance_rows.append(row)


            # ------------------------------------------------
            # ATTENDANCE SUMMARY
            # ------------------------------------------------

            attendance_total = len(
                attendance_rows
            )

            for row in attendance_rows:

                status = normalize_status(
                    row["status"]
                )

                if status in {
                    "present",
                    "p",
                }:

                    attendance_summary["present"] += 1

                elif status in {
                    "absent",
                    "a",
                }:

                    attendance_summary["absent"] += 1

                elif status in {
                    "late",
                    "l",
                }:

                    attendance_summary["late"] += 1

                elif status in {
                    "excused",
                    "e",
                }:

                    attendance_summary["excused"] += 1

                elif status in {
                    "sick",
                }:

                    attendance_summary["sick"] += 1

                elif status in {
                    "leave",
                }:

                    attendance_summary["leave"] += 1


            attendance_summary["total"] = (
                attendance_total
            )


            # Present + Late are treated as attended
            attended_count = (
                attendance_summary["present"]
                +
                attendance_summary["late"]
            )


            if attendance_total > 0:

                attendance_summary[
                    "attendance_percentage"
                ] = round(
                    (
                        attended_count /
                        attendance_total
                    ) * 100,
                    2
                )

            else:

                attendance_summary[
                    "attendance_percentage"
                ] = 0


        except Exception:

            # Do not allow attendance relationship
            # problems to destroy the complete report.
            attendance_rows = []
            attendance_total = 0


        # ====================================================
        # MARKS
        # ====================================================

        try:

            mark_query = (
                Mark.query
                .filter(
                    Mark.student_id ==
                    student.id
                )
            )


            # Institution
            if hasattr(
                Mark,
                "institution_id"
            ):

                mark_query = mark_query.filter(
                    Mark.institution_id ==
                    getattr(
                        student,
                        "institution_id",
                        user_institution_id
                    )
                )


            # Branch
            if (
                user_role in {
                    "branch_admin",
                    "teacher",
                }
                and user_branch_id is not None
                and hasattr(
                    Mark,
                    "branch_id"
                )
            ):

                mark_query = mark_query.filter(
                    Mark.branch_id ==
                    user_branch_id
                )


            # Academic year
            mark_query = apply_optional_filter(
                mark_query,
                Mark,
                "academic_year_id",
                academic_year_id
            )


            # Term
            mark_query = apply_optional_filter(
                mark_query,
                Mark,
                "term_id",
                term_id
            )


            marks = (
                mark_query
                .order_by(
                    Mark.id.desc()
                )
                .all()
            )


            # =================================================
            # BUILD MARK ROWS
            # =================================================

            for mark in marks:

                exam_subject = getattr(
                    mark,
                    "exam_subject",
                    None
                )


                exam = getattr(
                    mark,
                    "exam",
                    None
                )


                subject = getattr(
                    mark,
                    "subject",
                    None
                )


                # ---------------------------------------------
                # FALLBACK EXAM SUBJECT
                # ---------------------------------------------

                if exam_subject is None:

                    exam_subject_id = getattr(
                        mark,
                        "exam_subject_id",
                        None
                    )

                    if exam_subject_id:

                        try:

                            exam_subject = (
                                ExamSubject.query
                                .filter(
                                    ExamSubject.id ==
                                    exam_subject_id
                                )
                                .first()
                            )

                        except Exception:
                            exam_subject = None


                # ---------------------------------------------
                # FALLBACK EXAM
                # ---------------------------------------------

                if exam is None and exam_subject:

                    exam = getattr(
                        exam_subject,
                        "exam",
                        None
                    )


                # ---------------------------------------------
                # FALLBACK SUBJECT
                # ---------------------------------------------

                if subject is None and exam_subject:

                    subject = getattr(
                        exam_subject,
                        "subject",
                        None
                    )


                marks_obtained = first_value(
                    mark,
                    "marks_obtained",
                    "obtained_marks",
                    "score",
                    "marks",
                    "mark",
                    default=None
                )


                is_absent = bool(
                    first_value(
                        mark,
                        "is_absent",
                        "absent",
                        default=False
                    )
                )


                is_exempted = bool(
                    first_value(
                        mark,
                        "is_exempted",
                        "exempted",
                        default=False
                    )
                )


                exam_mark_rows.append({

                    "mark": mark,

                    "exam_subject": exam_subject,

                    "exam": exam,

                    "subject": subject,

                    "marks_obtained": marks_obtained,

                    "is_absent": is_absent,

                    "is_exempted": is_exempted,

                    "status": first_value(
                        mark,
                        "status",
                        "mark_status",
                        default=None
                    ),

                    "remarks": first_value(
                        mark,
                        "remarks",
                        "remark",
                        "notes",
                        "note",
                        default=None
                    ),
                })


            mark_total = len(
                exam_mark_rows
            )


        except Exception:

            exam_mark_rows = []
            mark_total = 0


        # ====================================================
        # STUDENT RESULTS
        # ====================================================

        try:

            result_query = (
                StudentResult.query
                .filter(
                    StudentResult.student_id ==
                    student.id
                )
            )


            # Institution
            if hasattr(
                StudentResult,
                "institution_id"
            ):

                result_query = result_query.filter(
                    StudentResult.institution_id ==
                    getattr(
                        student,
                        "institution_id",
                        user_institution_id
                    )
                )


            # Branch
            if (
                user_role in {
                    "branch_admin",
                    "teacher",
                }
                and user_branch_id is not None
                and hasattr(
                    StudentResult,
                    "branch_id"
                )
            ):

                result_query = result_query.filter(
                    StudentResult.branch_id ==
                    user_branch_id
                )


            # Academic Year
            result_query = apply_optional_filter(
                result_query,
                StudentResult,
                "academic_year_id",
                academic_year_id
            )


            # Term
            result_query = apply_optional_filter(
                result_query,
                StudentResult,
                "term_id",
                term_id
            )


            student_results_exam = (
                result_query
                .order_by(
                    StudentResult.id.desc()
                )
                .all()
            )


            # =================================================
            # RESULT SUMMARY
            # =================================================

            result_summary["total_exams"] = len(
                student_results_exam
            )


            percentage_values = []


            for result in student_results_exam:

                result_status = normalize_status(
                    first_value(
                        result,
                        "result_status",
                        "status",
                        default=""
                    )
                )


                publication_status = normalize_status(
                    first_value(
                        result,
                        "status",
                        default=""
                    )
                )


                if result_status in {
                    "pass",
                    "passed",
                    "promoted",
                }:

                    result_summary["passed"] += 1


                elif result_status in {
                    "fail",
                    "failed",
                }:

                    result_summary["failed"] += 1


                elif result_status in {
                    "incomplete",
                    "pending",
                }:

                    result_summary["incomplete"] += 1


                if publication_status in {
                    "published",
                }:

                    result_summary["published"] += 1


                percentage = first_value(
                    result,
                    "percentage",
                    "average_percentage",
                    default=None
                )


                if percentage is not None:

                    try:
                        percentage_values.append(
                            float(percentage)
                        )
                    except (
                        TypeError,
                        ValueError
                    ):
                        pass


            if percentage_values:

                result_summary[
                    "average_percentage"
                ] = round(
                    sum(percentage_values)
                    /
                    len(percentage_values),
                    2
                )


        except Exception:

            student_results_exam = []


        # ====================================================
        # RANKING
        #
        # StudentResult architecture:
        #
        # institution_position
        # branch_position
        # program_position
        # class_position
        # section_position
        # ====================================================

        if student_results_exam:

            latest_result = student_results_exam[0]


            rank_summary = {

                "institution_position":
                    first_value(
                        latest_result,
                        "institution_position",
                        default=None
                    ),

                "branch_position":
                    first_value(
                        latest_result,
                        "branch_position",
                        default=None
                    ),

                "program_position":
                    first_value(
                        latest_result,
                        "program_position",
                        default=None
                    ),

                "class_position":
                    first_value(
                        latest_result,
                        "class_position",
                        default=None
                    ),

                "section_position":
                    first_value(
                        latest_result,
                        "section_position",
                        default=None
                    ),
            }


            # =================================================
            # BUILD RANKING TABLE DATA
            # =================================================

            for result in student_results_exam:

                ranking_rows.append({

                    "exam": getattr(
                        result,
                        "exam",
                        None
                    ),

                    "academic_year": getattr(
                        result,
                        "academic_year",
                        None
                    ),

                    "term": getattr(
                        result,
                        "term",
                        None
                    ),

                    "percentage": first_value(
                        result,
                        "percentage",
                        default=None
                    ),

                    "grade": first_value(
                        result,
                        "grade",
                        default=None
                    ),

                    "gpa": first_value(
                        result,
                        "gpa",
                        default=None
                    ),

                    "result_status": first_value(
                        result,
                        "result_status",
                        default=None
                    ),

                    "institution_position":
                        first_value(
                            result,
                            "institution_position",
                            default=None
                        ),

                    "branch_position":
                        first_value(
                            result,
                            "branch_position",
                            default=None
                        ),

                    "program_position":
                        first_value(
                            result,
                            "program_position",
                            default=None
                        ),

                    "class_position":
                        first_value(
                            result,
                            "class_position",
                            default=None
                        ),

                    "section_position":
                        first_value(
                            result,
                            "section_position",
                            default=None
                        ),

                    "status": first_value(
                        result,
                        "status",
                        default=None
                    ),
                })


        # ====================================================
        # ACADEMIC YEAR / TERM LISTS
        #
        # IMPORTANT:
        # These are NOT all students.
        # They are only filter options.
        # ====================================================

    # ========================================================
    # ACADEMIC YEARS
    # ========================================================

    academic_year_query = AcademicYear.query


    if user_role != "superadmin":

        if user_institution_id is not None:

            if hasattr(
                AcademicYear,
                "institution_id"
            ):

                academic_year_query = (
                    academic_year_query
                    .filter(
                        AcademicYear.institution_id ==
                        user_institution_id
                    )
                )


    academic_years = (
        academic_year_query
        .order_by(
            AcademicYear.id.desc()
        )
        .all()
    )


    # ========================================================
    # TERMS
    # ========================================================

    term_query = Term.query


    if user_role != "superadmin":

        if user_institution_id is not None:

            if hasattr(
                Term,
                "institution_id"
            ):

                term_query = (
                    term_query
                    .filter(
                        Term.institution_id ==
                        user_institution_id
                    )
                )


    if academic_year_id:

        if hasattr(
            Term,
            "academic_year_id"
        ):

            term_query = term_query.filter(
                Term.academic_year_id ==
                academic_year_id
            )


    terms = (
        term_query
        .order_by(
            Term.id.asc()
        )
        .all()
    )


    # ========================================================
    # STUDENT DATA
    # ========================================================

    student_data = None

    if student:

        student_name = first_value(
            student,
            "name",
            "full_name",
            "student_name",
            default=None
        )


        if not student_name:

            student_name = (
                f"{first_value(student, 'first_name', default='') or ''} "
                f"{first_value(student, 'last_name', default='') or ''}"
            ).strip()


        student_data = {

            "id":
                getattr(student, "id", None),

            "name":
                student_name or "Student",

            "admission_no":
                first_value(
                    student,
                    "admission_no",
                    "admission_number",
                    default=None
                ),

            "roll_no":
                first_value(
                    student,
                    "roll_no",
                    "roll_number",
                    default=None
                ),

            "gender":
                first_value(
                    student,
                    "gender",
                    default=None
                ),

            "dob":
                first_value(
                    student,
                    "dob",
                    "date_of_birth",
                    default=None
                ),

            "phone":
                first_value(
                    student,
                    "phone",
                    "phone_number",
                    default=None
                ),

            "email":
                first_value(
                    student,
                    "email",
                    default=None
                ),

            "address":
                first_value(
                    student,
                    "address",
                    default=None
                ),

            "photo":
                first_value(
                    student,
                    "photo",
                    "photo_url",
                    "profile_photo",
                    "image",
                    default=None
                ),
        }


    # ========================================================
    # RANK SUMMARY
    #
    # Additional readable ranking information for template.
    # ========================================================

    ranking_display = {

        "institution":
            rank_summary.get(
                "institution_position"
            ),

        "branch":
            rank_summary.get(
                "branch_position"
            ),

        "program":
            rank_summary.get(
                "program_position"
            ),

        "class":
            rank_summary.get(
                "class_position"
            ),

        "section":
            rank_summary.get(
                "section_position"
            ),
    }


    # ========================================================
    # RENDER
    # ========================================================

    return render_template(

        "backend/pages/students/student_report.html",

        # ----------------------------------------------------
        # STUDENT
        # ----------------------------------------------------

        student=student,

        student_data=student_data,

        student_results=student_results,

        # ----------------------------------------------------
        # INSTITUTION / BRANCH
        # ----------------------------------------------------

        institution=institution,

        branch=branch,

        # ----------------------------------------------------
        # ENROLLMENT
        # ----------------------------------------------------

        enrollments=enrollments,

        current_enrollment=current_enrollment,

        enrollment_data=enrollment_data,

        # ----------------------------------------------------
        # ATTENDANCE
        # ----------------------------------------------------

        attendance_rows=attendance_rows,

        attendance_total=attendance_total,

        attendance_summary=attendance_summary,

        # ----------------------------------------------------
        # MARKS
        # ----------------------------------------------------

        exam_mark_rows=exam_mark_rows,

        mark_total=mark_total,

        # ----------------------------------------------------
        # RESULTS
        # ----------------------------------------------------

        student_results_exam=student_results_exam,

        result_summary=result_summary,

        # ----------------------------------------------------
        # RANKING
        # ----------------------------------------------------

        ranking_rows=ranking_rows,

        rank_summary=rank_summary,

        ranking_display=ranking_display,

        # ----------------------------------------------------
        # FILTER DATA
        # ----------------------------------------------------

        academic_years=academic_years,

        terms=terms,


        search=search,

        student_id=student_id,

        academic_year_id=academic_year_id,

        term_id=term_id,
    )


# ============================================================
# EXAM RESULTS
# ADMIN / SCHOOL / BRANCH / SUPERADMIN
# PostgreSQL / Neon
# ============================================================

@bp.route(
    "/exam-results",
    methods=["GET"]
)
@login_required
def exam_results():

    # ========================================================
    # SECURITY
    # ========================================================

    role = str(
        getattr(current_user, "role", "") or ""
    ).lower().strip()

    allowed_roles = {
        "superadmin",
        "school_admin",
        "branch_admin",
    }

    if role not in allowed_roles:
        abort(403)

    # ========================================================
    # CURRENT USER INSTITUTION
    # ========================================================

    current_institution_id = getattr(
        current_user,
        "institution_id",
        None
    )

    current_branch_id = getattr(
        current_user,
        "branch_id",
        None
    )

    # ========================================================
    # SUPERADMIN
    # ========================================================
    #
    # Superadmin can work with all institutions.
    #
    # school_admin:
    #   institution only
    #
    # branch_admin:
    #   institution + branch only
    #
    # ========================================================

    institution_id = request.args.get(
        "institution_id",
        type=int
    )

    branch_id = request.args.get(
        "branch_id",
        type=int
    )

    exam_id = request.args.get(
        "exam_id",
        type=int
    )

    academic_year_id = request.args.get(
        "academic_year_id",
        type=int
    )

    term_id = request.args.get(
        "term_id",
        type=int
    )

    program_id = request.args.get(
        "program_id",
        type=int
    )

    class_id = request.args.get(
        "class_id",
        type=int
    )

    section_id = request.args.get(
        "section_id",
        type=int
    )

    result_status = (
        request.args.get(
            "result_status",
            ""
        )
        .strip()
        .lower()
    )

    status = (
        request.args.get(
            "status",
            ""
        )
        .strip()
        .lower()
    )

    search = (
        request.args.get(
            "search",
            ""
        )
        .strip()
    )

    # ========================================================
    # NORMALIZE EMPTY VALUES
    # ========================================================

    if result_status not in {
        "",
        "pass",
        "fail",
        "incomplete",
    }:
        result_status = ""

    if status not in {
        "",
        "draft",
        "submitted",
        "approved",
        "published",
    }:
        status = ""

    # ========================================================
    # INSTITUTION SECURITY
    # ========================================================

    if role == "school_admin":

        if not current_institution_id:
            abort(403)

        institution_id = current_institution_id

    elif role == "branch_admin":

        if (
            not current_institution_id
            or not current_branch_id
        ):
            abort(403)

        institution_id = current_institution_id
        branch_id = current_branch_id

    elif role == "superadmin":

        # ----------------------------------------------------
        # Superadmin can select institution.
        # ----------------------------------------------------

        if institution_id:

            selected_institution = (
                Institution.query
                .filter(
                    Institution.id == institution_id
                )
                .first()
            )

            if not selected_institution:
                abort(404)

    # ========================================================
    # BRANCH SECURITY
    # ========================================================

    if institution_id and branch_id:

        branch = (
            Branch.query
            .filter(
                Branch.id == branch_id,
                Branch.institution_id == institution_id
            )
            .first()
        )

        if not branch:
            abort(404)

    # ========================================================
    # BASE RESULT QUERY
    # ========================================================

    query = (
        StudentResult.query
        .join(
            Student,
            Student.id == StudentResult.student_id
        )
        .filter(
            StudentResult.institution_id
            == institution_id
        )
    )

    # ========================================================
    # BRANCH FILTER
    # ========================================================

    if branch_id:

        query = query.filter(
            StudentResult.branch_id == branch_id
        )

    # ========================================================
    # EXAM
    # ========================================================

    if exam_id:

        query = query.filter(
            StudentResult.exam_id == exam_id
        )

    # ========================================================
    # ACADEMIC YEAR
    # ========================================================

    if academic_year_id:

        query = query.filter(
            StudentResult.academic_year_id
            == academic_year_id
        )

    # ========================================================
    # TERM
    # ========================================================

    if term_id:

        query = query.filter(
            StudentResult.term_id == term_id
        )

    # ========================================================
    # PROGRAM
    # ========================================================

    if program_id:

        query = query.filter(
            StudentResult.program_id == program_id
        )

    # ========================================================
    # CLASS
    # ========================================================

    if class_id:

        query = query.filter(
            StudentResult.class_id == class_id
        )

    # ========================================================
    # SECTION
    # ========================================================

    if section_id:

        query = query.filter(
            StudentResult.section_id == section_id
        )

    # ========================================================
    # RESULT STATUS
    # ========================================================

    if result_status:

        query = query.filter(
            db.func.lower(
                StudentResult.result_status
            ) == result_status
        )

    # ========================================================
    # WORKFLOW STATUS
    # ========================================================

    if status:

        query = query.filter(
            db.func.lower(
                StudentResult.status
            ) == status
        )

    # ========================================================
    # STUDENT SEARCH
    # ========================================================

    if search:

        search_pattern = f"%{search}%"

        query = query.filter(
            db.or_(

                Student.full_name.ilike(
                    search_pattern
                ),

                Student.admission_no.ilike(
                    search_pattern
                )
            )
        )

    # ========================================================
    # SUMMARY
    # ========================================================

    total_results = query.count()

    total_pass = (
        query
        .filter(
            db.func.lower(
                StudentResult.result_status
            ) == "pass"
        )
        .count()
    )

    total_fail = (
        query
        .filter(
            db.func.lower(
                StudentResult.result_status
            ) == "fail"
        )
        .count()
    )

    total_incomplete = (
        query
        .filter(
            db.func.lower(
                StudentResult.result_status
            ) == "incomplete"
        )
        .count()
    )

    total_published = (
        query
        .filter(
            db.func.lower(
                StudentResult.status
            ) == "published"
        )
        .count()
    )

    total_approved = (
        query
        .filter(
            db.func.lower(
                StudentResult.status
            ) == "approved"
        )
        .count()
    )

    total_draft = (
        query
        .filter(
            db.func.lower(
                StudentResult.status
            ) == "draft"
        )
        .count()
    )

    # ========================================================
    # AVERAGE PERCENTAGE
    # ========================================================

    average_percentage = (
        db.session.query(
            db.func.avg(
                StudentResult.percentage
            )
        )
        .filter(
            StudentResult.institution_id
            == institution_id
        )
    )

    if branch_id:

        average_percentage = average_percentage.filter(
            StudentResult.branch_id == branch_id
        )

    if exam_id:

        average_percentage = average_percentage.filter(
            StudentResult.exam_id == exam_id
        )

    if academic_year_id:

        average_percentage = average_percentage.filter(
            StudentResult.academic_year_id
            == academic_year_id
        )

    if term_id:

        average_percentage = average_percentage.filter(
            StudentResult.term_id == term_id
        )

    if program_id:

        average_percentage = average_percentage.filter(
            StudentResult.program_id == program_id
        )

    if class_id:

        average_percentage = average_percentage.filter(
            StudentResult.class_id == class_id
        )

    if section_id:

        average_percentage = average_percentage.filter(
            StudentResult.section_id == section_id
        )

    if result_status:

        average_percentage = average_percentage.filter(
            db.func.lower(
                StudentResult.result_status
            ) == result_status
        )

    if status:

        average_percentage = average_percentage.filter(
            db.func.lower(
                StudentResult.status
            ) == status
        )

    average_percentage = (
        average_percentage
        .scalar()
    )

    average_percentage = to_decimal(
        average_percentage
    ).quantize(
        Decimal("0.01"),
        rounding=ROUND_HALF_UP
    )

    # ========================================================
    # PAGINATION
    # ========================================================

    page = request.args.get(
        "page",
        1,
        type=int
    )

    if page < 1:
        page = 1

    per_page = request.args.get(
        "per_page",
        25,
        type=int
    )

    if per_page not in {
        10,
        25,
        50,
        100,
    }:
        per_page = 25

    pagination = (
        query
        .options(
            joinedload(
                StudentResult.student
            ),

            joinedload(
                StudentResult.exam
            ),

            joinedload(
                StudentResult.institution
            ),

            joinedload(
                StudentResult.branch
            ),

            joinedload(
                StudentResult.program
            ),

            joinedload(
                StudentResult.academic_year
            ),

            joinedload(
                StudentResult.term
            ),

            joinedload(
                StudentResult.class_
            ),

            joinedload(
                StudentResult.section
            )
        )
        .order_by(

            StudentResult.percentage.desc(),

            StudentResult.gpa.desc(),

            StudentResult.student_id.asc(),

            StudentResult.id.asc()
        )
        .paginate(
            page=page,
            per_page=per_page,
            error_out=False
        )
    )

    results = pagination.items

    # ========================================================
    # INSTITUTIONS
    # ========================================================

    institutions = []

    if role == "superadmin":

        institutions = (
            Institution.query
            .order_by(
                Institution.name.asc()
            )
            .all()
        )

    elif current_institution_id:

        institution = (
            Institution.query
            .filter(
                Institution.id
                == current_institution_id
            )
            .first()
        )

        if institution:
            institutions = [institution]

    # ========================================================
    # BRANCHES
    # ========================================================

    branches_query = Branch.query

    if institution_id:

        branches_query = branches_query.filter(
            Branch.institution_id
            == institution_id
        )

    if role == "branch_admin":

        branches_query = branches_query.filter(
            Branch.id == current_branch_id
        )

    branches = (
        branches_query
        .order_by(
            Branch.name.asc()
        )
        .all()
    )

    # ========================================================
    # EXAMS
    # ========================================================

    exams_query = Exam.query

    if institution_id:

        exams_query = exams_query.filter(
            Exam.institution_id
            == institution_id
        )

    if branch_id:

        exams_query = exams_query.filter(
            Exam.branch_id == branch_id
        )

    if academic_year_id:

        exams_query = exams_query.filter(
            Exam.academic_year_id
            == academic_year_id
        )

    if program_id:

        exams_query = exams_query.filter(
            Exam.program_id == program_id
        )

    exams = (
        exams_query
        .order_by(
            Exam.id.desc()
        )
        .all()
    )

    # ========================================================
    # ACADEMIC YEARS
    # ========================================================

    academic_years_query = AcademicYear.query

    if institution_id:

        academic_years_query = (
            academic_years_query
            .filter(
                AcademicYear.institution_id
                == institution_id
            )
        )

    academic_years = (
        academic_years_query
        .order_by(
            AcademicYear.id.desc()
        )
        .all()
    )

    # ========================================================
    # TERMS
    # ========================================================

    terms_query = Term.query

    if institution_id:

        terms_query = terms_query.filter(
            Term.institution_id
            == institution_id
        )

    if academic_year_id:

        terms_query = terms_query.filter(
            Term.academic_year_id
            == academic_year_id
        )

    terms = (
        terms_query
        .order_by(
            Term.id.asc()
        )
        .all()
    )

    # ========================================================
    # PROGRAMS
    # ========================================================

    programs_query = Program.query

    if institution_id:

        programs_query = programs_query.filter(
            Program.institution_id
            == institution_id
        )

    if branch_id:

        programs_query = programs_query.filter(
            db.or_(
                Program.branch_id == branch_id,
                Program.branch_id.is_(None)
            )
        )

    programs = (
        programs_query
        .order_by(
            Program.name.asc()
        )
        .all()
    )

    # ========================================================
    # CLASSES
    # ========================================================

    classes_query = Class.query

    if institution_id:

        classes_query = classes_query.filter(
            Class.institution_id
            == institution_id
        )

    if branch_id:

        classes_query = classes_query.filter(
            Class.branch_id == branch_id
        )

    if program_id:

        classes_query = classes_query.filter(
            Class.program_id == program_id
        )

    if academic_year_id:

        classes_query = classes_query.filter(
            Class.academic_year_id
            == academic_year_id
        )

    classes = (
        classes_query
        .order_by(
            Class.name.asc()
        )
        .all()
    )

    # ========================================================
    # SECTIONS
    # ========================================================

    sections_query = Section.query

    if institution_id:

        sections_query = sections_query.filter(
            Section.institution_id
            == institution_id
        )

    if branch_id:

        sections_query = sections_query.filter(
            Section.branch_id == branch_id
        )

    if class_id:

        sections_query = sections_query.filter(
            Section.class_id == class_id
        )

    if academic_year_id:

        sections_query = sections_query.filter(
            Section.academic_year_id
            == academic_year_id
        )

    sections = (
        sections_query
        .order_by(
            Section.name.asc()
        )
        .all()
    )

    # ========================================================
    # RENDER
    # ========================================================

    return render_template(
        "backend/pages/results/exam_results.html",

        # ----------------------------------------------------
        # RESULTS
        # ----------------------------------------------------

        results=results,

        pagination=pagination,

        # ----------------------------------------------------
        # FILTER DATA
        # ----------------------------------------------------

        institutions=institutions,

        branches=branches,

        exams=exams,

        academic_years=academic_years,

        terms=terms,

        programs=programs,

        classes=classes,

        sections=sections,

        # ----------------------------------------------------
        # CURRENT FILTERS
        # ----------------------------------------------------

        institution_id=institution_id,

        branch_id=branch_id,

        exam_id=exam_id,

        academic_year_id=academic_year_id,

        term_id=term_id,

        program_id=program_id,

        class_id=class_id,

        section_id=section_id,

        result_status=result_status,

        status=status,

        search=search,

        page=page,

        per_page=per_page,

        # ----------------------------------------------------
        # SUMMARY
        # ----------------------------------------------------

        total_results=total_results,

        total_pass=total_pass,

        total_fail=total_fail,

        total_incomplete=total_incomplete,

        total_published=total_published,

        total_approved=total_approved,

        total_draft=total_draft,

        average_percentage=average_percentage,

        # ----------------------------------------------------
        # CURRENT USER
        # ----------------------------------------------------

        user=current_user
    )


# ============================================================
# DELETE EXAM RESULT
# ============================================================

@bp.route(
    "/exam-results/<int:result_id>/delete",
    methods=["POST"]
)
@login_required
def delete_exam_result(result_id):

    # ========================================================
    # SECURITY
    # ========================================================

    role = getattr(current_user, "role", None)

    allowed_roles = {
        "superadmin",
        "school_admin",
        "branch_admin",
    }

    if role not in allowed_roles:
        abort(403)

    # ========================================================
    # LOAD RESULT
    # ========================================================

    result = (
        StudentResult.query
        .filter(
            StudentResult.id == result_id
        )
        .first()
    )

    if not result:
        flash(
            "Exam result was not found.",
            "error"
        )
        return redirect(
            url_for("main.exam_results")
        )

    # ========================================================
    # SCOPE CHECK
    # ========================================================

    if role == "superadmin":

        # Superadmin can manage all institutions/results.
        pass

    elif role == "school_admin":

        user_institution_id = getattr(
            current_user,
            "institution_id",
            None
        )

        if not user_institution_id:
            abort(403)

        if result.institution_id != user_institution_id:
            abort(403)

    elif role == "branch_admin":

        user_institution_id = getattr(
            current_user,
            "institution_id",
            None
        )

        user_branch_id = getattr(
            current_user,
            "branch_id",
            None
        )

        if not user_institution_id or not user_branch_id:
            abort(403)

        if (
            result.institution_id != user_institution_id
            or result.branch_id != user_branch_id
        ):
            abort(403)

    # ========================================================
    # KEEP BASIC INFORMATION FOR FLASH MESSAGE
    # ========================================================

    student_name = "Student"

    if getattr(result, "student", None):

        student_name = (
            getattr(
                result.student,
                "full_name",
                None
            )
            or getattr(
                result.student,
                "name",
                None
            )
            or "Student"
        )

    exam_name = "Exam"

    if getattr(result, "exam", None):

        exam_name = (
            getattr(
                result.exam,
                "name",
                None
            )
            or getattr(
                result.exam,
                "title",
                None
            )
            or getattr(
                result.exam,
                "code",
                None
            )
            or "Exam"
        )

    # ========================================================
    # DELETE
    # ========================================================

    try:

        db.session.delete(result)

        db.session.commit()

        flash(
            f"Exam result for {student_name} "
            f"({exam_name}) was deleted successfully.",
            "success"
        )

    except Exception as exc:

        db.session.rollback()

        current_app.logger.exception(
            "Failed to delete exam result %s: %s",
            result_id,
            exc
        )

        flash(
            "Unable to delete the exam result. "
            "Please try again.",
            "error"
        )

    # ========================================================
    # RETURN TO RESULTS PAGE
    # ========================================================

    return redirect(
        url_for("main.exam_results")
    )


# ============================================================
# EDIT EXAM RESULT
# ============================================================
# ============================================================
# EDIT EXAM RESULT
# ADMIN CAN COMPLETE MISSING SUBJECT MARKS
# ============================================================
# ============================================================
# EDIT EXAM RESULT
# ADMIN CAN COMPLETE MISSING SUBJECT MARKS
# ============================================================

@bp.route(
    "/exam-results/<int:result_id>/edit",
    methods=["GET", "POST"]
)
@login_required
def edit_exam_result(result_id):

    # ========================================================
    # SECURITY / ROLE
    # ========================================================

    role = getattr(
        current_user,
        "role",
        None
    )

    allowed_roles = {
        "superadmin",
        "school_admin",
        "branch_admin",
    }

    if role not in allowed_roles:
        abort(403)

    # ========================================================
    # LOAD RESULT
    # ========================================================

    result = (
        StudentResult.query
        .options(
            db.joinedload(
                StudentResult.student
            ),
            db.joinedload(
                StudentResult.exam
            ),
            db.joinedload(
                StudentResult.institution
            ),
            db.joinedload(
                StudentResult.branch
            ),
            db.joinedload(
                StudentResult.program
            ),
            db.joinedload(
                StudentResult.academic_year
            ),
            db.joinedload(
                StudentResult.term
            ),
            db.joinedload(
                StudentResult.section
            ),
        )
        .filter(
            StudentResult.id == result_id
        )
        .first()
    )

    # ========================================================
    # RESULT NOT FOUND
    # ========================================================

    if not result:

        flash(
            "Exam result was not found.",
            "error"
        )

        return redirect(
            url_for(
                "main.exam_results"
            )
        )

    # ========================================================
    # SCOPE SECURITY
    # ========================================================

    if role == "superadmin":

        pass

    elif role == "school_admin":

        current_institution_id = getattr(
            current_user,
            "institution_id",
            None
        )

        if not current_institution_id:
            abort(403)

        if (
            result.institution_id
            != current_institution_id
        ):
            abort(403)

    elif role == "branch_admin":

        current_institution_id = getattr(
            current_user,
            "institution_id",
            None
        )

        current_branch_id = getattr(
            current_user,
            "branch_id",
            None
        )

        if (
            not current_institution_id
            or not current_branch_id
        ):
            abort(403)

        if (
            result.institution_id
            != current_institution_id
        ):
            abort(403)

        if (
            result.branch_id
            != current_branch_id
        ):
            abort(403)

    # ========================================================
    # BASIC IDs
    # ========================================================

    exam_id = result.exam_id
    student_id = result.student_id

    institution_id = result.institution_id
    branch_id = result.branch_id

    # ========================================================
    # VALIDATE BASIC REFERENCES
    # ========================================================

    if not exam_id:
        flash(
            "This result is not linked to an examination.",
            "error"
        )

        return redirect(
            url_for(
                "main.exam_results"
            )
        )

    if not student_id:
        flash(
            "This result is not linked to a student.",
            "error"
        )

        return redirect(
            url_for(
                "main.exam_results"
            )
        )

    if not institution_id:
        flash(
            "This result has no institution assigned.",
            "error"
        )

        return redirect(
            url_for(
                "main.exam_results"
            )
        )

    if not branch_id:
        flash(
            "This result has no branch assigned.",
            "error"
        )

        return redirect(
            url_for(
                "main.exam_results"
            )
        )

    # ========================================================
    # LOAD ALL EXAM SUBJECTS
    #
    # IMPORTANT:
    # We intentionally load ALL subjects.
    #
    # This allows admin to complete subjects where no Mark
    # row currently exists.
    # ========================================================

    exam_subjects = (
        ExamSubject.query
        .options(
            db.joinedload(
                ExamSubject.subject
            ),
            db.joinedload(
                ExamSubject.teacher
            ),
        )
        .filter(
            ExamSubject.exam_id == exam_id
        )
        .order_by(
            ExamSubject.id.asc()
        )
        .all()
    )

    # ========================================================
    # NO SUBJECTS
    # ========================================================

    if not exam_subjects:

        flash(
            "This examination has no subjects assigned.",
            "error"
        )

        return redirect(
            url_for(
                "main.view_exam_result",
                result_id=result.id
            )
        )

    # ========================================================
    # SUBJECT IDS
    # ========================================================

    exam_subject_ids = [
        item.id
        for item in exam_subjects
    ]

    # ========================================================
    # LOAD EXISTING MARKS
    # ========================================================

    existing_marks = (
        Mark.query
        .filter(
            Mark.student_id == student_id,
            Mark.exam_subject_id.in_(
                exam_subject_ids
            )
        )
        .all()
    )

    # ========================================================
    # MARK MAP
    # ========================================================

    mark_map = {
        mark.exam_subject_id: mark
        for mark in existing_marks
    }

    # ========================================================
    # POST
    # ========================================================

    if request.method == "POST":

        try:

            # =================================================
            # PROCESS EVERY EXAM SUBJECT
            # =================================================

            for exam_subject in exam_subjects:

                exam_subject_id = (
                    exam_subject.id
                )

                # =============================================
                # EXISTING MARK
                # =============================================

                mark = mark_map.get(
                    exam_subject_id
                )

                # =============================================
                # FIELD NAMES
                # =============================================

                mark_field = (
                    f"mark_{exam_subject_id}"
                )

                absent_field = (
                    f"absent_{exam_subject_id}"
                )

                exempted_field = (
                    f"exempted_{exam_subject_id}"
                )

                remark_field = (
                    f"remark_{exam_subject_id}"
                )

                # =============================================
                # RAW VALUES
                # =============================================

                raw_marks = request.form.get(
                    mark_field,
                    ""
                )

                raw_marks = (
                    raw_marks.strip()
                    if raw_marks
                    else ""
                )

                is_absent = (
                    request.form.get(
                        absent_field
                    ) == "1"
                )

                is_exempted = (
                    request.form.get(
                        exempted_field
                    ) == "1"
                )

                subject_remark = request.form.get(
                    remark_field,
                    ""
                )

                subject_remark = (
                    subject_remark.strip()
                    if subject_remark
                    else ""
                )

                # =============================================
                # SUBJECT NAME
                # =============================================

                subject = getattr(
                    exam_subject,
                    "subject",
                    None
                )

                subject_name = (
                    getattr(
                        subject,
                        "name",
                        None
                    )
                    or getattr(
                        subject,
                        "title",
                        None
                    )
                    or "Subject"
                )

                # =============================================
                # ABSENT + EXEMPTED
                #
                # They cannot both be selected.
                # =============================================

                if (
                    is_absent
                    and is_exempted
                ):

                    raise ValueError(
                        f"{subject_name}: "
                        "A subject cannot be both "
                        "absent and exempted."
                    )

                # =============================================
                # COMPLETELY EMPTY
                #
                # IMPORTANT:
                # Do NOT create a zero.
                #
                # Existing mark is preserved.
                # Missing subject remains missing.
                # =============================================

                if (
                    not raw_marks
                    and not is_absent
                    and not is_exempted
                ):

                    continue

                # =============================================
                # ABSENT
                #
                # marks_obtained MUST remain None.
                # =============================================

                if is_absent:

                    if mark is None:

                        mark = Mark(
                            exam_subject_id=(
                                exam_subject_id
                            ),
                            student_id=student_id,
                            marks_obtained=None,
                            is_absent=True,
                            is_exempted=False,
                            remarks=(
                                subject_remark
                                or None
                            ),
                            status="submitted",
                            entered_by=None,
                        )

                        db.session.add(
                            mark
                        )

                        mark_map[
                            exam_subject_id
                        ] = mark

                    else:

                        mark.marks_obtained = None

                        mark.is_absent = True

                        mark.is_exempted = False

                        mark.remarks = (
                            subject_remark
                            or None
                        )

                        mark.status = (
                            "submitted"
                        )

                    continue

                # =============================================
                # EXEMPTED
                #
                # marks_obtained MUST remain None.
                # =============================================

                if is_exempted:

                    if mark is None:

                        mark = Mark(
                            exam_subject_id=(
                                exam_subject_id
                            ),
                            student_id=student_id,
                            marks_obtained=None,
                            is_absent=False,
                            is_exempted=True,
                            remarks=(
                                subject_remark
                                or None
                            ),
                            status="submitted",
                            entered_by=None,
                        )

                        db.session.add(
                            mark
                        )

                        mark_map[
                            exam_subject_id
                        ] = mark

                    else:

                        mark.marks_obtained = None

                        mark.is_absent = False

                        mark.is_exempted = True

                        mark.remarks = (
                            subject_remark
                            or None
                        )

                        mark.status = (
                            "submitted"
                        )

                    continue

                # =============================================
                # NORMAL MARK
                # =============================================

                try:

                    marks = Decimal(
                        raw_marks
                    )

                except (
                    InvalidOperation,
                    ValueError,
                    TypeError
                ):

                    raise ValueError(
                        f"Invalid marks entered for "
                        f"{subject_name}."
                    )

                # =============================================
                # FINITE NUMBER CHECK
                # =============================================

                if not marks.is_finite():

                    raise ValueError(
                        f"Invalid marks entered for "
                        f"{subject_name}."
                    )

                # =============================================
                # NEGATIVE CHECK
                # =============================================

                if marks < Decimal("0"):

                    raise ValueError(
                        f"Marks cannot be negative for "
                        f"{subject_name}."
                    )

                # =============================================
                # MAX MARKS
                # =============================================

                max_marks = to_decimal(
                    exam_subject.max_marks,
                    Decimal("0")
                )

                if max_marks <= Decimal("0"):

                    raise ValueError(
                        f"Maximum marks are not configured "
                        f"correctly for {subject_name}."
                    )

                # =============================================
                # EXCEEDS MAXIMUM
                # =============================================

                if marks > max_marks:

                    raise ValueError(
                        f"Marks for {subject_name} "
                        f"cannot exceed {max_marks}."
                    )

                # =============================================
                # SAVE NORMAL MARK
                # =============================================

                if mark is None:

                    mark = Mark(
                        exam_subject_id=(
                            exam_subject_id
                        ),
                        student_id=student_id,
                        marks_obtained=marks,
                        is_absent=False,
                        is_exempted=False,
                        remarks=(
                            subject_remark
                            or None
                        ),
                        status="submitted",
                        entered_by=None,
                    )

                    db.session.add(
                        mark
                    )

                    mark_map[
                        exam_subject_id
                    ] = mark

                else:

                    mark.marks_obtained = marks

                    mark.is_absent = False

                    mark.is_exempted = False

                    mark.remarks = (
                        subject_remark
                        or None
                    )

                    mark.status = (
                        "submitted"
                    )

            # =================================================
            # OVERALL ADMIN REMARKS
            # =================================================

            remarks = request.form.get(
                "remarks",
                ""
            )

            remarks = (
                remarks.strip()
                if remarks
                else ""
            )

            if len(remarks) > 5000:

                raise ValueError(
                    "Remarks cannot exceed "
                    "5000 characters."
                )

            # =================================================
            # WORKFLOW STATUS
            # =================================================

            submitted_status = request.form.get(
                "status",
                result.status or "draft"
            )

            submitted_status = (
                submitted_status.strip().lower()
                if submitted_status
                else "draft"
            )

            allowed_statuses = {
                "draft",
                "submitted",
                "approved",
                "published",
            }

            if (
                submitted_status
                not in allowed_statuses
            ):

                raise ValueError(
                    "Invalid result workflow status."
                )

            # =================================================
            # SAVE ADMIN FIELDS
            # =================================================

            result.remarks = (
                remarks
                or None
            )

            result.status = (
                submitted_status
            )

            # =================================================
            # FLUSH MARKS
            # =================================================

            db.session.flush()

            # =================================================
            # RECALCULATE STUDENT RESULT
            #
            # IMPORTANT:
            # Your existing helper is designed as:
            #
            # calculate_student_result(
            #     exam,
            #     student_id,
            #     institution_id,
            #     branch_id
            # )
            # =================================================

            calculated_result = (
                calculate_student_result(
                    result.exam,
                    student_id,
                    institution_id,
                    branch_id,
                )
            )

            # =================================================
            # ENSURE CALCULATION RETURNED A RESULT
            # =================================================

            if calculated_result is None:

                raise RuntimeError(
                    "The student result calculation "
                    "did not return a result."
                )

            # =================================================
            # FLUSH CALCULATED VALUES
            # =================================================

            db.session.flush()

            # =================================================
            # RELOAD RESULT
            # =================================================

            refreshed_result = (
                StudentResult.query
                .filter(
                    StudentResult.id == result_id
                )
                .first()
            )

            if not refreshed_result:

                raise RuntimeError(
                    "Student result could not be "
                    "reloaded after calculation."
                )

            # =================================================
            # RESTORE ADMINISTRATIVE VALUES
            #
            # calculate_student_result() intentionally sets:
            #
            # result.status = "draft"
            #
            # Therefore restore the status selected by admin.
            # =================================================

            refreshed_result.remarks = (
                remarks
                or None
            )

            refreshed_result.status = (
                submitted_status
            )

            # =================================================
            # REGENERATE RANKINGS
            #
            # IMPORTANT:
            # Your actual helper requires:
            #
            # calculate_exam_rankings(
            #     exam_id,
            #     institution_id,
            #     branch_id
            # )
            # =================================================

            calculate_exam_rankings(
                exam_id,
                institution_id,
                branch_id,
            )

            # =================================================
            # FINAL FLUSH
            # =================================================

            db.session.flush()

            # =================================================
            # FINAL COMMIT
            # =================================================

            db.session.commit()

            # =================================================
            # SUCCESS
            # =================================================

            flash(
                "Exam result updated successfully. "
                "Subject marks, calculated result values, "
                "and rankings have been regenerated.",
                "success"
            )

            return redirect(
                url_for(
                    "main.view_exam_result",
                    result_id=result_id
                )
            )

        # ====================================================
        # VALIDATION ERROR
        # ====================================================

        except ValueError as exc:

            db.session.rollback()

            flash(
                str(exc),
                "error"
            )

        # ====================================================
        # UNEXPECTED ERROR
        # ====================================================

        except Exception as exc:

            db.session.rollback()

            current_app.logger.exception(
                "EDIT EXAM RESULT FAILED | "
                "result_id=%s | "
                "exam_id=%s | "
                "student_id=%s | "
                "institution_id=%s | "
                "branch_id=%s",
                result_id,
                exam_id,
                student_id,
                institution_id,
                branch_id,
            )

            flash(
                "Unable to update the exam result. "
                "The update was rolled back. "
                "Please check the server console for "
                "the exact error.",
                "error"
            )

    # ========================================================
    # RELOAD RESULT AFTER GET / FAILED POST
    # ========================================================

    result = (
        StudentResult.query
        .options(
            db.joinedload(
                StudentResult.student
            ),
            db.joinedload(
                StudentResult.exam
            ),
            db.joinedload(
                StudentResult.institution
            ),
            db.joinedload(
                StudentResult.branch
            ),
            db.joinedload(
                StudentResult.program
            ),
            db.joinedload(
                StudentResult.academic_year
            ),
            db.joinedload(
                StudentResult.term
            ),
            db.joinedload(
                StudentResult.section
            ),
        )
        .filter(
            StudentResult.id == result_id
        )
        .first()
    )

    # ========================================================
    # RESULT SAFETY
    # ========================================================

    if not result:

        flash(
            "Exam result was not found.",
            "error"
        )

        return redirect(
            url_for(
                "main.exam_results"
            )
        )

    # ========================================================
    # RELOAD EXAM SUBJECTS
    # ========================================================

    exam_subjects = (
        ExamSubject.query
        .options(
            db.joinedload(
                ExamSubject.subject
            ),
            db.joinedload(
                ExamSubject.teacher
            ),
        )
        .filter(
            ExamSubject.exam_id == result.exam_id
        )
        .order_by(
            ExamSubject.id.asc()
        )
        .all()
    )

    # ========================================================
    # RELOAD SUBJECT IDS
    # ========================================================

    exam_subject_ids = [
        item.id
        for item in exam_subjects
    ]

    # ========================================================
    # RELOAD MARKS
    # ========================================================

    existing_marks = []

    if exam_subject_ids:

        existing_marks = (
            Mark.query
            .filter(
                Mark.student_id == result.student_id,
                Mark.exam_subject_id.in_(
                    exam_subject_ids
                )
            )
            .all()
        )

    # ========================================================
    # MARK MAP
    # ========================================================

    mark_map = {
        mark.exam_subject_id: mark
        for mark in existing_marks
    }

    # ========================================================
    # SUBJECT ROWS
    # ========================================================

    subject_rows = []

    for exam_subject in exam_subjects:

        mark = mark_map.get(
            exam_subject.id
        )

        # ====================================================
        # SUBJECT
        # ====================================================

        subject = getattr(
            exam_subject,
            "subject",
            None
        )

        subject_name = (
            getattr(
                subject,
                "name",
                None
            )
            or getattr(
                subject,
                "title",
                None
            )
            or "Subject"
        )

        # ====================================================
        # TEACHER
        # ====================================================

        teacher = getattr(
            exam_subject,
            "teacher",
            None
        )

        teacher_name = (
            getattr(
                teacher,
                "full_name",
                None
            )
            or "—"
        )

        # ====================================================
        # MARK VALUE
        # ====================================================

        marks_value = None

        if (
            mark
            and mark.marks_obtained is not None
        ):

            marks_value = (
                mark.marks_obtained
            )

        # ====================================================
        # STATUS
        # ====================================================

        is_absent = (
            bool(mark.is_absent)
            if mark
            else False
        )

        is_exempted = (
            bool(mark.is_exempted)
            if mark
            else False
        )

        # ====================================================
        # MISSING
        # ====================================================

        is_missing = (
            mark is None
            or (
                mark.marks_obtained is None
                and not is_absent
                and not is_exempted
            )
        )

        # ====================================================
        # APPEND
        # ====================================================

        subject_rows.append({

            "exam_subject": exam_subject,

            "mark": mark,

            "subject_name": subject_name,

            "teacher_name": teacher_name,

            "marks": marks_value,

            "max_marks": (
                exam_subject.max_marks
            ),

            "pass_marks": (
                exam_subject.pass_marks
            ),

            "is_absent": is_absent,

            "is_exempted": is_exempted,

            "is_missing": is_missing,

        })

    # ========================================================
    # COUNTS
    # ========================================================

    total_subjects = len(
        subject_rows
    )

    missing_subjects = sum(
        1
        for row in subject_rows
        if row["is_missing"]
    )

    completed_subjects = sum(
        1
        for row in subject_rows
        if (
            row["marks"] is not None
            and not row["is_absent"]
            and not row["is_exempted"]
        )
    )

    absent_subjects = sum(
        1
        for row in subject_rows
        if row["is_absent"]
    )

    exempted_subjects = sum(
        1
        for row in subject_rows
        if row["is_exempted"]
    )

    # ========================================================
    # RENDER
    # ========================================================

    return render_template(
        "backend/pages/results/edit_exam_result.html",

        result=result,

        exam_subjects=exam_subjects,

        subject_rows=subject_rows,

        mark_map=mark_map,

        total_subjects=total_subjects,

        missing_subjects=missing_subjects,

        completed_subjects=completed_subjects,

        absent_subjects=absent_subjects,

        exempted_subjects=exempted_subjects,

        can_edit_subject_marks=True,

        can_edit_workflow_status=True,

        page_mode="edit",
        user=current_user,
    )




# ============================================================
# VIEW EXAM RESULT
# ============================================================

@bp.route(
    "/exam-results/<int:result_id>/view",
    methods=["GET"]
)
@login_required
def view_exam_result(result_id):

    # ========================================================
    # SECURITY
    # ========================================================

    role = getattr(
        current_user,
        "role",
        None
    )

    allowed_roles = {
        "superadmin",
        "school_admin",
        "branch_admin",
        "teacher",
    }

    if role not in allowed_roles:
        abort(403)

    # ========================================================
    # GET RESULT
    # ========================================================

    result = (
        StudentResult.query
        .filter(
            StudentResult.id == result_id
        )
        .first()
    )

    if not result:

        flash(
            "Exam result was not found.",
            "danger"
        )

        return redirect(
            url_for("main.exam_results")
        )

    # ========================================================
    # INSTITUTION / BRANCH SECURITY
    # ========================================================

    if role == "superadmin":

        pass

    elif role == "school_admin":

        user_institution_id = getattr(
            current_user,
            "institution_id",
            None
        )

        if not user_institution_id:
            abort(403)

        if (
            result.institution_id
            != user_institution_id
        ):
            abort(403)

    elif role == "branch_admin":

        user_institution_id = getattr(
            current_user,
            "institution_id",
            None
        )

        user_branch_id = getattr(
            current_user,
            "branch_id",
            None
        )

        if (
            not user_institution_id
            or not user_branch_id
        ):
            abort(403)

        if (
            result.institution_id
            != user_institution_id
        ):
            abort(403)

        if (
            result.branch_id
            != user_branch_id
        ):
            abort(403)

    elif role == "teacher":

        teacher = getattr(
            g,
            "teacher",
            None
        )

        if not teacher:
            abort(403)

        # ----------------------------------------------------
        # TEACHER INSTITUTION
        # ----------------------------------------------------

        if (
            teacher.institution_id
            != result.institution_id
        ):
            abort(403)

        # ----------------------------------------------------
        # TEACHER BRANCH
        # ----------------------------------------------------

        if (
            teacher.branch_id
            != result.branch_id
        ):
            abort(403)

    # ========================================================
    # RELATED DATA
    # ========================================================

    student = getattr(
        result,
        "student",
        None
    )

    exam = getattr(
        result,
        "exam",
        None
    )

    enrollment = getattr(
        result,
        "student_enrollment",
        None
    )

    institution = getattr(
        result,
        "institution",
        None
    )

    branch = getattr(
        result,
        "branch",
        None
    )

    program = getattr(
        result,
        "program",
        None
    )

    academic_year = getattr(
        result,
        "academic_year",
        None
    )

    term = getattr(
        result,
        "term",
        None
    )

    selected_class = getattr(
        result,
        "class_",
        None
    )

    section = getattr(
        result,
        "section",
        None
    )

    if not student:

        flash(
            "The student connected to this result was not found.",
            "danger"
        )

        return redirect(
            url_for("main.exam_results")
        )

    if not exam:

        flash(
            "The examination connected to this result was not found.",
            "danger"
        )

        return redirect(
            url_for("main.exam_results")
        )

    # ========================================================
    # GET EXAM SUBJECTS
    # ========================================================

    exam_subjects = (
        ExamSubject.query
        .filter(
            ExamSubject.exam_id == exam.id
        )
        .order_by(
            ExamSubject.id.asc()
        )
        .all()
    )

    # ========================================================
    # GET STUDENT MARKS
    # ========================================================

    exam_subject_ids = [
        exam_subject.id
        for exam_subject in exam_subjects
    ]

    marks_by_exam_subject = {}

    if exam_subject_ids:

        marks = (
            Mark.query
            .filter(
                Mark.exam_subject_id.in_(
                    exam_subject_ids
                ),
                Mark.student_id == student.id
            )
            .all()
        )

        marks_by_exam_subject = {
            mark.exam_subject_id: mark
            for mark in marks
        }

    # ========================================================
    # PREPARE SUBJECT RESULTS
    # ========================================================

    subject_results = []

    for exam_subject in exam_subjects:

        subject = getattr(
            exam_subject,
            "subject",
            None
        )

        mark = marks_by_exam_subject.get(
            exam_subject.id
        )

        # ----------------------------------------------------
        # MAX MARKS
        # ----------------------------------------------------

        max_marks = to_decimal(
            getattr(
                exam_subject,
                "max_marks",
                None
            )
        )

        if max_marks <= 0:

            max_marks = to_decimal(
                getattr(
                    subject,
                    "max_marks",
                    100
                )
            )

        # ----------------------------------------------------
        # MARK
        # ----------------------------------------------------

        marks_obtained = None

        if mark:

            marks_obtained = (
                mark.marks_obtained
            )

        # ----------------------------------------------------
        # ABSENT / EXEMPTED
        # ----------------------------------------------------

        is_absent = (
            mark.is_absent
            if mark
            else False
        )

        is_exempted = (
            mark.is_exempted
            if mark
            else False
        )

        # ----------------------------------------------------
        # SUBJECT PERCENTAGE / GRADE
        # ----------------------------------------------------

        subject_percentage = None
        subject_grade = "-"

        if (
            mark
            and not is_absent
            and not is_exempted
            and marks_obtained is not None
            and max_marks > 0
        ):

            subject_percentage = (
                to_decimal(marks_obtained)
                / max_marks
            ) * Decimal("100")

            subject_percentage = (
                subject_percentage.quantize(
                    Decimal("0.01"),
                    rounding=ROUND_HALF_UP
                )
            )

            subject_grade = calculate_grade(
                subject_percentage
            )

        # ----------------------------------------------------
        # PASS MARKS
        # ----------------------------------------------------

        pass_marks = to_decimal(
            getattr(
                exam_subject,
                "pass_marks",
                None
            )
        )

        if pass_marks <= 0:

            pass_marks = to_decimal(
                getattr(
                    subject,
                    "pass_marks",
                    50
                )
            )

        # ----------------------------------------------------
        # SUBJECT RESULT STATUS
        # ----------------------------------------------------

        if not mark:

            subject_status = "Not Entered"

        elif is_absent:

            subject_status = "Absent"

        elif is_exempted:

            subject_status = "Exempted"

        elif marks_obtained is None:

            subject_status = "Incomplete"

        elif to_decimal(
            marks_obtained
        ) >= pass_marks:

            subject_status = "Pass"

        else:

            subject_status = "Fail"

        # ----------------------------------------------------
        # APPEND
        # ----------------------------------------------------

        subject_results.append({

            "exam_subject": exam_subject,

            "subject": subject,

            "mark": mark,

            "marks_obtained": marks_obtained,

            "max_marks": max_marks,

            "pass_marks": pass_marks,

            "percentage": subject_percentage,

            "grade": subject_grade,

            "is_absent": is_absent,

            "is_exempted": is_exempted,

            "status": subject_status,

            "remarks": (
                mark.remarks
                if mark
                else None
            ),

        })

    # ========================================================
    # RENDER
    # ========================================================

    return render_template(
        "backend/pages/results/view_exam_result.html",

        # ----------------------------------------------------
        # RESULT
        # ----------------------------------------------------

        result=result,

        # ----------------------------------------------------
        # STUDENT
        # ----------------------------------------------------

        student=student,

        # ----------------------------------------------------
        # EXAM
        # ----------------------------------------------------

        exam=exam,

        exam_subjects=exam_subjects,

        subject_results=subject_results,

        # ----------------------------------------------------
        # ACADEMIC STRUCTURE
        # ----------------------------------------------------

        enrollment=enrollment,

        institution=institution,

        branch=branch,

        program=program,

        academic_year=academic_year,

        term=term,

        selected_class=selected_class,

        section=section,
        user=current_user,

        # ----------------------------------------------------
        # CALCULATED RESULT VALUES
        # ----------------------------------------------------

        total_marks=(
            getattr(
                result,
                "total_marks",
                0
            )
            or 0
        ),

        total_possible_marks=(
            getattr(
                result,
                "total_possible_marks",
                0
            )
            or 0
        ),

        percentage=(
            getattr(
                result,
                "percentage",
                0
            )
            or 0
        ),

        average=(
            getattr(
                result,
                "average",
                0
            )
            or 0
        ),

        grade=(
            getattr(
                result,
                "grade",
                "-"
            )
            or "-"
        ),

        gpa=(
            getattr(
                result,
                "gpa",
                0
            )
            or 0
        ),

        result_status=(
            getattr(
                result,
                "result_status",
                "incomplete"
            )
            or "incomplete"
        ),

        status=(
            getattr(
                result,
                "status",
                "draft"
            )
            or "draft"
        ),

        # ----------------------------------------------------
        # SUBJECT COUNTS
        # ----------------------------------------------------

        subjects_total=(
            getattr(
                result,
                "subjects_total",
                0
            )
            or 0
        ),

        subjects_completed=(
            getattr(
                result,
                "subjects_completed",
                0
            )
            or 0
        ),

        subjects_failed=(
            getattr(
                result,
                "subjects_failed",
                0
            )
            or 0
        ),

        # ----------------------------------------------------
        # RANKINGS
        # ----------------------------------------------------

        institution_position=(
            getattr(
                result,
                "institution_position",
                None
            )
        ),

        branch_position=(
            getattr(
                result,
                "branch_position",
                None
            )
        ),

        program_position=(
            getattr(
                result,
                "program_position",
                None
            )
        ),

        class_position=(
            getattr(
                result,
                "class_position",
                None
            )
        ),

        section_position=(
            getattr(
                result,
                "section_position",
                None
            )
        ),

        # ----------------------------------------------------
        # REMARKS
        # ----------------------------------------------------

        remarks=(
            getattr(
                result,
                "remarks",
                ""
            )
            or ""
        ),
    )



# ============================================================
# ADD / ENTER EXAM RESULT MARKS
# ADMIN ONLY
#
# FEATURES
# ------------------------------------------------------------
# - Dynamic exam selection
# - Dynamic scope
# - Class
# - Section
# - All Students
# - All Program
# - Dynamic student list
# - Only incomplete students
# - Student name sorted ASC
# - Missing subjects only
# - Mark / Absent / Exempted / Remark
# - Same student after Save
# - Dynamic Previous / Next student
# - No redirect to exam-results list
# - StudentResult recalculated
# - Rankings recalculated
# - Draft / Ongoing / Published exams
# ============================================================

@bp.route(
    "/exam-results/add",
    methods=["GET", "POST"]
)
@login_required
def add_exam_result():

    # ========================================================
    # SECURITY / ROLE
    # ========================================================

    role = getattr(
        current_user,
        "role",
        None
    )

    role = getattr(
        role,
        "value",
        role
    )

    role = (
        str(role).strip().lower()
        if role
        else None
    )

    allowed_roles = {
        "superadmin",
        "school_admin",
        "branch_admin",
    }

    if role not in allowed_roles:
        abort(403)

    # ========================================================
    # USER SCOPE
    # ========================================================

    current_institution_id = getattr(
        current_user,
        "institution_id",
        None
    )

    current_branch_id = getattr(
        current_user,
        "branch_id",
        None
    )

    # ========================================================
    # HELPERS
    # ========================================================

    def to_int(value):

        if value is None:
            return None

        try:
            value = str(value).strip()

            if not value:
                return None

            return int(value)

        except (
            ValueError,
            TypeError,
        ):
            return None

    def request_value(
        name,
        aliases=None,
        default=None,
    ):

        aliases = aliases or []

        names = [
            name,
            *aliases,
        ]

        # ----------------------------------------------------
        # POST
        # ----------------------------------------------------

        if request.method == "POST":

            for field_name in names:

                value = request.form.get(
                    field_name
                )

                if value is not None:

                    value = str(
                        value
                    ).strip()

                    if value:
                        return value

        # ----------------------------------------------------
        # GET
        # ----------------------------------------------------

        for field_name in names:

            value = request.args.get(
                field_name
            )

            if value is not None:

                value = str(
                    value
                ).strip()

                if value:
                    return value

        return default

    def normalize_status(value):

        value = getattr(
            value,
            "value",
            value
        )

        return (
            str(value).strip().lower()
            if value
            else ""
        )

    # ========================================================
    # REQUEST VALUES
    # ========================================================

    exam_id = to_int(
        request_value(
            "exam_id",
            aliases=[
                "selected_exam_id",
            ]
        )
    )

    student_id = to_int(
        request_value(
            "student_id",
            aliases=[
                "selected_student_id",
                "student",
                "student_select",
            ]
        )
    )

    scope_type = request_value(
        "scope_type",
        aliases=[
            "student_scope",
            "scope",
        ]
    )

    if scope_type:

        scope_type = (
            str(scope_type)
            .strip()
            .lower()
        )

    allowed_scopes = {
        "class",
        "section",
        "all_students",
        "all_program",
    }

    if scope_type not in allowed_scopes:
        scope_type = None

    class_id = to_int(
        request_value(
            "class_id",
            aliases=[
                "selected_class_id",
            ]
        )
    )

    section_id = to_int(
        request_value(
            "section_id",
            aliases=[
                "selected_section_id",
            ]
        )
    )

    program_id = to_int(
        request_value(
            "program_id",
            aliases=[
                "selected_program_id",
            ]
        )
    )

    # ========================================================
    # NAVIGATION
    # ========================================================

    navigation = request_value(
        "navigation",
        aliases=[
            "student_navigation",
        ]
    )

    # ========================================================
    # EXAMS
    # ========================================================

    exams_query = Exam.query

    if role == "school_admin":

        if not current_institution_id:
            abort(403)

        exams_query = exams_query.filter(
            Exam.institution_id
            == current_institution_id
        )

    elif role == "branch_admin":

        if (
            not current_institution_id
            or not current_branch_id
        ):
            abort(403)

        exams_query = exams_query.filter(
            Exam.institution_id
            == current_institution_id,
            Exam.branch_id
            == current_branch_id,
        )

    exams = (
        exams_query
        .order_by(
            Exam.id.desc()
        )
        .all()
    )

    # ========================================================
    # SELECTED EXAM
    # ========================================================

    exam = None

    if exam_id:

        exam_query = Exam.query

        if role == "school_admin":

            exam_query = exam_query.filter(
                Exam.institution_id
                == current_institution_id
            )

        elif role == "branch_admin":

            exam_query = exam_query.filter(
                Exam.institution_id
                == current_institution_id,
                Exam.branch_id
                == current_branch_id,
            )

        exam = (
            exam_query
            .filter(
                Exam.id == exam_id
            )
            .first()
        )

        if not exam:

            flash(
                "The selected examination was not found or is outside your access scope.",
                "error"
            )

            return redirect(
                url_for(
                    "main.add_exam_result"
                )
            )

    # ========================================================
    # EXAM STATUS
    # ========================================================

    if exam:

        exam_status = normalize_status(
            getattr(
                exam,
                "status",
                None
            )
        )

        if exam_status not in {
            "draft",
            "ongoing",
            "published",
        }:

            flash(
                "Marks can only be entered for draft, ongoing, or published examinations.",
                "error"
            )

            return redirect(
                url_for(
                    "main.add_exam_result"
                )
            )

    # ========================================================
    # EXAM SUBJECTS
    # ========================================================

    exam_subjects = []

    if exam:

        exam_subjects = (
            ExamSubject.query
            .options(
                db.joinedload(
                    ExamSubject.subject
                ),
                db.joinedload(
                    ExamSubject.teacher
                ),
            )
            .filter(
                ExamSubject.exam_id
                == exam.id
            )
            .order_by(
                ExamSubject.id.asc()
            )
            .all()
        )

    # ========================================================
    # PROGRAMS
    # ========================================================

    programs = []

    if exam:

        programs_query = (
            Program.query
            .filter(
                Program.institution_id
                == exam.institution_id
            )
        )

        programs = (
            programs_query
            .order_by(
                db.func.lower(
                    Program.name
                ).asc()
            )
            .all()
        )

    # ========================================================
    # CLASSES
    # ========================================================

    classes = []

    if exam:

        classes_query = (
            Class.query
            .filter(
                Class.institution_id
                == exam.institution_id,
                Class.branch_id
                == exam.branch_id,
                Class.academic_year_id
                == exam.academic_year_id,
            )
        )

        # ----------------------------------------------------
        # If exam has a program, show only that program's
        # classes.
        # ----------------------------------------------------

        if getattr(
            exam,
            "program_id",
            None
        ):

            classes_query = (
                classes_query
                .filter(
                    Class.program_id
                    == exam.program_id
                )
            )

        classes = (
            classes_query
            .order_by(
                db.func.lower(
                    Class.name
                ).asc()
            )
            .all()
        )

    # ========================================================
    # SECTIONS
    # ========================================================

    sections = []

    if exam:

        sections_query = (
            Section.query
            .filter(
                Section.institution_id
                == exam.institution_id,
                Section.branch_id
                == exam.branch_id,
                Section.academic_year_id
                == exam.academic_year_id,
            )
        )

        if class_id:

            sections_query = (
                sections_query
                .filter(
                    Section.class_id
                    == class_id
                )
            )

        sections = (
            sections_query
            .order_by(
                db.func.lower(
                    Section.name
                ).asc()
            )
            .all()
        )

    # ========================================================
    # POST
    # ========================================================

    if request.method == "POST":

        try:

            # =================================================
            # EXAM
            # =================================================

            if not exam:

                raise ValueError(
                    "Please select an examination."
                )

            # =================================================
            # SUBJECTS
            # =================================================

            if not exam_subjects:

                raise ValueError(
                    "This examination has no subjects assigned."
                )

            # =================================================
            # SCOPE
            # =================================================

            if not scope_type:

                raise ValueError(
                    "Please select a student scope."
                )

            if scope_type not in allowed_scopes:

                raise ValueError(
                    "Invalid student scope selected."
                )

            # =================================================
            # IMPORTANT:
            # CLEAR UNUSED SCOPE VALUES
            #
            # This prevents old class values from interfering
            # when switching between Section / All Students /
            # All Program.
            # =================================================

            if scope_type == "class":

                if not class_id:

                    raise ValueError(
                        "Please select a class."
                    )

                section_id = None
                program_id = None

            elif scope_type == "section":

                if not section_id:

                    raise ValueError(
                        "Please select a section."
                    )

                class_id = None
                program_id = None

            elif scope_type == "all_students":

                class_id = None
                section_id = None
                program_id = None

            elif scope_type == "all_program":

                if not program_id:

                    raise ValueError(
                        "Please select a program."
                    )

                class_id = None
                section_id = None

            # =================================================
            # VALIDATE CLASS
            # =================================================

            selected_class = None

            if scope_type == "class":

                selected_class = (
                    Class.query
                    .filter(
                        Class.id
                        == class_id,
                        Class.institution_id
                        == exam.institution_id,
                        Class.branch_id
                        == exam.branch_id,
                        Class.academic_year_id
                        == exam.academic_year_id,
                    )
                    .first()
                )

                if not selected_class:

                    raise ValueError(
                        "Selected class does not belong to this examination."
                    )

                if (
                    exam.program_id
                    and selected_class.program_id
                    != exam.program_id
                ):

                    raise ValueError(
                        "Selected class does not belong to the examination program."
                    )

            # =================================================
            # VALIDATE SECTION
            # =================================================

            selected_section = None

            if scope_type == "section":

                selected_section = (
                    Section.query
                    .filter(
                        Section.id
                        == section_id,
                        Section.institution_id
                        == exam.institution_id,
                        Section.branch_id
                        == exam.branch_id,
                        Section.academic_year_id
                        == exam.academic_year_id,
                    )
                    .first()
                )

                if not selected_section:

                    raise ValueError(
                        "Selected section does not belong to this examination."
                    )

                # ---------------------------------------------
                # Validate section's class
                # ---------------------------------------------

                section_class = (
                    Class.query
                    .filter(
                        Class.id
                        == selected_section.class_id,
                        Class.institution_id
                        == exam.institution_id,
                        Class.branch_id
                        == exam.branch_id,
                        Class.academic_year_id
                        == exam.academic_year_id,
                    )
                    .first()
                )

                if not section_class:

                    raise ValueError(
                        "The selected section is not connected to a valid class."
                    )

                if (
                    exam.program_id
                    and section_class.program_id
                    != exam.program_id
                ):

                    raise ValueError(
                        "Selected section does not belong to the examination program."
                    )

            # =================================================
            # VALIDATE PROGRAM
            # =================================================

            selected_program = None

            if scope_type == "all_program":

                selected_program = (
                    Program.query
                    .filter(
                        Program.id
                        == program_id,
                        Program.institution_id
                        == exam.institution_id,
                    )
                    .first()
                )

                if not selected_program:

                    raise ValueError(
                        "Selected program does not belong to this institution."
                    )

                if (
                    exam.program_id
                    and program_id
                    != exam.program_id
                ):

                    raise ValueError(
                        "Selected program does not match the examination program."
                    )

            # =================================================
            # STUDENT REQUIRED
            # =================================================

            if not student_id:

                raise ValueError(
                    "Please select a student."
                )

            # =================================================
            # STUDENT
            # =================================================

            student = (
                Student.query
                .filter(
                    Student.id
                    == student_id,
                    Student.institution_id
                    == exam.institution_id,
                    Student.branch_id
                    == exam.branch_id,
                )
                .first()
            )

            if not student:

                raise ValueError(
                    "Selected student was not found in this examination branch."
                )

            # =================================================
            # ENROLLMENT
            # =================================================

            enrollment = (
                StudentEnrollment.query
                .filter(
                    StudentEnrollment.student_id
                    == student.id,
                    StudentEnrollment.academic_year_id
                    == exam.academic_year_id,
                )
                .order_by(
                    StudentEnrollment.id.desc()
                )
                .first()
            )

            if not enrollment:

                raise ValueError(
                    "The selected student has no enrollment for this exam academic year."
                )

            # =================================================
            # ENROLLMENT BRANCH
            # =================================================

            enrollment_branch_id = getattr(
                enrollment,
                "branch_id",
                None
            )

            if (
                enrollment_branch_id
                and enrollment_branch_id
                != exam.branch_id
            ):

                raise ValueError(
                    "The selected student does not belong to this exam branch."
                )

            # =================================================
            # ENROLLMENT INSTITUTION
            # =================================================

            enrollment_institution_id = getattr(
                enrollment,
                "institution_id",
                None
            )

            if (
                enrollment_institution_id
                and enrollment_institution_id
                != exam.institution_id
            ):

                raise ValueError(
                    "The selected student enrollment does not belong to this institution."
                )

            # =================================================
            # ENROLLMENT STATUS
            # =================================================

            enrollment_status = normalize_status(
                getattr(
                    enrollment,
                    "status",
                    None
                )
            )

            if enrollment_status and enrollment_status not in {
                "active",
                "enrolled",
            }:

                raise ValueError(
                    "The selected student is not actively enrolled for this academic year."
                )

            # =================================================
            # PROGRAM VALIDATION
            # =================================================

            enrollment_program_id = getattr(
                enrollment,
                "program_id",
                None
            )

            if (
                exam.program_id
                and enrollment_program_id
                != exam.program_id
            ):

                raise ValueError(
                    "The selected student does not belong to the program assigned to this examination."
                )

            # =================================================
            # SCOPE VALIDATION
            # =================================================

            enrollment_class_id = getattr(
                enrollment,
                "class_id",
                None
            )

            enrollment_section_id = getattr(
                enrollment,
                "section_id",
                None
            )

            # -------------------------------------------------
            # CLASS
            # -------------------------------------------------

            if (
                scope_type == "class"
                and enrollment_class_id
                != class_id
            ):

                raise ValueError(
                    "The selected student does not belong to the selected class."
                )

            # -------------------------------------------------
            # SECTION
            # -------------------------------------------------

            if (
                scope_type == "section"
                and enrollment_section_id
                != section_id
            ):

                raise ValueError(
                    "The selected student does not belong to the selected section."
                )

            # -------------------------------------------------
            # PROGRAM
            # -------------------------------------------------

            if (
                scope_type == "all_program"
                and enrollment_program_id
                != program_id
            ):

                raise ValueError(
                    "The selected student does not belong to the selected program."
                )

            # =================================================
            # EXISTING MARKS
            # =================================================

            exam_subject_ids = [
                item.id
                for item in exam_subjects
            ]

            existing_marks = (
                Mark.query
                .filter(
                    Mark.student_id
                    == student.id,
                    Mark.exam_subject_id.in_(
                        exam_subject_ids
                    )
                )
                .all()
            )

            mark_map = {
                mark.exam_subject_id: mark
                for mark in existing_marks
            }

            # =================================================
            # PROCESS MARKS
            # =================================================

            changed_any = False

            for exam_subject in exam_subjects:

                exam_subject_id = (
                    exam_subject.id
                )

                subject = getattr(
                    exam_subject,
                    "subject",
                    None
                )

                subject_name = (
                    getattr(
                        subject,
                        "name",
                        None
                    )
                    or getattr(
                        subject,
                        "title",
                        None
                    )
                    or "Subject"
                )

                mark_field = (
                    f"mark_{exam_subject_id}"
                )

                absent_field = (
                    f"absent_{exam_subject_id}"
                )

                exempted_field = (
                    f"exempted_{exam_subject_id}"
                )

                remark_field = (
                    f"remark_{exam_subject_id}"
                )

                raw_marks = request.form.get(
                    mark_field,
                    ""
                )

                raw_marks = (
                    raw_marks.strip()
                    if raw_marks
                    else ""
                )

                is_absent = (
                    request.form.get(
                        absent_field
                    ) == "1"
                )

                is_exempted = (
                    request.form.get(
                        exempted_field
                    ) == "1"
                )

                subject_remark = request.form.get(
                    remark_field,
                    ""
                )

                subject_remark = (
                    subject_remark.strip()
                    if subject_remark
                    else ""
                )

                # =================================================
                # BOTH ABSENT + EXEMPTED
                # =================================================

                if (
                    is_absent
                    and is_exempted
                ):

                    raise ValueError(
                        f"{subject_name}: "
                        "A subject cannot be both absent and exempted."
                    )

                # =================================================
                # EMPTY
                # =================================================

                if (
                    not raw_marks
                    and not is_absent
                    and not is_exempted
                ):

                    continue

                mark = mark_map.get(
                    exam_subject_id
                )

                # =================================================
                # ABSENT
                # =================================================

                if is_absent:

                    if mark is None:

                        mark = Mark(
                            exam_subject_id=(
                                exam_subject_id
                            ),
                            student_id=student.id,
                            marks_obtained=None,
                            is_absent=True,
                            is_exempted=False,
                            remarks=(
                                subject_remark
                                or None
                            ),
                            status="submitted",
                            entered_by=None,
                        )

                        db.session.add(mark)

                        mark_map[
                            exam_subject_id
                        ] = mark

                    else:

                        mark.marks_obtained = None
                        mark.is_absent = True
                        mark.is_exempted = False
                        mark.remarks = (
                            subject_remark
                            or None
                        )
                        mark.status = "submitted"

                    changed_any = True
                    continue

                # =================================================
                # EXEMPTED
                # =================================================

                if is_exempted:

                    if mark is None:

                        mark = Mark(
                            exam_subject_id=(
                                exam_subject_id
                            ),
                            student_id=student.id,
                            marks_obtained=None,
                            is_absent=False,
                            is_exempted=True,
                            remarks=(
                                subject_remark
                                or None
                            ),
                            status="submitted",
                            entered_by=None,
                        )

                        db.session.add(mark)

                        mark_map[
                            exam_subject_id
                        ] = mark

                    else:

                        mark.marks_obtained = None
                        mark.is_absent = False
                        mark.is_exempted = True
                        mark.remarks = (
                            subject_remark
                            or None
                        )
                        mark.status = "submitted"

                    changed_any = True
                    continue

                # =================================================
                # NORMAL MARK
                # =================================================

                try:

                    marks = Decimal(
                        raw_marks
                    )

                except (
                    InvalidOperation,
                    ValueError,
                    TypeError,
                ):

                    raise ValueError(
                        f"Invalid marks entered for {subject_name}."
                    )

                if not marks.is_finite():

                    raise ValueError(
                        f"Invalid marks entered for {subject_name}."
                    )

                if marks < Decimal("0"):

                    raise ValueError(
                        f"Marks cannot be negative for {subject_name}."
                    )

                max_marks = to_decimal(
                    exam_subject.max_marks,
                    Decimal("0")
                )

                if max_marks <= Decimal("0"):

                    raise ValueError(
                        f"Maximum marks are not configured correctly for {subject_name}."
                    )

                if marks > max_marks:

                    raise ValueError(
                        f"Marks for {subject_name} cannot exceed {max_marks}."
                    )

                # =================================================
                # CREATE
                # =================================================

                if mark is None:

                    mark = Mark(
                        exam_subject_id=(
                            exam_subject_id
                        ),
                        student_id=student.id,
                        marks_obtained=marks,
                        is_absent=False,
                        is_exempted=False,
                        remarks=(
                            subject_remark
                            or None
                        ),
                        status="submitted",
                        entered_by=None,
                    )

                    db.session.add(mark)

                    mark_map[
                        exam_subject_id
                    ] = mark

                # =================================================
                # UPDATE
                # =================================================

                else:

                    mark.marks_obtained = marks
                    mark.is_absent = False
                    mark.is_exempted = False
                    mark.remarks = (
                        subject_remark
                        or None
                    )
                    mark.status = "submitted"

                changed_any = True

            # =================================================
            # NOTHING ENTERED
            # =================================================

            if not changed_any:

                raise ValueError(
                    "Please enter at least one subject mark, absent status, or exempted status."
                )

            # =================================================
            # SAVE MARKS
            # =================================================

            db.session.flush()

            # =================================================
            # PRESERVE EXISTING RESULT STATUS
            # =================================================

            old_result = (
                StudentResult.query
                .filter(
                    StudentResult.exam_id
                    == exam.id,
                    StudentResult.student_id
                    == student.id,
                )
                .first()
            )

            old_result_status = None

            if old_result:

                old_result_status = getattr(
                    old_result,
                    "status",
                    None
                )

            # =================================================
            # CALCULATE RESULT
            # =================================================

            calculated_result = (
                calculate_student_result(
                    exam,
                    student.id,
                    exam.institution_id,
                    exam.branch_id,
                )
            )

            if calculated_result is None:

                raise RuntimeError(
                    "Student result calculation did not return a result."
                )

            db.session.flush()

            # =================================================
            # RESTORE WORKFLOW STATUS
            # =================================================

            saved_result = (
                StudentResult.query
                .filter(
                    StudentResult.exam_id
                    == exam.id,
                    StudentResult.student_id
                    == student.id,
                )
                .first()
            )

            if saved_result:

                if old_result_status:

                    saved_result.status = (
                        old_result_status
                    )

                elif not getattr(
                    saved_result,
                    "status",
                    None
                ):

                    saved_result.status = "draft"

            # =================================================
            # RANKINGS
            # =================================================

            calculate_exam_rankings(
                exam.id,
                exam.institution_id,
                exam.branch_id,
            )

            db.session.flush()

            # =================================================
            # COMMIT
            # =================================================

            db.session.commit()

            # =================================================
            # SUCCESS
            # =================================================

            flash(
                f"Marks for {getattr(student, 'full_name', 'student')} were saved successfully.",
                "success"
            )

            # =================================================
            # SAME STUDENT
            # =================================================

            return redirect(
                url_for(
                    "main.add_exam_result",
                    exam_id=exam.id,
                    scope_type=scope_type,
                    class_id=class_id,
                    section_id=section_id,
                    program_id=program_id,
                    student_id=student.id,
                )
            )

        # ====================================================
        # VALIDATION ERROR
        # ====================================================

        except ValueError as exc:

            db.session.rollback()

            flash(
                str(exc),
                "error"
            )

        # ====================================================
        # DATABASE / UNEXPECTED ERROR
        # ====================================================

        except Exception:

            db.session.rollback()

            current_app.logger.exception(
                "ADD EXAM RESULT FAILED | "
                "exam_id=%s | "
                "student_id=%s | "
                "scope=%s | "
                "class=%s | "
                "section=%s | "
                "program=%s",
                exam_id,
                student_id,
                scope_type,
                class_id,
                section_id,
                program_id,
            )

            flash(
                "Unable to save the exam result. "
                "The update was rolled back. "
                "Please check the server console for the exact error.",
                "error"
            )

    # ========================================================
    # BUILD DYNAMIC STUDENT LIST
    # ========================================================

    students = []

    if (
        exam
        and scope_type in allowed_scopes
    ):

        enrollment_query = (
            StudentEnrollment.query
            .join(
                Student,
                Student.id
                == StudentEnrollment.student_id
            )
            .filter(
                StudentEnrollment.academic_year_id
                == exam.academic_year_id,
                StudentEnrollment.branch_id
                == exam.branch_id,
                Student.institution_id
                == exam.institution_id,
                Student.branch_id
                == exam.branch_id,
            )
        )

        # ====================================================
        # EXAM PROGRAM
        # ====================================================

        if exam.program_id:

            enrollment_query = (
                enrollment_query
                .filter(
                    StudentEnrollment.program_id
                    == exam.program_id
                )
            )

        # ====================================================
        # CLASS
        # ====================================================

        if scope_type == "class":

            if class_id:

                enrollment_query = (
                    enrollment_query
                    .filter(
                        StudentEnrollment.class_id
                        == class_id
                    )
                )
            else:

                # No class selected = no students.
                enrollment_query = (
                    enrollment_query
                    .filter(
                        db.literal(False)
                    )
                )

        # ====================================================
        # SECTION
        # ====================================================

        elif scope_type == "section":

            if section_id:

                enrollment_query = (
                    enrollment_query
                    .filter(
                        StudentEnrollment.section_id
                        == section_id
                    )
                )
            else:

                enrollment_query = (
                    enrollment_query
                    .filter(
                        db.literal(False)
                    )
                )

        # ====================================================
        # ALL PROGRAM
        # ====================================================

        elif scope_type == "all_program":

            if program_id:

                enrollment_query = (
                    enrollment_query
                    .filter(
                        StudentEnrollment.program_id
                        == program_id
                    )
                )
            else:

                enrollment_query = (
                    enrollment_query
                    .filter(
                        db.literal(False)
                    )
                )

        # ====================================================
        # ALL STUDENTS
        # ====================================================

        elif scope_type == "all_students":

            pass

        # ====================================================
        # ACTIVE ENROLLMENTS
        # ====================================================

        enrollment_status_column = getattr(
            StudentEnrollment,
            "status",
            None
        )

        if enrollment_status_column is not None:

            enrollment_query = (
                enrollment_query
                .filter(
                    db.func.lower(
                        enrollment_status_column
                    ).in_(
                        [
                            "active",
                            "enrolled",
                        ]
                    )
                )
            )

        # ====================================================
        # SORT NAME ASC
        # ====================================================

        enrollments = (
            enrollment_query
            .order_by(
                db.func.lower(
                    Student.full_name
                ).asc(),
                Student.id.asc()
            )
            .all()
        )

        # ====================================================
        # SUBJECT IDS
        # ====================================================

        exam_subject_ids = [
            item.id
            for item in exam_subjects
        ]

        # ====================================================
        # GET ALL MARKS IN ONE QUERY
        # ====================================================

        student_ids = [
            enrollment.student_id
            for enrollment in enrollments
            if getattr(
                enrollment,
                "student_id",
                None
            )
        ]

        all_marks = []

        if (
            student_ids
            and exam_subject_ids
        ):

            all_marks = (
                Mark.query
                .filter(
                    Mark.student_id.in_(
                        student_ids
                    ),
                    Mark.exam_subject_id.in_(
                        exam_subject_ids
                    ),
                )
                .all()
            )

        marks_by_student = {}

        for mark in all_marks:

            marks_by_student.setdefault(
                mark.student_id,
                {}
            )[
                mark.exam_subject_id
            ] = mark

        # ====================================================
        # BUILD LIST
        # ====================================================

        for enrollment in enrollments:

            student_obj = getattr(
                enrollment,
                "student",
                None
            )

            if not student_obj:
                continue

            student_mark_map = (
                marks_by_student.get(
                    student_obj.id,
                    {}
                )
            )

            missing_subject_ids = []

            for exam_subject in exam_subjects:

                mark = student_mark_map.get(
                    exam_subject.id
                )

                if mark is None:

                    missing_subject_ids.append(
                        exam_subject.id
                    )

                    continue

                if (
                    mark.marks_obtained is None
                    and not mark.is_absent
                    and not mark.is_exempted
                ):

                    missing_subject_ids.append(
                        exam_subject.id
                    )

            # ------------------------------------------------
            # COMPLETE STUDENTS ARE HIDDEN
            # ------------------------------------------------

            if (
                exam_subjects
                and not missing_subject_ids
            ):
                continue

            students.append({
                "student": student_obj,
                "enrollment": enrollment,
                "marks": student_mark_map,
                "missing_subject_ids": (
                    missing_subject_ids
                ),
                "missing_count": len(
                    missing_subject_ids
                ),
            })

    # ========================================================
    # SELECTED STUDENT
    # ========================================================

    selected_student = None
    selected_enrollment = None
    selected_subject_rows = []

    if (
        student_id
        and exam
    ):

        selected_student = (
            Student.query
            .filter(
                Student.id
                == student_id,
                Student.institution_id
                == exam.institution_id,
                Student.branch_id
                == exam.branch_id,
            )
            .first()
        )

        if selected_student:

            selected_enrollment = (
                StudentEnrollment.query
                .filter(
                    StudentEnrollment.student_id
                    == selected_student.id,
                    StudentEnrollment.academic_year_id
                    == exam.academic_year_id,
                    StudentEnrollment.branch_id
                    == exam.branch_id,
                )
                .order_by(
                    StudentEnrollment.id.desc()
                )
                .first()
            )

            # =================================================
            # LOAD MARKS
            # =================================================

            selected_mark_map = {}

            exam_subject_ids = [
                item.id
                for item in exam_subjects
            ]

            if exam_subject_ids:

                selected_marks = (
                    Mark.query
                    .filter(
                        Mark.student_id
                        == selected_student.id,
                        Mark.exam_subject_id.in_(
                            exam_subject_ids
                        )
                    )
                    .all()
                )

                selected_mark_map = {
                    mark.exam_subject_id: mark
                    for mark in selected_marks
                }

            # =================================================
            # ONLY MISSING SUBJECTS
            # =================================================

            for exam_subject in exam_subjects:

                mark = selected_mark_map.get(
                    exam_subject.id
                )

                is_missing = (
                    mark is None
                    or (
                        mark.marks_obtained is None
                        and not mark.is_absent
                        and not mark.is_exempted
                    )
                )

                if not is_missing:
                    continue

                subject = getattr(
                    exam_subject,
                    "subject",
                    None
                )

                subject_name = (
                    getattr(
                        subject,
                        "name",
                        None
                    )
                    or getattr(
                        subject,
                        "title",
                        None
                    )
                    or "Subject"
                )

                teacher = getattr(
                    exam_subject,
                    "teacher",
                    None
                )

                teacher_name = (
                    getattr(
                        teacher,
                        "full_name",
                        None
                    )
                    or "—"
                )

                selected_subject_rows.append({
                    "exam_subject": exam_subject,
                    "mark": mark,
                    "subject_name": subject_name,
                    "teacher_name": teacher_name,
                    "marks": (
                        mark.marks_obtained
                        if (
                            mark
                            and mark.marks_obtained
                            is not None
                        )
                        else None
                    ),
                    "max_marks": (
                        exam_subject.max_marks
                    ),
                    "pass_marks": (
                        exam_subject.pass_marks
                    ),
                    "is_absent": (
                        bool(mark.is_absent)
                        if mark
                        else False
                    ),
                    "is_exempted": (
                        bool(mark.is_exempted)
                        if mark
                        else False
                    ),
                    "is_missing": True,
                })

    # ========================================================
    # DYNAMIC NEXT / PREVIOUS
    # ========================================================

    current_student_index = None
    previous_student = None
    next_student = None

    student_objects = [
        item["student"]
        for item in students
    ]

    if student_id:

        for index, item_student in enumerate(
            student_objects
        ):

            if item_student.id == student_id:

                current_student_index = index
                break

    if current_student_index is not None:

        if current_student_index > 0:

            previous_student = (
                student_objects[
                    current_student_index - 1
                ]
            )

        if (
            current_student_index
            < len(student_objects) - 1
        ):

            next_student = (
                student_objects[
                    current_student_index + 1
                ]
            )

    # ========================================================
    # COUNTS
    # ========================================================

    total_students = len(
        students
    )

    missing_subject_count = sum(
        item["missing_count"]
        for item in students
    )

    selected_missing_count = len(
        selected_subject_rows
    )

    # ========================================================
    # RENDER
    # ========================================================

    return render_template(
        "backend/pages/results/add_exam_result.html",

        # ----------------------------------------------------
        # EXAMS
        # ----------------------------------------------------

        exams=exams,
        exam=exam,

        # ----------------------------------------------------
        # PROGRAMS / CLASSES / SECTIONS
        # ----------------------------------------------------

        programs=programs,
        classes=classes,
        sections=sections,

        # ----------------------------------------------------
        # CURRENT SELECTION
        # ----------------------------------------------------

        scope_type=scope_type,
        selected_class_id=class_id,
        selected_section_id=section_id,
        selected_program_id=program_id,
        selected_student_id=student_id,

        # ----------------------------------------------------
        # STUDENTS
        # ----------------------------------------------------

        students=students,
        total_students=total_students,
        missing_subject_count=missing_subject_count,

        # ----------------------------------------------------
        # SELECTED STUDENT
        # ----------------------------------------------------

        selected_student=selected_student,
        selected_enrollment=selected_enrollment,

        # ----------------------------------------------------
        # SUBJECTS
        # ----------------------------------------------------

        exam_subjects=exam_subjects,
        subject_rows=selected_subject_rows,
        selected_subject_rows=selected_subject_rows,
        selected_missing_count=selected_missing_count,

        # ----------------------------------------------------
        # NAVIGATION
        # ----------------------------------------------------

        current_student_index=current_student_index,
        previous_student=previous_student,
        next_student=next_student,

        # ----------------------------------------------------
        # PAGE
        # ----------------------------------------------------

        page_mode="add",
        can_edit_subject_marks=True,
        can_edit_workflow_status=False,

        # ----------------------------------------------------
        # USER
        # ----------------------------------------------------

        user=current_user,
    )

    






























#---------------------------------------
#---- Route: Ending |  Logout Sections ----
#---------------------------------------
@bp.route("/logout")
def logout():

    if current_user.is_authenticated:

        user = User.query.get(current_user.id)

        if user:
            user.auth_status = "logout"
            user.session_token = None
            user.last_seen = datetime.utcnow()

            try:
                db.session.commit()
            except Exception:
                db.session.rollback()
                current_app.logger.exception("Logout update error")

        logout_user()

        flash(
            "You have been logged out successfully.",
            "success"
        )

    else:

        flash(
            "You are already logged out.",
            "info"
        )

    return redirect(
        url_for("main.login")
    )


# ---------------------------------------
# ---- Route: Teacher Logout ------------
# ---------------------------------------

@bp.route("/teacher/logout")
def teacher_logout():

    # Get current teacher from session
    teacher_id = session.get("teacher_id")

    if teacher_id:

        teacher = Teacher.query.get(teacher_id)

        if teacher:
            teacher.last_active = datetime.utcnow()

            try:
                db.session.commit()

            except Exception:
                db.session.rollback()

                current_app.logger.exception(
                    "Teacher logout update error"
                )

        # IMPORTANT:
        # Remove ONLY teacher session data.
        # Do NOT use session.clear()
        # because Admin/User Flask-Login session
        # must remain untouched.

        session.pop("teacher_id", None)
        session.pop("teacher_role", None)
        session.pop("teacher_institution_id", None)
        session.pop("teacher_branch_id", None)

        flash(
            "You have been logged out successfully.",
            "success"
        )

    else:

        flash(
            "You are already logged out.",
            "info"
        )

    return redirect(
        url_for("main.teacher_login")
    )

    



